def _card_name_key(name: str) -> str:
    """Normalize card names for robust DB matching."""
    text = " ".join(str(name or "").strip().split())
    text = text.replace("||", "//")
    text = text.replace(" // ", "//")
    return text.lower()


# Keyword tokens we recognize in card rules text. Only ``go_again`` and
# ``dominate`` are mechanically simulated; the rest are surfaced for display
# and for requirement/bonus hooks.
_KEYWORD_PATTERNS: dict[str, str] = {
    "go_again": r"\bgo again\b",
    "dominate": r"\bdominate\b",
    "overpower": r"\boverpower\b",
    "intimidate": r"\bintimidate\b",
    "ward": r"\bward\b",
    "fusion": r"\bfusion\b",
    "battleworn": r"\bbattleworn\b",
    "blade_break": r"\bblade break\b",
    "arcane_barrier": r"\barcane barrier\b",
    "temper": r"\btemper\b",
}


def _derive_keywords(text: str) -> tuple[str, ...]:
    """Extract recognized FAB keywords from a card's rules text."""
    body = str(text or "").lower()
    if not body:
        return ()
    found = [kw for kw, pat in _KEYWORD_PATTERNS.items() if re.search(pat, body)]
    return tuple(found)


@functools.lru_cache(maxsize=4096)
def _reveal_requirement(text: str) -> tuple[Optional[str], bool]:
    """Parse a 'reveal a <X> card' clause from rules text.

    Returns ``(token, hard)`` where ``token`` is the required card descriptor
    (e.g. ``"lightning"``) and ``hard`` is True when the reveal is mandatory
    (no "you may" qualifier) rather than an optional bonus.
    """
    body = str(text or "").lower()
    match = re.search(r"reveal an?\s+([a-z]+)\s+card\s+from\s+(?:your\s+)?hand", body)
    if not match:
        return None, False
    token = match.group(1)
    pre = body[max(0, match.start() - 40):match.start()]
    # "you may reveal" / "Fusion - reveal" are optional bonuses, not gates.
    optional = "may" in pre or "fusion" in pre
    return token, not optional


@functools.lru_cache(maxsize=4096)
def _fusion_elements(text: str) -> tuple[str, ...]:
    """Return fusion element(s) required (e.g. ``('lightning',)`` or ``('earth', 'lightning')``)."""
    body = str(text or "").lower()
    m = re.search(r"((?:[a-z]+(?:\s+and\s+[a-z]+)*))\s+fusion\b", body)
    if m:
        chunk = m.group(1).strip()
        if " and " in chunk:
            return tuple(p.strip() for p in re.split(r"\s+and\s+", chunk) if p.strip())
        return (chunk,)
    m = re.search(r"\b([a-z]+)\s+fusion\b", body)
    return (m.group(1),) if m else ()


@functools.lru_cache(maxsize=4096)
def _fusion_element(text: str) -> Optional[str]:
    """Return the primary fusion element (back-compat helper)."""
    elements = _fusion_elements(text)
    return elements[0] if elements else None


@functools.lru_cache(maxsize=8192)
def _parse_action_damage(text: str, power: int, is_attack: bool) -> tuple[int, bool]:
    """Damage an action deals when played, and whether it is arcane.

    Attack actions use printed power (physical, blockable). Non-attack actions
    fall back to parsing a "deal N [arcane] damage" clause from rules text.
    """
    body = str(text or "").lower()
    if is_attack:
        return int(power or 0), False
    if power and power > 0:
        return int(power), "arcane" in body
    for match in re.finditer(r"deal (\d+)\s+(arcane\s+)?damage", body):
        start = max(body.rfind(".", 0, match.start()), body.rfind("{br}", 0, match.start()))
        if re.search(r"\bif\b", body[start:match.start()]):
            continue
        tail = body[match.start(): match.end() + 24]
        return int(match.group(1)), bool(match.group(2)) or "arcane damage" in tail
    return 0, False


_EQUIP_SLOTS: tuple[str, ...] = ("head", "chest", "arms", "legs")


def _equipment_slot(card: "Card") -> Optional[str]:
    """Return the gear slot ('head'/'chest'/'arms'/'legs') for an equipment card."""
    line = (card.type_line or "").lower()
    if "equipment" not in line:
        return None
    for slot in _EQUIP_SLOTS:
        if slot in line:
            return slot
    return None


def _load_cards() -> dict[str, Card]:
    if not _CARDS_PATH.exists():
        raise FileNotFoundError(f"Missing Flesh and Blood card DB at {_CARDS_PATH}")

    raw = json.loads(_CARDS_PATH.read_text(encoding="utf-8"))
    cards: dict[str, Card] = {}
    for rec in raw:
        text = rec.get("text", "")
        keywords = tuple(rec.get("keywords", [])) or _derive_keywords(text)
        card = Card(
            id=rec["id"],
            name=rec["name"],
            pitch=int(rec.get("pitch", 0)),
            cost=int(rec.get("cost", 0)),
            power=int(rec.get("power", 0)),
            defense=int(rec.get("defense", 0)),
            type_line=rec.get("type_line", ""),
            card_types=tuple(rec.get("card_types", [])),
            card_class=rec.get("class", "Generic"),
            talent=rec.get("talent"),
            rarity=rec.get("rarity", "Common"),
            set_code=rec.get("set", "SIM"),
            keywords=keywords,
            text=text,
            legality=rec.get("legality", {}),
        )
        cards[card.id] = card
    return cards


def _load_heroes() -> dict[str, Hero]:
    if not _HEROES_PATH.exists():
        raise FileNotFoundError(f"Missing Flesh and Blood hero DB at {_HEROES_PATH}")

    raw = json.loads(_HEROES_PATH.read_text(encoding="utf-8"))
    heroes: dict[str, Hero] = {}
    for rec in raw:
        weapon = rec.get("weapon", {})
        hero = Hero(
            id=rec["id"],
            name=rec["name"],
            hero_class=rec.get("class", "Generic"),
            talent=rec.get("talent"),
            life=int(rec.get("life", 40)),
            intellect=int(rec.get("intellect", 4)),
            weapon_name=weapon.get("name", "Basic Weapon"),
            weapon_attack=int(weapon.get("attack", 3)),
            weapon_cost=int(weapon.get("cost", 1)),
        )
        heroes[hero.id] = hero
    return heroes


class FleshAndBloodEnvironment(rlbridgeEnvironment):
    """Talishar-inspired RL simulator for Flesh and Blood gameplay loops."""

    def __init__(
        self,
        *,
        seed: Optional[int] = None,
        agent_hero_id: str = "hero_dorinthea_ironsong",
        opponent_hero_id: str = "hero_rhinar_reckless_rampage",
        max_turns: int = 60,
        deck_size: int = 36,
        agent_deck_style: str = "balanced",
        opponent_deck_style: str = "balanced",
        format: str = "classic_constructed",
        two_phase_deckbuild: bool = False,
        self_play: bool = False,
        opponent_type: str = "preset_logic",
        render_mode: Optional[str] = None,
    ) -> None:
        self._cards = _load_cards()
        self._token_name_index = token_defs.build_token_name_index(self._cards)
        self._heroes = _load_heroes()
        self._attach_hero_abilities()
        self._rng = random.Random(seed)

        if agent_hero_id not in self._heroes:
            raise ValueError(f"Unknown agent_hero_id: {agent_hero_id}")
        if opponent_hero_id not in self._heroes:
            raise ValueError(f"Unknown opponent_hero_id: {opponent_hero_id}")

        self._agent_hero_id = agent_hero_id
        self._opponent_hero_id = opponent_hero_id
        self._max_turns = max_turns
        self._deck_size = deck_size
        self._agent_deck_style = str(agent_deck_style)
        self._opponent_deck_style = str(opponent_deck_style)
        self._format = self._normalize_format(format)
        self._two_phase_deckbuild = bool(two_phase_deckbuild)

        self._players: list[PlayerState] = []
        self._turn = 0
        self._active_player = 0
        self._phase = "action"
        self._flow_stage = "p0_opening"
        self._combat_chain_links = 0
        self._action_phase_player = 0
        self._pending_combat: Optional[CombatState] = None
        self._initialized = False
        self._last_event = ""
        self._last_combat_summary: Optional[dict[str, Any]] = None
        # Optional callback fired right after every combat resolution with a dict
        # containing: combat, attacker_idx, defender_idx, total_power, total_block,
        # raw_damage, damage, defender_life_before.  Set by external tools (e.g.
        # TalisharOracle) — not used by the environment itself.
        self.on_combat_resolve: Optional[Any] = None
        self._last_opponent_turn: Optional[dict[str, Any]] = None
        self._notices: list[str] = []
        self._pending_optionals: list[dict[str, Any]] = []
        self._optional_resume: Optional[str] = None
        self._optional_ctx: dict[str, Any] = {}
        self._opt_ctx: dict[str, Any] = {}
        self._opt_resume: Optional[dict[str, Any]] = None
        self._choice_ctx: dict[str, Any] = {}
        self._choice_resume: Optional[str] = None
        self._pending_die_roll: Optional[dict[str, Any]] = None
        self._optional_post_ctx: dict[str, Any] = {}
        self._play_resume_ctx: dict[str, Any] = {}
        self._pending_instant_pay: dict[str, Any] = {}
        self._pending_pitch_pay: dict[str, Any] = {}
        self._render_mode = render_mode
        self._self_play = self_play
        self._opponent_type = self._normalize_opponent_type(opponent_type)
        self._opponent_policy = self._build_opponent_policy(self._opponent_type)
        self._selection_stage = False
        self._selected_deck_option: Optional[dict[str, Any]] = None
        self._selected_opponent_deck_option: Optional[dict[str, Any]] = None
        self._card_vault_cards_cache: Optional[list[dict[str, Any]]] = None
        self._stolen_until_phase_end: list[tuple[int, int, str]] = []
        self._play_restriction_kind: str = ""
        self._play_restriction_clear_at_turn: int = 0

    def reset(
        self,
        seed: Optional[int] = None,
        options: Optional[dict[str, Any]] = None,
    ) -> ResetResult:
        if seed is not None:
            self._rng.seed(seed)

        opts = options or {}
        self._agent_hero_id = str(opts.get("agent_hero_id", self._agent_hero_id))
        self._opponent_hero_id = str(opts.get("opponent_hero_id", self._opponent_hero_id))
        self._agent_deck_style = str(opts.get("agent_deck_style", self._agent_deck_style))
        self._opponent_deck_style = str(opts.get("opponent_deck_style", self._opponent_deck_style))
        self._format = self._normalize_format(str(opts.get("format", self._format)))
        self._two_phase_deckbuild = bool(opts.get("two_phase_deckbuild", self._two_phase_deckbuild))
        self._opponent_type = self._normalize_opponent_type(str(opts.get("opponent_type", self._opponent_type)))
        self._opponent_policy = self._build_opponent_policy(self._opponent_type)
        self._max_turns = int(opts.get("max_turns", self._max_turns))
        self._deck_size = int(opts.get("deck_size", self._deck_size))

        min_cards, max_cards = self._format_deck_bounds()
        self._deck_size = max(min_cards, min(self._deck_size, max_cards))

        self._pending_combat = None
        self._pending_instant_pay = {}
        self._pending_pitch_pay = {}
        self._selected_deck_option = None
        self._selected_opponent_deck_option = None

        if self._two_phase_deckbuild:
            self._players = []
            self._turn = 0
            self._active_player = 0
            self._phase = "deck_selection"
            self._selection_stage = True
            self._last_event = "Select a deck to begin the match"
        else:
            self._selection_stage = False
            self._start_match(
                agent_hero_id=self._agent_hero_id,
                opponent_hero_id=self._opponent_hero_id,
                agent_deck_style=self._agent_deck_style,
                opponent_deck_style=self._opponent_deck_style,
            )

        self._initialized = True
        return ResetResult(
            observation=self._observation(),
            info={
                "legal_actions": self._legal_actions(),
                "agent_hero": (self._players[0].hero.name if self._players else None),
                "opponent_hero": (self._players[1].hero.name if self._players else None),
                "format": self._format,
                "opponent_type": self._opponent_type,
                "stage": ("deck_selection" if self._selection_stage else "play"),
            },
        )

    def step(self, action: Any) -> StepResult:
        if not self._initialized:
            raise RuntimeError("Call reset() before step().")

        if self._selection_stage:
            legal = self._legal_actions()
            parsed = self._normalize_action(action)
            if parsed not in legal:
                if isinstance(action, int) and legal:
                    parsed = legal[action % len(legal)]
                else:
                    return StepResult(
                        observation=self._observation(),
                        reward=-0.1,
                        terminated=False,
                        truncated=False,
                        info={
                            "error": f"Illegal action {parsed!r}",
                            "legal_actions": legal,
                        },
                    )

            choice_key = parsed.split(" ", 1)[1]
            choice = next((o for o in self._deck_options_for_format() if o["key"] == choice_key), None)
            if choice is None:
                return StepResult(
                    observation=self._observation(),
                    reward=-0.1,
                    terminated=False,
                    truncated=False,
                    info={"error": f"Unknown deck option: {choice_key}", "legal_actions": legal},
                )

            self._selected_deck_option = dict(choice)
            self._agent_hero_id = str(choice["hero_id"])
            self._deck_size = int(choice["deck_size"])

            opp_choice = self._sample_opponent_matchup(agent_hero_id=self._agent_hero_id)
            self._selected_opponent_deck_option = dict(opp_choice)
            self._opponent_hero_id = str(opp_choice["hero_id"])

            self._selection_stage = False
            # Pass pre-resolved card IDs when a fabrary deck option was chosen.
            agent_card_ids: Optional[list[str]] = choice.get("_card_ids")  # type: ignore[assignment]
            opp_card_ids: Optional[list[str]] = opp_choice.get("_card_ids")  # type: ignore[assignment]
            self._start_match(
                agent_hero_id=self._agent_hero_id,
                opponent_hero_id=self._opponent_hero_id,
                agent_deck_style=str(choice["style"]),
                opponent_deck_style=str(opp_choice["style"]),
                agent_deck_ids=agent_card_ids,
                opponent_deck_ids=opp_card_ids,
            )
            self._last_event = f"Deck selected: {choice['label']} | Matchup: {opp_choice['label']}"

            info = {
                "legal_actions": self._legal_actions(),
                "phase": self._phase,
                "last_event": self._last_event,
                "turn": self._turn,
                "stage": "play",
            }
            return StepResult(
                observation=self._observation(),
                reward=0.0,
                terminated=False,
                truncated=False,
                info=info,
            )

        legal = self._legal_actions()
        parsed = self._normalize_action(action)
        if parsed not in legal:
            if legal == ["pass"]:
                # Only pass is legal - coerce so policies never deadlock.
                parsed = "pass"
            elif isinstance(action, int) and legal:
                # RL agents emit integer indices; treat them as indices into the
                # legal action list so out-of-range ints never get stuck.
                parsed = legal[action % len(legal)]
            else:
                return StepResult(
                    observation=self._observation(),
                    reward=-0.1,
                    terminated=False,
                    truncated=False,
                    info={
                        "error": f"Illegal action {parsed!r}",
                        "legal_actions": legal,
                    },
                )

        reward = 0.0
        self._notices = []

        if self._self_play:
            reward += self._step_self_play(parsed)
        else:
            if self._phase == "action":
                if parsed == "pass":
                    self._last_event = "Agent passed turn"
                    self._pass_action(0)
                elif parsed.startswith("pitch "):
                    reward += self._do_pitch(0, int(parsed.split(" ")[1]))
                elif parsed.startswith("play "):
                    reward += self._do_play_card(0, int(parsed.split(" ")[1]), 0)
                elif parsed.startswith("arsenalplay"):
                    reward += self._do_play_arsenal(0, 0)
                elif parsed.startswith("banishplay "):
                    reward += self._do_play_banished(0, int(parsed.split(" ")[1]), 0)
                elif parsed.startswith("gyplay "):
                    reward += self._do_play_graveyard(0, int(parsed.split(" ")[1]), 0)
                elif parsed == "weapon":
                    reward += self._do_weapon_attack(0, 0)
                elif parsed.startswith("ability "):
                    reward += self._do_ability(0, int(parsed.split(" ")[1]), 0)
                elif parsed.startswith("instant "):
                    reward += self._do_instant_play(0, int(parsed.split(" ")[1]), 0)
                elif parsed == "deckplay":
                    reward += self._do_play_deck_top(0, 0)
                elif parsed.startswith("mayplay "):
                    parts = parsed.split(" ")
                    reward += self._do_may_play(0, parts[1], int(parts[2]), 0)
            elif self._phase == "arsenal":
                if parsed == "pass":
                    self._pass_arsenal(0)
                elif parsed.startswith("stash "):
                    reward += self._do_stash(0, int(parsed.split(" ")[1]))
            elif self._phase == "defense":
                if self._active_player == 0:
                    if parsed == "pass":
                        self._pass_defense(0)
                    elif parsed.startswith("block "):
                        reward += self._do_block(0, int(parsed.split(" ")[1]))
                    elif parsed.startswith("blockgear "):
                        reward += self._do_block_gear(0, int(parsed.split(" ")[1]))
                    elif parsed == "trapdefend":
                        reward += self._do_trap_defend(0, 0)
                    else:
                        reward += self._agent_combat_instant_step(parsed, 0)
                elif parsed != "pass":
                    reward += self._agent_combat_instant_step(parsed, 0)
            elif self._phase == "attack_reaction":
                if self._active_player == 0:
                    if parsed == "pass":
                        self._pass_attack_reaction()
                    elif parsed.startswith("reaction "):
                        reward += self._do_reaction(0, int(parsed.split(" ")[1]))
                    else:
                        reward += self._agent_combat_instant_step(parsed, 0)
                elif parsed != "pass":
                    reward += self._agent_combat_instant_step(parsed, 0)
            elif self._phase == "defense_reaction":
                if self._active_player == 0:
                    if parsed == "pass":
                        reward += self._pass_defense_reaction(0)
                    elif parsed.startswith("defreact "):
                        reward += self._do_defense_reaction(0, int(parsed.split(" ")[1]))
                    else:
                        reward += self._agent_combat_instant_step(parsed, 0)
                elif parsed != "pass":
                    reward += self._agent_combat_instant_step(parsed, 0)
            elif self._phase == "optional":
                reward += self._do_optional(parsed == "use_optional")
            elif self._phase == "choice":
                if parsed == "pass":
                    reward += self._resolve_card_choice(None)
                elif parsed.startswith("choose "):
                    reward += self._resolve_card_choice(int(parsed.split()[1]))
            elif self._phase == "opt":
                if parsed == "opt_bottom":
                    self._do_opt_choice(0, to_bottom=True)
                elif parsed == "opt_top":
                    self._do_opt_choice(0, to_bottom=False)
            elif self._phase == "instant_pay":
                if parsed == "pass":
                    self._cancel_instant_pay()
                elif parsed.startswith("pitch "):
                    reward += self._do_pitch(0, int(parsed.split(" ")[1]))
            elif self._phase == "pitch_pay":
                if parsed == "pass":
                    reward += self._pass_pitch_pay()
                elif parsed.startswith("pitch "):
                    reward += self._do_pitch(0, int(parsed.split(" ")[1]))
            # Drive the scripted opponent until the agent must decide again.
            reward += self._auto_advance()

        terminated = self._is_terminal()
        truncated = self._turn >= self._max_turns and not terminated
        if truncated:
            self._last_event = "Reached max turns"

        # Terminal win/loss bonus (primary signal)
        if terminated:
            if self._self_play:
                # In self-play the acting player just caused termination;
                # reward from the perspective of the player whose life just hit 0.
                loser = next(i for i, p in enumerate(self._players) if p.life <= 0)
                winner = 1 - loser
                # Reward for the policy: +1 if the last acting player won, -1 if lost.
                if self._active_player == winner:
                    reward += 1.0
                else:
                    reward -= 1.0
            elif self._players[0].life <= 0:
                reward -= 1.0  # agent lost
            else:
                reward += 1.0  # agent won
        else:
            reward -= 0.005  # step penalty to discourage passive looping

        info = {
            "legal_actions": [] if (terminated or truncated) else self._legal_actions(),
            "phase": self._phase,
            "last_event": self._last_event,
            "turn": self._turn,
        }
        return StepResult(
            observation=self._observation(),
            reward=reward,
            terminated=terminated,
            truncated=truncated,
            info=info,
        )

    def close(self) -> None:
        self._players = []
        self._pending_combat = None
        self._initialized = False

    @property
    def observation_space(self) -> TextSpace:
        return TextSpace(min_length=0, max_length=16000)

    @property
    def action_space(self) -> TextSpace:
        return TextSpace(min_length=1, max_length=32)

    def sample_action(self) -> str:
        if not self._initialized:
            return "pass"
        if self._selection_stage:
            legal = self._legal_actions()
            return self._rng.choice(legal) if legal else "pass"
        if len(self._players) < 2:
            return "pass"
        legal = self._legal_actions()
        return self._rng.choice(legal) if legal else "pass"

    def render(self) -> RenderResult:
        if self._render_mode == "rgb_array":
            return self._render_rgb()
        return RenderResult(mode="ansi", text=self._render_text())

    def _render_rgb(self) -> RenderResult:
        try:
            from PIL import Image, ImageDraw, ImageFont
        except ImportError:
            return RenderResult(mode="rgb_array", text="pillow not installed")

        obs = self._observation()
        p_agent, p_opp = self._estimate_win_probabilities(obs)
        canvas_width, canvas_height = 1200, 720
        width, height = 1280, 720  # 720p output
        bg = (18, 24, 33)
        panel = (30, 40, 54)
        panel_alt = (41, 53, 69)
        accent = (245, 181, 82)
        fg = (240, 243, 248)
        sub = (176, 186, 201)
        enemy = (240, 103, 103)
        ally = (96, 214, 138)

        img = Image.new("RGB", (canvas_width, canvas_height), bg)
        draw = ImageDraw.Draw(img)

        try:
            font_title = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 28)
            font_subtitle = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 20)
            font_text = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 16)
            font_small = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 14)
        except Exception:
            font_title = ImageFont.load_default()
            font_subtitle = ImageFont.load_default()
            font_text = ImageFont.load_default()
            font_small = ImageFont.load_default()

        def _panel(x0: int, y0: int, x1: int, y1: int, fill: tuple[int, int, int]) -> None:
            draw.rounded_rectangle((x0, y0, x1, y1), radius=14, fill=fill)

        def _text(x: int, y: int, msg: str, font: Any, fill: tuple[int, int, int]) -> None:
            draw.text((x, y), msg, fill=fill, font=font)

        def _encode_image(image: Any) -> str:
            if image.size != (width, height):
                resampling = getattr(getattr(Image, "Resampling", Image), "LANCZOS")
                image = image.resize((width, height), resample=resampling)
            buf = BytesIO()
            image.save(buf, format="PNG")
            return base64.b64encode(buf.getvalue()).decode("ascii")

        if obs.get("stage") == "deck_selection":
            _text(24, 20, "Flesh and Blood (Talishar-inspired)", font_title, fg)
            _text(24, 58, f"Format: {obs['format']} | Stage: deck_selection", font_subtitle, sub)
            _panel(20, 100, 1180, 680, panel)
            _text(40, 128, "Choose a deck to start the episode", font_subtitle, accent)
            for i, item in enumerate(obs.get("deck_options", [])[:12]):
                _text(40, 170 + i * 34, f"[{i}] {item['label']} ({item['deck_size']} cards)", font_text, fg)
            legal = ", ".join(obs.get("legal_actions", [])[:12])
            _text(40, 640, f"Legal actions: {legal}", font_small, sub)
            b64 = _encode_image(img)
            return RenderResult(mode="rgb_array", data=b64, width=width, height=height)

        _text(24, 20, "Flesh and Blood (Talishar-inspired)", font_title, fg)
        _text(
            24,
            58,
            f"Turn {obs['turn']} | Format: {obs['format']} | Phase: {obs['phase']} | Active: P{obs['active_player']}",
            font_subtitle,
            sub,
        )

        _panel(20, 100, 580, 240, panel)
        _panel(620, 100, 1180, 240, panel)
        _panel(20, 260, 1180, 360, panel_alt)
        _panel(20, 380, 1180, 700, panel)

        agent = obs["agent"]
        opponent = obs["opponent"]

        _text(40, 120, "Agent", font_subtitle, ally)
        _text(40, 150, f"Hero: {agent['hero']}", font_text, fg)
        _text(40, 174, f"Life: {agent['life']}", font_text, fg)
        _text(220, 174, f"Resources: {agent['resources']}", font_text, fg)
        _text(440, 174, f"AP: {agent['action_points']}", font_text, fg)
        _text(40, 200, f"Deck: {agent['deck']}  Discard: {agent['discard']}", font_text, sub)
        _text(40, 224, f"Win %: {p_agent:.1%}", font_text, accent)

        _text(640, 120, "Opponent", font_subtitle, enemy)
        _text(640, 150, f"Hero: {opponent['hero']}", font_text, fg)
        _text(640, 174, f"Life: {opponent['life']}", font_text, fg)
        _text(820, 174, f"Resources: {opponent['resources']}", font_text, fg)
        _text(1040, 174, f"AP: {opponent['action_points']}", font_text, fg)
        _text(
            640,
            200,
            f"Deck: {opponent['deck']}  Discard: {opponent['discard']}  Hand: {opponent['hand_size']}",
            font_text,
            sub,
        )
        _text(640, 224, f"Win %: {p_opp:.1%}", font_text, accent)

        pending = obs.get("pending_combat")
        if pending:
            combat_line = (
                f"Combat | Attacker: P{pending['attacker']}  Defender: P{pending['defender']}  "
                f"{pending['attack_card']} ATK {pending['attack_power']}  BLOCK {pending['total_block']}"
            )
        else:
            combat_line = "Combat | none"
        _text(40, 292, combat_line, font_text, fg)
        _text(40, 320, f"Last event: {obs['last_event']}", font_text, sub)

        _text(40, 400, "Agent Hand", font_subtitle, accent)

        hand = agent["hand"]
        card_w, card_h = 215, 128
        cols = 5
        x_start = 40
        y_start = 432
        x_gap = 14
        y_gap = 12
        for idx, card in enumerate(hand[:15]):
            row = idx // cols
            col = idx % cols
            x0 = x_start + col * (card_w + x_gap)
            y0 = y_start + row * (card_h + y_gap)
            x1 = x0 + card_w
            y1 = y0 + card_h
            shade = panel_alt if idx % 2 == 0 else (36, 47, 62)
            draw.rounded_rectangle((x0, y0, x1, y1), radius=10, fill=shade)
            _text(x0 + 10, y0 + 8, f"[{card['index']}] {card['name'][:24]}", font_small, fg)
            _text(x0 + 10, y0 + 34, f"Cost {card['cost']}  ATK {card['power']}  DEF {card['defense']}", font_small, sub)
            ctype = ",".join(card.get("card_types", []))[:28]
            _text(x0 + 10, y0 + 58, f"Type: {ctype}", font_small, sub)
            keys = ",".join(card.get("keywords", [])) or "none"
            _text(x0 + 10, y0 + 82, f"Keywords: {keys[:24]}", font_small, sub)

        legal = ", ".join(obs.get("legal_actions", [])[:12])
        _text(40, 676, f"Legal actions: {legal}", font_small, sub)

        b64 = _encode_image(img)
        return RenderResult(mode="rgb_array", data=b64, width=width, height=height)

    def _new_player(self, hero: Hero, hero_slot: int, deck_style: str = "balanced", deck_ids: Optional[list[str]] = None) -> PlayerState:
        if deck_ids is not None:
            deck = list(deck_ids)
        else:
            deck = self._build_deck(hero, deck_style=deck_style)
        self._rng.shuffle(deck)
        return PlayerState(
            hero=hero,
            life=self._starting_life(hero),
            resources=0,
            action_points=0,
            deck=deck,
            hand=[],
            discard=[],
            equipment=self._select_equipment(hero),
            weapon_id=self._select_weapon(hero),
        )

    def _build_deck(self, hero: Hero, deck_style: str = "balanced") -> list[str]:
        candidates: list[Card] = []
        for card in self._cards.values():
            if not self._is_card_legal_for_format(card.id):
                continue
            if not self._is_card_compatible_with_hero(card, hero):
                continue
            if not self._is_deck_candidate(card):
                continue
            candidates.append(card)

        if not candidates:
            raise ValueError(f"No legal cards available for hero={hero.name!r} format={self._format}")

        if deck_style == "aggro":
            ranked = sorted(
                candidates,
                key=lambda c: (
                    1 if "attack_action" in c.card_types else 0,
                    c.power,
                    -c.cost,
                    c.defense,
                ),
                reverse=True,
            )
        elif deck_style == "control":
            ranked = sorted(
                candidates,
                key=lambda c: (
                    c.defense,
                    c.pitch,
                    1 if "defense_reaction" in c.card_types else 0,
                    1 if "attack_action" in c.card_types else 0,
                ),
                reverse=True,
            )
        else:
            ranked = sorted(
                candidates,
                key=lambda c: (
                    (c.power + c.defense),
                    c.pitch,
                    1 if "attack_action" in c.card_types else 0,
                ),
                reverse=True,
            )

        copy_limit = 2 if self._format == "silver_age" else 3
        deck: list[str] = []
        counts: dict[str, int] = {}

        def _fill_from(seq: list[Card], limit: int) -> None:
            for card in seq:
                if len(deck) >= limit:
                    break
                while counts.get(card.id, 0) < copy_limit and len(deck) < limit:
                    deck.append(card.id)
                    counts[card.id] = counts.get(card.id, 0) + 1

        # Reserve a share of the deck for combination cards so those
        # interactions actually come up instead of the deck filling with only
        # the highest-power vanilla attacks. Fusion gets its own quota because
        # it is lower-power and would otherwise always be crowded out.
        attack_ranked = sorted(
            [c for c in candidates if "attack_action" in c.card_types],
            key=lambda c: (c.power, -c.cost, c.defense),
            reverse=True,
        )
        min_attacks = {
            "aggro": max(28, int(self._deck_size * 0.65)),
            "control": max(18, int(self._deck_size * 0.4)),
        }.get(deck_style, max(20, int(self._deck_size * 0.45)))
        _fill_from(attack_ranked, min_attacks)

        fusion_ranked = [c for c in ranked if "fusion" in set(c.keywords)]
        bolt_ranked = [
            c
            for c in ranked
            if "fusion" not in set(c.keywords) and self._is_combo_candidate(c)
        ]
        if fusion_ranked:
            _fill_from(fusion_ranked, int(self._deck_size * 0.2))
        if bolt_ranked:
            _fill_from(bolt_ranked, int(self._deck_size * 0.3))
        _fill_from(ranked, self._deck_size)
        while len(deck) < self._deck_size:
            deck.append(self._rng.choice(ranked).id)

        return deck[: self._deck_size]

    def _is_combo_candidate(self, card: Card) -> bool:
        """Cards that enable multi-card interactions worth reserving deck space."""
        keywords = set(card.keywords)
        if "fusion" in keywords or "go_again" in keywords:
            return True
        if "attack_reaction" in card.card_types:
            return True
        if "utility_action" in card.card_types:
            damage, _ = _parse_action_damage(card.text, card.power, False)
            return damage > 0
        return False

    def _normalize_format(self, fmt: str) -> str:
        normalized = _FORMAT_ALIASES.get(str(fmt).strip().lower())
        if normalized is None:
            allowed = ", ".join(sorted(set(_FORMAT_ALIASES.values())))
            raise ValueError(f"Unknown format {fmt!r}. Expected one of: {allowed}")
        return normalized

    def _normalize_opponent_type(self, opponent_type: str) -> str:
        key = str(opponent_type or "").strip().lower().replace("-", "_")
        aliases = {
            "preset": "preset_logic",
            "preset_logic": "preset_logic",
            "random": "random",
            "self_play": "self_play",
            "selfplay": "self_play",
        }
        normalized = aliases.get(key)
        return normalized if normalized is not None else "preset_logic"

    def _build_opponent_policy(self, opponent_type: str) -> Any:
        from .opponents.preset_logic import PresetLogicOpponent

        if opponent_type == "preset_logic":
            return PresetLogicOpponent()
        if opponent_type == "random":
            from .opponents.random import RandomOpponent

            return RandomOpponent()
        if opponent_type == "self_play":
            from .opponents.self_play import SelfPlayOpponent

            return SelfPlayOpponent()
        return PresetLogicOpponent()

    def _format_deck_bounds(self) -> tuple[int, int]:
        if self._format == "silver_age":
            return 40, 55
        return 60, 80

    def _deck_options_for_format(self) -> list[dict[str, Any]]:
        min_cards, max_cards = self._format_deck_bounds()
        secondary_size = min(max_cards, min_cards + 5)
        options: list[dict[str, Any]] = []
        for hero in self._hero_pool_for_format():
            slug = hero.id.replace("hero_", "")
            options.append(
                {
                    "key": f"{slug}_aggro",
                    "label": f"{hero.name} Aggro",
                    "hero_id": hero.id,
                    "style": "aggro",
                    "deck_size": min_cards,
                }
            )
            options.append(
                {
                    "key": f"{slug}_control",
                    "label": f"{hero.name} Control",
                    "hero_id": hero.id,
                    "style": "control",
                    "deck_size": secondary_size,
                }
            )
        # Append fabrary deck options (distinct keys prefixed with "fab_")
        options.extend(self._fabrary_deck_options_for_format())
        return options

    def _sample_opponent_matchup(self, agent_hero_id: str) -> dict[str, Any]:
        options = self._deck_options_for_format()
        candidates = [o for o in options if str(o["hero_id"]) != agent_hero_id]
        if not candidates:
            candidates = options
        return dict(self._rng.choice(candidates))

    # ------------------------------------------------------------------
    # Fabrary deck database
    # ------------------------------------------------------------------

    def _load_fabrary_db(self) -> list[dict[str, Any]]:
        """Load and return raw deck entries from fabrary_decks.json."""
        if not _FABRARY_DECKS_PATH.exists():
            return []
        try:
            data = json.loads(_FABRARY_DECKS_PATH.read_text(encoding="utf-8"))
            return list(data.get("decks", []))
        except Exception:
            return []

    def _load_card_vault_feed(self) -> list[dict[str, Any]]:
        """Load raw card records from the official card vault (or fallback mirror)."""
        if self._card_vault_cards_cache is not None:
            return self._card_vault_cards_cache

        try:
            importer = importlib.import_module("flesh_and_blood_rlbridge.card_db.import_from_talishar")
        except Exception:
            self._card_vault_cards_cache = []
            return self._card_vault_cards_cache

        load_cards = getattr(importer, "load_cards", None)
        if load_cards is None:
            self._card_vault_cards_cache = []
            return self._card_vault_cards_cache

        for source_url in _CARD_VAULT_FEED_URL_CANDIDATES:
            try:
                records = load_cards(path=None, source_url=source_url)
                if isinstance(records, list) and records:
                    self._card_vault_cards_cache = records
                    return records
            except Exception:
                continue

        self._card_vault_cards_cache = []
        return self._card_vault_cards_cache

    def _import_missing_cards_from_card_vault(self, card_names: list[str]) -> int:
        """Append missing cards to cards.json by scanning card-vault data."""
        targets = {_card_name_key(name) for name in card_names if str(name).strip()}
        if not targets:
            return 0

        raw_records = self._load_card_vault_feed()
        if not raw_records:
            return 0

        by_name: dict[str, list[dict[str, Any]]] = {}
        for rec in raw_records:
            if not isinstance(rec, dict):
                continue
            key = _card_name_key(rec.get("name", ""))
            if not key:
                continue
            by_name.setdefault(key, []).append(rec)

        selected: list[dict[str, Any]] = []
        for key in sorted(targets):
            selected.extend(by_name.get(key, []))
        if not selected:
            return 0

        try:
            importer = importlib.import_module("flesh_and_blood_rlbridge.card_db.import_from_talishar")
            normalize_record = getattr(importer, "normalize_record", None)
            if normalize_record is None:
                return 0
        except Exception:
            return 0

        try:
            current_cards = json.loads(_CARDS_PATH.read_text(encoding="utf-8"))
            if not isinstance(current_cards, list):
                return 0
        except Exception:
            return 0

        existing_ids = {str(rec.get("id", "")) for rec in current_cards if isinstance(rec, dict)}
        normalized_new: list[dict[str, Any]] = []
        for rec in selected:
            try:
                norm = normalize_record(rec)
            except Exception:
                continue
            card_id = str(norm.get("id", ""))
            if not card_id or card_id in existing_ids:
                continue
            existing_ids.add(card_id)
            normalized_new.append(norm)

        if not normalized_new:
            return 0

        current_cards.extend(normalized_new)
        _CARDS_PATH.write_text(json.dumps(current_cards, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")
        self._cards = _load_cards()
        self._attach_hero_abilities()
        return len(normalized_new)

    def _build_name_lookup(self, hero: Hero) -> dict[str, list[Card]]:
        """Build normalized card-name lookup restricted to hero and format legality."""
        by_name: dict[str, list[Card]] = {}
        for card in self._cards.values():
            if not self._is_card_legal_for_format(card.id):
                continue
            if not self._is_deck_candidate(card):
                continue
            if not self._is_card_compatible_with_hero(card, hero):
                continue
            by_name.setdefault(_card_name_key(card.name), []).append(card)
        return by_name

    def _resolve_fabrary_deck(self, deck_entry: dict[str, Any]) -> list[str]:
        """Map a fabrary deck entry to a list of card IDs legal for the current format.

        Strategy:
        - For each {name, count} entry look up all pitch versions of that card
          that are legal and compatible with the hero.
        - Include up to ``count`` copies of *each* pitch version found.
        - Apply the per-card-ID copy limit (2 for silver_age, 3 for CC).
        - If the list exceeds ``max_deck_size`` it is randomly trimmed.
        - If it falls below ``min_deck_size`` it is padded with generic filler.
        """
        hero_id = str(deck_entry.get("hero_id", ""))
        if hero_id not in self._heroes:
            return []
        hero = self._heroes[hero_id]

        # Build name → [Card, ...] lookup restricted to this hero + format.
        by_name = self._build_name_lookup(hero)

        missing_names: list[str] = []
        for entry in deck_entry.get("cards", []):
            raw_name = str(entry.get("name", "")).strip()
            if raw_name and _card_name_key(raw_name) not in by_name:
                missing_names.append(raw_name)
        if missing_names:
            imported = self._import_missing_cards_from_card_vault(missing_names)
            if imported > 0:
                by_name = self._build_name_lookup(hero)

        copy_limit = 2 if self._format == "silver_age" else 3
        deck: list[str] = []

        for entry in deck_entry.get("cards", []):
            raw_name = str(entry.get("name", "")).strip()
            count = max(1, int(entry.get("count", 1)))
            matches = by_name.get(_card_name_key(raw_name), [])
            if not matches:
                continue  # card not in DB or not legal/compatible for this hero+format
            per_copy = min(count, copy_limit)
            # Sort pitch=1 (red) first so trimming preserves the strongest copies.
            for card in sorted(matches, key=lambda c: c.pitch):
                deck.extend([card.id] * per_copy)

        if not deck:
            return []

        min_cards, max_cards = self._format_deck_bounds()

        # Trim excess randomly if deck exceeds format maximum.
        if len(deck) > max_cards:
            self._rng.shuffle(deck)
            deck = deck[:max_cards]

        # Pad below minimum with generic legal filler cards.
        if len(deck) < min_cards:
            existing_ids = set(deck)
            filler_pool = [
                c for c in self._cards.values()
                if self._is_card_legal_for_format(c.id)
                and self._is_deck_candidate(c)
                and self._is_card_compatible_with_hero(c, hero)
                and c.id not in existing_ids
            ]
            self._rng.shuffle(filler_pool)
            for filler in filler_pool:
                if len(deck) >= min_cards:
                    break
                deck.append(filler.id)

        return deck

    def _fabrary_deck_options_for_format(self) -> list[dict[str, Any]]:
        """Return deck option dicts for all fabrary decks matching the current format.

        Each option has the same shape as procedural options plus extra fields:
        ``source``, ``source_url``, ``description``, and ``_card_ids``
        (the pre-resolved card ID list used by ``_new_player``).
        Keys are prefixed with ``"fab_"`` to avoid collisions with procedural keys.
        """
        raw_decks = self._load_fabrary_db()
        options: list[dict[str, Any]] = []
        for deck_entry in raw_decks:
            if str(deck_entry.get("format", "")) != self._format:
                continue
            hero_id = str(deck_entry.get("hero_id", ""))
            if hero_id not in self._heroes:
                continue
            card_ids = self._resolve_fabrary_deck(deck_entry)
            if not card_ids:
                continue
            options.append(
                {
                    "key": deck_entry["id"],
                    "label": deck_entry.get("name", deck_entry["id"]),
                    "hero_id": hero_id,
                    "style": str(deck_entry.get("style", "balanced")),
                    "deck_size": len(card_ids),
                    "source": "fabrary",
                    "source_url": deck_entry.get("source_url", ""),
                    "description": deck_entry.get("description", ""),
                    "_card_ids": card_ids,
                }
            )
        return options

    def _start_match(
        self,
        *,
        agent_hero_id: str,
        opponent_hero_id: str,
        agent_deck_style: str,
        opponent_deck_style: str,
        agent_deck_ids: Optional[list[str]] = None,
        opponent_deck_ids: Optional[list[str]] = None,
    ) -> None:
        self._players = [
            self._new_player(self._heroes[agent_hero_id], hero_slot=0, deck_style=agent_deck_style, deck_ids=agent_deck_ids),
            self._new_player(self._heroes[opponent_hero_id], hero_slot=1, deck_style=opponent_deck_style, deck_ids=opponent_deck_ids),
        ]
        for idx, player in enumerate(self._players):
            for cid in player.equipment:
                self._fire_enters_triggers(idx, self._cards[cid])
            if player.weapon_id:
                self._fire_enters_triggers(idx, self._cards[player.weapon_id])
            self._apply_hero_passives(idx)
        self._turn = 1
        self._active_player = 0
        self._phase = "action"
        self._pending_combat = None
        self._flow_stage = "p0_opening"
        self._combat_chain_links = 0
        self._action_phase_player = 0
        self._stolen_until_phase_end = []
        self._last_event = "Game start — both players draw opening hands"
        self._draw_up(0)
        self._draw_up(1)
        self._begin_action_phase(0)

    def _starting_life(self, hero: Hero) -> int:
        # Talishar profile: Silver Age uses young-hero life profile.
        if self._format == "silver_age":
            return min(hero.life, 20)
        return hero.life

    def _is_deck_candidate(self, card: Card) -> bool:
        if "hero" in card.card_types:
            return False
        if "attack_action" in card.card_types:
            return True
        # Non-attack actions and reactions enable combinations (fusion, arcane
        # bolts, attack/defense reactions) so they belong in the deck too.
        if "utility_action" in card.card_types:
            return True
        if "attack_reaction" in card.card_types:
            return True
        if "defense_reaction" in card.card_types:
            return True
        if card.defense > 0:
            return True
        return False

    def _is_card_compatible_with_hero(self, card: Card, hero: Hero) -> bool:
        card_class = (card.card_class or "Generic").strip().upper()
        hero_class = (hero.hero_class or "Generic").strip().upper()
        if card_class not in {"", "GENERIC", "NONE"} and card_class != hero_class:
            return False

        card_talent = (card.talent or "").strip().upper()
        hero_talent = (hero.talent or "").strip().upper()
        if card_talent not in {"", "NONE"} and card_talent != hero_talent:
            return False

        return True

    def _select_equipment(self, hero: Hero) -> list[str]:
        """Pick one compatible piece for each gear slot at game setup.

        Prefers higher-defense pieces and avoids self-destroying gear
        (battleworn / blade break) so the loadout survives a few blocks.
        """
        by_slot: dict[str, list[Card]] = {s: [] for s in _EQUIP_SLOTS}
        for card in self._cards.values():
            slot = _equipment_slot(card)
            if slot is None:
                continue
            if not self._is_card_legal_for_format(card.id):
                continue
            if not self._is_card_compatible_with_hero(card, hero):
                continue
            by_slot[slot].append(card)

        loadout: list[str] = []
        for slot in _EQUIP_SLOTS:
            options = by_slot[slot]
            if not options:
                continue
            options.sort(
                key=lambda c: (
                    c.defense,
                    0 if ({"battleworn", "blade_break"} & set(c.keywords)) else 1,
                    -c.cost,
                ),
                reverse=True,
            )
            loadout.append(options[0].id)
        return loadout

    @staticmethod
    def _is_weapon_card(card: Card) -> bool:
        return "weapon" in (card.type_line or "").lower() and "utility_item" in card.card_types

    @staticmethod
    def _is_dagger_card(card: Card) -> bool:
        line = (card.type_line or "").lower()
        name = card.name.lower()
        return "dagger" in line or ("weapon" in line and "dagger" in name)

    def _dagger_ids_controlled(self, player_idx: int) -> list[str]:
        actor = self._players[player_idx]
        ids: list[str] = []
        if actor.weapon_id:
            weapon = self._cards.get(actor.weapon_id)
            if weapon and self._is_dagger_card(weapon):
                ids.append(actor.weapon_id)
        for cid in actor.equipment:
            card = self._cards.get(cid)
            if card and self._is_dagger_card(card):
                ids.append(cid)
        return ids

    def _daggers_on_chain(self, combat: CombatState) -> set[str]:
        on_chain: set[str] = set()
        attack = self._cards.get(combat.attack_card_id)
        if attack and self._is_dagger_card(attack):
            on_chain.add(combat.attack_card_id)
        if combat.is_weapon:
            weapon_id = self._players[combat.attacker].weapon_id
            if weapon_id:
                on_chain.add(weapon_id)
        for cid in combat.reaction_cards:
            card = self._cards.get(cid)
            if card and self._is_dagger_card(card):
                on_chain.add(cid)
        return on_chain

    def _destroy_controlled_dagger(
        self,
        player_idx: int,
        dagger_id: str,
        perspective_idx: int,
    ) -> None:
        actor = self._players[player_idx]
        if dagger_id == actor.weapon_id:
            actor.weapon_id = None
        elif dagger_id in actor.equipment:
            actor.equipment.remove(dagger_id)
        else:
            return
        actor.discard.append(dagger_id)
        card = self._cards[dagger_id]
        self._fire_on_destroy_triggers(player_idx, dagger_id, perspective_idx)
        self._fire_controlled_destroy_triggers(player_idx, card, perspective_idx)
        self._fire_on_leave_triggers(player_idx, dagger_id, perspective_idx)
        self._event_append(f"destroyed {card.name}")

    def _weapon_swing_cost(self, card: Card) -> int:
        """Resource cost of a weapon's printed attack ability ({r} count)."""
        for ability in effects.parse_activated_abilities(card.text):
            if "attack" in ability.raw.lower():
                return ability.cost
        return 0

    def _select_weapon(self, hero: Hero) -> Optional[str]:
        """Pick a real weapon card for the hero (else fall back to basic weapon).

        Prefers higher attack power, and rewards weapons that also carry an
        activated ability we can resolve (e.g. an arcane staff).
        """
        best: Optional[Card] = None
        best_score = float("-inf")
        hero_class = (hero.hero_class or "Generic").strip().upper()
        for card in self._cards.values():
            if not self._is_weapon_card(card):
                continue
            if not self._is_card_legal_for_format(card.id):
                continue
            if not self._is_card_compatible_with_hero(card, hero):
                continue
            has_ability = any(
                a.implemented for a in effects.parse_activated_abilities(card.text)
            )
            class_specific = (card.card_class or "Generic").strip().upper() == hero_class
            swing_cost = self._weapon_swing_cost(card)
            # Favor a thematic class weapon, then a weapon the hero can actually
            # swing (low resource cost), then attack power, then a usable ability.
            score = (
                (10 if class_specific else 0)
                + (card.power if card.power > 0 else 0)
                - swing_cost * 2
                + (3 if has_ability else 0)
            )
            if score > best_score:
                best_score, best = score, card
        return best.id if best is not None else None

    def _weapon_stats(self, player_idx: int) -> tuple[str, int, int, Optional[Card]]:
        """Return (name, attack, swing_cost, weapon_card) for a player's weapon."""
        p = self._players[player_idx]
        if p.weapon_id is not None:
            card = self._cards[p.weapon_id]
            return card.name, card.power, self._weapon_swing_cost(card), card
        hero = p.hero
        return hero.weapon_name, hero.weapon_attack, hero.weapon_cost, None

    def _attach_hero_abilities(self) -> None:
        """Populate each hero's special-ability text from its hero card."""
        index: dict[str, str] = {}
        for card in self._cards.values():
            if "hero" in card.card_types and card.text:
                index.setdefault(_card_name_key(card.name), card.text)
        for hid, hero in list(self._heroes.items()):
            if hero.ability_text:
                continue
            text = index.get(_card_name_key(hero.name), "")
            if text:
                self._heroes[hid] = dataclasses.replace(hero, ability_text=text)

    def _hero_pool_for_format(self) -> list[Hero]:
        heroes = list(self._heroes.values())
        if self._format == "silver_age":
            filtered = [h for h in heroes if h.life < 30]
        else:
            filtered = [h for h in heroes if h.life >= 30]
        if not filtered:
            filtered = heroes
        filtered.sort(key=lambda h: h.name.lower())
        return filtered

    def _is_card_legal_for_format(self, card_id: str) -> bool:
        card = self._cards[card_id]
        if self._format == "classic_constructed":
            return str(card.legality.get("classic_constructed", "legal")).lower() == "legal"

        if self._format == "silver_age":
            return str(card.legality.get("silver_age", "banned")).lower() == "legal"

        return True

    def _draw_card(self, player_idx: int, *, from_action: bool = False) -> bool:
        p = self._players[player_idx]
        if not p.deck and p.discard:
            p.deck = p.discard
            p.discard = []
            self._rng.shuffle(p.deck)
        if not p.deck:
            return False
        p.hand.append(p.deck.pop())
        p.class_state["NumCardsDrawn"] += 1
        if from_action:
            p.class_state["DrawFromActionThisTurn"] = (
                p.class_state.get("DrawFromActionThisTurn", 0) + 1
            )
            self._fire_passive_triggers(player_idx, "whenever_action_draw", 1)
        if self._phase == "action":
            self._fire_passive_triggers(player_idx, "whenever_any_draw", 1)
        return True

    def _fire_passive_triggers(
        self, player_idx: int, when: str, amount: int = 1
    ) -> None:
        actor = self._players[player_idx]
        sources: list[Card] = [self._cards[cid] for cid in actor.equipment]
        if actor.weapon_id:
            sources.append(self._cards[actor.weapon_id])
        for card in sources:
            for trig in effects.parse_triggers(card.text):
                if trig.when != when or not trig.effect.implemented:
                    continue
                eff = trig.effect
                if eff.kind == "create_token":
                    n = max(1, amount or 1)
                    self._create_token(player_idx, eff.token_name, n)
                    self._event_append(
                        f"{card.name}: created {n} {eff.token_name} token(s)"
                    )
                elif eff.kind == "lose_gold":
                    actor.gold = max(0, actor.gold - max(1, eff.amount or 1))
                    self._event_append(f"{card.name}: lost {eff.amount or 1} gold on draw")
                else:
                    self._apply_effect(player_idx, card, eff, self._pending_combat, player_idx)

    def _fire_equipment_triggers(
        self,
        player_idx: int,
        when: str,
        perspective_idx: int = 0,
    ) -> float:
        """Fire optional/mandatory triggers on equipment and weapon for a given event."""
        reward = 0.0
        actor = self._players[player_idx]
        sources: list[Card] = [self._cards[cid] for cid in actor.equipment]
        if actor.weapon_id:
            sources.append(self._cards[actor.weapon_id])
        for card in sources:
            for trig in effects.parse_triggers(card.text):
                if trig.when != when or not trig.effect.implemented:
                    continue
                eff = trig.effect
                if eff.optional:
                    if self._optional_available(player_idx, eff):
                        self._pending_optionals.append(
                            {
                                "player": player_idx,
                                "card_id": card.id,
                                "effect": eff,
                                "perspective": perspective_idx,
                            }
                        )
                    continue
                reward += self._apply_effect(
                    player_idx, card, eff, self._pending_combat, perspective_idx
                )
        return reward

    def _fire_deck_banish_item_triggers(self, player_idx: int, perspective_idx: int = 0) -> None:
        actor = self._players[player_idx]
        if not actor.banished:
            return
        card = self._cards[actor.banished[-1]]
        if not self._is_arena_permanent(card):
            return
        self._fire_equipment_triggers(player_idx, "on_deck_banish_item", perspective_idx)

    def _fire_arrow_from_deck_triggers(
        self, player_idx: int, arrow_id: str, perspective_idx: int = 0
    ) -> None:
        self._players[player_idx].class_state["LastArrowFromDeckId"] = arrow_id
        self._fire_equipment_triggers(player_idx, "on_arrow_from_deck", perspective_idx)

    def _put_arrow_from_deck_to_arsenal(self, player_idx: int) -> bool:
        actor = self._players[player_idx]
        if actor.arsenal or not actor.deck:
            return False
        top = actor.deck[-1]
        card = self._cards[top]
        tl = (card.type_line or "").lower()
        if "arrow" not in tl and "arrow" not in card.name.lower():
            return False
        return self._put_deck_top_in_arsenal(player_idx, face_up=True, require_arrow=True)

    def _put_deck_top_in_arsenal(
        self, player_idx: int, *, face_up: bool = False, require_arrow: bool = False
    ) -> bool:
        actor = self._players[player_idx]
        if actor.arsenal or not actor.deck:
            return False
        top = actor.deck[-1]
        card = self._cards[top]
        if require_arrow:
            tl = (card.type_line or "").lower()
            if "arrow" not in tl and "arrow" not in card.name.lower():
                return False
        cid = actor.deck.pop()
        actor.arsenal.append(cid)
        face = "face-up" if face_up else "face-down"
        self._event_append(f"put {card.name} {face} in arsenal from deck")
        if require_arrow or "arrow" in (card.type_line or "").lower():
            self._fire_arrow_from_deck_triggers(player_idx, cid)
        return True

    def _do_beat_chest(self, player_idx: int, perspective_idx: int = 0) -> float:
        actor = self._players[player_idx]
        if not actor.hand:
            self._last_event = "No cards to beat chest"
            return -0.05
        idx = random.randrange(len(actor.hand))
        cid = actor.hand.pop(idx)
        self._event_append(f"beat chest: discarded {self._cards[cid].name}")
        actor.discard.append(cid)
        return self._fire_equipment_triggers(player_idx, "on_beat_chest", perspective_idx)

    def _damage_target_idx(
        self,
        player_idx: int,
        effect: "effects.Effect",
        combat: Optional[CombatState],
    ) -> int:
        if effect.target == "attacking_hero" and combat is not None:
            return combat.attacker
        if effect.target == "permanent_controller":
            controller = self._players[player_idx].class_state.get(
                "LastSteamRemovedController", player_idx
            )
            return int(controller)
        if effect.target == "defender" and combat is not None:
            return combat.defender
        if effect.target == "attacked" and combat is not None:
            return combat.defender
        if effect.target in ("opponent", "ally"):
            return 1 - player_idx
        if effect.target == "self":
            return player_idx
        return 1 - player_idx

    def _draw_up(self, player_idx: int) -> None:
        p = self._players[player_idx]
        target = p.class_state.pop("_EndPhaseDrawTarget", None)
        if target is None:
            target = p.hero.intellect
        while len(p.hand) < target:
            if not self._draw_card(player_idx):
                break

    def _begin_action_phase(self, player_idx: int) -> None:
        """Start a player's action (attack) phase."""
        p = self._players[player_idx]
        p.resources = 0
        p.action_points = 1
        for key in _PER_TURN_COUNTERS:
            p.class_state[key] = 0
        for key in list(p.class_state.keys()):
            if str(key).startswith("NamedPower:"):
                p.class_state[key] = 0
        p.weapon_used = False
        p.arena_used = set()
        p.playable_banished = set()
        p.playable_graveyard = set()
        p.tokens_controlled_turn = set()
        p.prevent_damage = 0
        p.prevent_damage_charges = 0
        p.prevent_damage_per_hit = 0
        p.marked = False
        p.amp = 0
        p.arcane_barrier = 0
        p.cheered_this_turn = False
        p.booed_this_turn = False
        p.play_as_instant = False
        p.extra_play_cost = 0
        p.extra_defense_reaction_cost = 0
        p.attack_play_power_cap = -1
        p.instant_class_filter = ""
        p.arsenal_play_blocked = False
        p.extra_attack_targets = 0
        p.weapon_attacks_blocked = False
        p.hand_from_arsenal = set()
        p.deck_top_play_used = False
        p.may_play_grants = list(p.hero_may_play_grants)
        self._process_token_upkeep(player_idx)
        self._fire_turn_start_triggers(player_idx)
        self._fire_action_phase_triggers(player_idx)
        if self._play_restriction_kind and self._turn >= self._play_restriction_clear_at_turn:
            self._play_restriction_kind = ""
            self._play_restriction_clear_at_turn = 0
            self._event_append("Proclamation of Combat restriction ended")
        if p.class_state.get("BlockZeroCostUntilTurn", 0) and self._turn > p.class_state["BlockZeroCostUntilTurn"]:
            p.class_state["BlockZeroCostUntilTurn"] = 0
        # Apply any action limit imposed by the opponent last turn
        max_actions_next = p.class_state.pop("MaxActionsNextTurn", 0)
        if max_actions_next:
            p.class_state["MaxActionsThisTurn"] = max_actions_next
            self._event_append(f"P{player_idx} limited to {max_actions_next} action(s) this turn")
        else:
            p.class_state.pop("MaxActionsThisTurn", None)
        if p.blocked_pitch_values and self._turn > p.class_state.get("BlockPitchColorUntilTurn", 0):
            p.blocked_pitch_values = set()
            p.class_state["BlockPitchColorUntilTurn"] = 0
        self._active_player = player_idx
        self._action_phase_player = player_idx
        self._phase = "action"
        self._combat_chain_links = 0
        if player_idx == 1:
            self._last_opponent_turn = {
                "pitches": [],
                "attack_card": None,
                "attack_power": None,
                "is_weapon": False,
            }

    def _finish_action_phase(self, player_idx: int) -> None:
        """End the active player's action phase and advance the game flow."""
        p = self._players[player_idx]
        if p.pitch_zone:
            p.deck[:0] = p.pitch_zone
            p.pitch_zone = []
        p.resources = 0
        p.action_points = 0
        self._process_blood_debt(player_idx)
        if p.intimidated:
            p.hand.extend(p.intimidated)
            p.intimidated = []
            self._event_append("intimidated cards returned to hand")
        if p.silenced:
            p.silenced = False
            self._event_append("silence ended")
        self._clear_chain_may_play_grants(0)
        self._clear_chain_may_play_grants(1)
        for owner_idx, thief_idx, cid in self._stolen_until_phase_end:
            thief = self._players[thief_idx]
            owner = self._players[owner_idx]
            if cid in thief.equipment:
                thief.equipment.remove(cid)
                owner.equipment.append(cid)
                self._event_append(f"returned {self._cards[cid].name} to P{owner_idx}")
        self._stolen_until_phase_end = []
        p.may_play_grants = list(p.hero_may_play_grants)
        delta = p.class_state.pop("EndPhaseIntellectDelta", 0)
        if delta:
            p.class_state["_EndPhaseDrawTarget"] = max(0, p.hero.intellect + delta)
            self._event_append(
                f"P{player_idx} intellect {delta:+d} during end phase "
                f"(draw to {p.class_state['_EndPhaseDrawTarget']})"
            )
        self._fire_end_phase_triggers(player_idx)
        self._combat_chain_links = 0
        self._turn += 1

        if self._flow_stage == "p0_opening":
            self._draw_up(0)
            self._draw_up(1)
            self._flow_stage = "p1_opening"
            self._last_event = (
                f"P{player_idx} ended opening attack phase — both players draw to full hand"
            )
            self._begin_action_phase(1)
        elif self._flow_stage == "p1_opening":
            self._draw_up(player_idx)
            self._flow_stage = "normal"
            self._last_event = (
                f"P{player_idx} ended opening attack phase — P{player_idx} draws to full hand"
            )
            self._begin_action_phase(0)
        else:
            self._draw_up(player_idx)
            next_player = 1 - player_idx
            self._last_event = (
                f"P{player_idx} ended attack phase — P{player_idx} draws to full hand; "
                f"P{next_player} attacks next"
            )
            self._begin_action_phase(next_player)

    def _begin_arsenal_step(self, player_idx: int) -> None:
        """Optional one-card arsenal stash after attacks, before end-of-phase draw."""
        p = self._players[player_idx]
        p.action_points = 0
        self._active_player = player_idx
        if not p.hand or p.arsenal:
            self._finish_action_phase(player_idx)
            return
        self._phase = "arsenal"
        self._last_event = f"P{player_idx} may stash a card in arsenal before drawing"

    def _pass_arsenal(self, player_idx: int) -> None:
        self._last_event = f"P{player_idx} skipped arsenal stash"
        self._finish_action_phase(player_idx)

    def _flow_segment_label(self) -> str:
        """Human-readable description of the current turn segment."""
        if self._phase == "defense" and self._pending_combat is not None:
            atk, dfn = self._pending_combat.attacker, self._pending_combat.defender
            link = self._combat_chain_links
            chain = f" (combat chain link {link})" if link > 1 else ""
            return f"P{dfn} defend step vs P{atk}'s attack{chain}"
        if self._phase == "attack_reaction" and self._pending_combat is not None:
            return (
                f"P{self._pending_combat.attacker} attack-reaction step "
                f"(combat chain link {self._combat_chain_links})"
            )
        if self._phase == "defense_reaction" and self._pending_combat is not None:
            return (
                f"P{self._pending_combat.defender} defense-reaction step "
                f"(combat chain link {self._combat_chain_links})"
            )
        if self._phase == "arsenal":
            player = self._action_phase_player
            if self._flow_stage == "p0_opening":
                return f"P{player} arsenal step after opening attacks (then draw)"
            if self._flow_stage == "p1_opening":
                return f"P{player} arsenal step after opening attacks (then draw)"
            return f"P{player} arsenal step (stash optional, then draw)"
        if self._phase == "action":
            if self._flow_stage == "p0_opening":
                return "P0 opening attack phase (no draw)"
            if self._flow_stage == "p1_opening":
                return "P1 opening attack phase (no draw)"
            return f"P{self._action_phase_player} attack phase (draw after)"
        if self._phase == "instant_pay":
            ctx = self._pending_instant_pay
            card_id = ctx.get("card_id", "")
            card = self._cards.get(card_id)
            name = card.name if card else "instant"
            cost = ctx.get("cost", 0)
            actor = self._players[ctx.get("player", 0)]
            return f"P{ctx.get('player', 0)} pitching to pay {cost} for {name} ({actor.resources}/{cost})"
        if self._phase == "pitch_pay":
            ctx = self._pending_pitch_pay
            card = self._cards.get(ctx.get("card_id", ""))
            name = card.name if card else "effect"
            cost = ctx.get("cost", 0)
            actor = self._players[ctx.get("player", 0)]
            if ctx.get("variable"):
                paid = actor.resources - ctx.get("resources_at_start", actor.resources)
                return (
                    f"P{ctx.get('player', 0)} pitching up to {cost} for {name} "
                    f"({paid}/{cost} committed, pass when done)"
                )
            return (
                f"P{ctx.get('player', 0)} pitching to pay {cost} for {name} "
                f"({actor.resources}/{cost})"
            )
        return self._phase

    # ------------------------------------------------------------------
    # Requirement / bonus hooks
    # ------------------------------------------------------------------
    def _reveal_available(self, player_idx: int, exclude_idx: int, token: str) -> bool:
        """True if the player can reveal another hand card matching ``token``."""
        token = (token or "").strip().lower()
        if not token:
            return False
        for i, cid in enumerate(self._players[player_idx].hand):
            if i == exclude_idx:
                continue
            c = self._cards[cid]
            haystack = " ".join(
                [c.name.lower(), (c.talent or "").lower(), c.text.lower(), " ".join(c.keywords)]
            )
            if token in haystack:
                return True
        return False

    def _card_requires_arsenal(self, card: Card) -> bool:
        for mod in effects.parse_play_modifiers(card.text):
            if mod.condition == "play_zone:arsenal_only":
                return True
        return False

    def _play_blocked_reason(
        self,
        player_idx: int,
        hand_idx: int,
        card: Card,
        *,
        from_arsenal: bool = False,
    ) -> Optional[str]:
        """Return a reason string if a mandatory play requirement is unmet."""
        if not from_arsenal:
            token, hard = _reveal_requirement(card.text)
            if token and hard and not self._reveal_available(player_idx, hand_idx, token):
                return f"{card.name} requires revealing a {token} card from hand"
        actor = self._players[player_idx]
        if (
            "attack_action" in card.card_types
            and actor.attack_play_power_cap >= 0
            and card.power <= actor.attack_play_power_cap
        ):
            return (
                f"{card.name} blocked: attacks with {card.power} or less base power "
                f"cannot be played this turn"
            )
        for mod in effects.parse_play_modifiers(card.text):
            if mod.condition.startswith("play_gate:") and not self._play_gate_met(
                player_idx, mod.condition
            ):
                return f"{card.name}: play requirement not met ({mod.raw[:60]})"
            if mod.condition == "play_zone:arsenal_only" and not from_arsenal:
                return f"{card.name} can only be played from arsenal"
        if from_arsenal and actor.arsenal_play_blocked:
            return f"{card.name} blocked: cannot play face-up cards from arsenal this turn"
        if self._play_restriction_kind == "weapon_attack_only":
            if "attack_action" not in card.card_types:
                return (
                    f"{card.name} blocked: only weapon and attack actions may be played "
                    "(Proclamation of Combat)"
                )
        max_actions = actor.class_state.get("MaxActionsThisTurn", 0)
        if max_actions and "action" in card.card_types:
            if actor.class_state.get("NumActionsPlayed", 0) >= max_actions:
                return f"{card.name} blocked: limited to {max_actions} action(s) this turn"
        if actor.class_state.get("BlockZeroCostUntilTurn", 0) and self._turn <= actor.class_state["BlockZeroCostUntilTurn"]:
            if card.cost <= 0:
                return f"{card.name} blocked: cannot play cards with base cost 0 this turn"
        return None

    def _count_equipped_evos(self, player_idx: int) -> int:
        actor = self._players[player_idx]
        count = 0
        for cid in actor.equipment:
            if "evo" in self._cards[cid].name.lower():
                count += 1
        if actor.weapon_id and "evo" in self._cards[actor.weapon_id].name.lower():
            count += 1
        return count

    def _count_blood_debt_in_banish(self, player_idx: int) -> int:
        actor = self._players[player_idx]
        return sum(
            1
            for cid in actor.banished
            if "blood_debt" in self._cards[cid].keywords
        )

    def _count_earth_in_banish(self, player_idx: int) -> int:
        actor = self._players[player_idx]
        return sum(
            1
            for cid in actor.banished
            if (self._cards[cid].talent or "").strip().lower() == "earth"
            or "earth" in (self._cards[cid].type_line or "").lower()
        )

    def _card_is_draconic(
        self,
        card: Optional[Card],
        player_idx: int,
        *,
        consume_pending: bool = False,
    ) -> bool:
        if card is None:
            return False
        if (card.talent or "").lower() == "draconic":
            return True
        actor = self._players[player_idx]
        if actor.class_state.get("NextChainAttackDraconic", 0):
            if consume_pending:
                actor.class_state["NextChainAttackDraconic"] = 0
            return True
        return False

    def _draconic_chain_links(self) -> int:
        """Chain links on the current combat chain with Draconic cards (approximation)."""
        combat = self._pending_combat
        if combat is None:
            return 0
        count = combat.draconic_links
        attack = self._cards.get(combat.attack_card_id)
        if self._card_is_draconic(attack, combat.attacker):
            count += 1
        for _, cid, _ in combat.blocks:
            block = self._cards.get(cid)
            if block and (block.talent or "").lower() == "draconic":
                count += 1
        return count

    def _mark_attack_started(self, player_idx: int) -> None:
        actor = self._players[player_idx]
        actor.class_state["AttacksStartedThisTurn"] = (
            actor.class_state.get("AttacksStartedThisTurn", 0) + 1
        )
        actor.class_state["NextFirstAttackExtraCost"] = 0

    def _effective_attack_base_power(self, player_idx: int, card: Card) -> int:
        base = card.power
        actor = self._players[player_idx]
        if (
            actor.class_state.get("HalveFirstAttackBaseNextTurn", 0)
            and actor.class_state.get("AttacksStartedThisTurn", 0) == 0
            and "attack_action" in card.card_types
        ):
            base = (base + 1) // 2
            actor.class_state["HalveFirstAttackBaseNextTurn"] = 0
            self._event_append(f"{card.name} base power halved to {base}")
        return base

    def _first_attack_extra_cost(self, player_idx: int, *, is_attack: bool) -> int:
        if not is_attack:
            return 0
        actor = self._players[player_idx]
        if actor.class_state.get("AttacksStartedThisTurn", 0) > 0:
            return 0
        return max(0, actor.class_state.get("NextFirstAttackExtraCost", 0))

    def _apply_chain_defend(
        self,
        player_idx: int,
        card: Card,
        effect: "effects.Effect",
        combat: Optional[CombatState],
    ) -> None:
        if combat is None:
            self._event_append("no active chain link to defend")
            return
        rider = (effect.banish_name or "").lower()
        defender_idx = combat.defender
        defender = self._players[defender_idx]
        defense_override = effect.amount if effect.amount > 0 else None
        if rider == "arsenal":
            if not defender.arsenal:
                if not effect.optional:
                    self._event_append("no card in arsenal to defend with")
                return
            cid = defender.arsenal.pop()
            defender.face_up_arsenal.discard(cid)
            block_card = self._cards[cid]
            defense = defense_override if defense_override is not None else block_card.defense
            combat.blocks.append((defender_idx, cid, defense))
            self._event_append(
                f"added {block_card.name} from arsenal as defending (+{defense})"
            )
            if self._is_trap_card(block_card):
                self._fire_trap_triggered(
                    defender_idx, block_card, combat, player_idx
                )
            return
        if rider == "self":
            defense = defense_override
            if defense is None:
                defense = self._effective_equipment_defense(
                    player_idx, card.id, card.defense
                )
            combat.blocks.append((player_idx, card.id, defense))
            actor = self._players[player_idx]
            actor.arena_used.add(f"equip:{card.id}")
            self._event_append(f"{card.name} added as defending (+{defense})")
            return
        if rider == "hand_actions":
            added = 0
            for cid in list(defender.hand):
                if "action" not in self._cards[cid].card_types:
                    continue
                defender.hand.remove(cid)
                defender.banished.append(cid)
                block_card = self._cards[cid]
                defense = block_card.defense
                combat.blocks.append((defender_idx, cid, defense))
                added += 1
            if added:
                self._event_append(f"banished {added} action(s) from hand as defending")
            else:
                self._event_append("no action cards in hand to banish as defending")
            return

    def _play_gate_met(self, player_idx: int, gate: str) -> bool:
        """Evaluate a parsed play_gate:kind:arg condition."""
        parts = gate.split(":")
        if len(parts) < 2 or parts[0] != "play_gate":
            return True
        kind = parts[1]
        arg = parts[2] if len(parts) > 2 else ""
        actor = self._players[player_idx]
        cs = actor.class_state
        if kind == "evos_ge":
            return self._count_equipped_evos(player_idx) >= int(arg or "1")
        if kind == "damage_taken_turn":
            return cs.get("DamageTakenThisTurn", 0) > 0
        if kind == "boosted_turn":
            return cs.get("BoostedThisTurn", 0) > 0
        if kind == "runechants_eq":
            key = token_defs.normalize_token_name("runechant")
            return actor.tokens.get(key, 0) == int(arg or "0")
        if kind == "discarded_power6_turn":
            return cs.get("DiscardedPower6ThisTurn", 0) > 0
        if kind == "pitched_power6_turn":
            return cs.get("PitchedPower6ThisTurn", 0) > 0
        if kind == "banished_power6_turn":
            return cs.get("BanishedPower6ThisTurn", 0) > 0
        if kind == "blood_debt_played_ge":
            return cs.get("BloodDebtPlayedThisTurn", 0) >= int(arg or "1")
        if kind == "blood_debt_banish_ge":
            return self._count_blood_debt_in_banish(player_idx) >= int(arg or "1")
        if kind == "phantasm_destroyed_turn":
            return cs.get("PhantasmDestroyedThisTurn", 0) > 0
        if kind == "fealty_ge":
            key = token_defs.normalize_token_name("fealty")
            return actor.tokens.get(key, 0) >= int(arg or "1")
        if kind == "draconic_links_ge":
            return self._draconic_chain_links() >= int(arg or "1")
        if kind == "weapon_attacks_ge":
            return cs.get("WeaponAttacksThisTurn", 0) >= int(arg or "1")
        if kind == "wagered_chain":
            return cs.get("WageredThisChain", 0) > 0
        if kind == "defending_action_chain":
            combat = self._pending_combat
            if combat is None:
                return False
            return any(
                "attack_action" in self._cards[cid].card_types
                for _, cid, _ in combat.blocks
            )
        if kind == "dealt_damage_turn":
            return cs.get("DamageDealt", 0) > 0
        if kind == "yellow_soul_turn":
            return cs.get("YellowSoulThisTurn", 0) > 0
        return True

    def _fusion_state(
        self, player_idx: int, hand_idx: int, card: Card
    ) -> tuple[tuple[str, ...], bool]:
        """Return fusion elements and whether the player can fuse right now."""
        if "fusion" not in set(card.keywords):
            return (), False
        elements = _fusion_elements(card.text)
        if not elements:
            return (), False
        return elements, self._can_fuse(player_idx, elements, exclude_idx=hand_idx)

    def _card_matches_element(self, card: Card, element: str) -> bool:
        token = (element or "").strip().lower()
        if not token:
            return False
        haystack = " ".join(
            [card.name.lower(), (card.talent or "").lower(), card.text.lower(), " ".join(card.keywords)]
        )
        return token in haystack

    def _can_fuse(
        self, player_idx: int, elements: tuple[str, ...], *, exclude_idx: int = -1
    ) -> bool:
        actor = self._players[player_idx]
        used: set[int] = set()
        for element in elements:
            found = False
            for i, cid in enumerate(actor.hand):
                if i == exclude_idx or i in used:
                    continue
                if self._card_matches_element(self._cards[cid], element):
                    used.add(i)
                    found = True
                    break
            if not found:
                return False
        return True

    def _consume_fusion_cards(self, player_idx: int, elements: tuple[str, ...]) -> bool:
        """Banish one hand card per fusion element (CR 8.3.8 reveal for Fusion)."""
        actor = self._players[player_idx]
        for element in elements:
            matched = False
            for i, cid in enumerate(actor.hand):
                if self._card_matches_element(self._cards[cid], element):
                    cid = actor.hand.pop(i)
                    actor.banished.append(cid)
                    self._event_append(f"fusion: banished {self._cards[cid].name}")
                    matched = True
                    break
            if not matched:
                return False
        return True

    def _is_playable_action(self, card: Card) -> bool:
        """Whether a card can be played from the action phase in this engine."""
        if "attack_action" in card.card_types:
            return True
        if "utility_action" not in card.card_types:
            return False
        # Only surface non-attack actions we can meaningfully resolve: those
        # that deal damage, chain (go again), or enable a fusion reveal.
        keywords = set(card.keywords)
        if "go_again" in keywords or "fusion" in keywords:
            return True
        damage, _ = _parse_action_damage(card.text, card.power, False)
        return damage > 0

    # ------------------------------------------------------------------
    # Legal-move helpers (shared by the engine and observation)
    # ------------------------------------------------------------------
    def _is_ally_card(self, card: Card) -> bool:
        tl = (card.type_line or "").lower()
        return " ally" in tl or tl.endswith("ally")

    def _is_arena_permanent(self, card: Card) -> bool:
        """True when a played action stays in the arena (item, aura, ally)."""
        tl = (card.type_line or "").lower()
        return any(marker in tl for marker in (" item", " aura", " ally")) or tl.endswith(
            ("item", "aura", "ally")
        )

    def _permanent_counters(self, player_idx: int, card_id: str) -> dict[str, int]:
        return self._players[player_idx].permanent_counters.setdefault(card_id, {})

    def _add_permanent_counter(self, player_idx: int, card_id: str, name: str, amount: int = 1) -> None:
        counters = self._permanent_counters(player_idx, card_id)
        key = name.strip().lower()
        counters[key] = counters.get(key, 0) + amount

    def _remove_permanent_counter(
        self, player_idx: int, card_id: str, name: str, amount: int = 1
    ) -> bool:
        counters = self._permanent_counters(player_idx, card_id)
        key = name.strip().lower()
        if counters.get(key, 0) < amount:
            return False
        counters[key] -= amount
        if counters[key] <= 0:
            del counters[key]
        return True

    def _crush_condition_met(self, attacker_idx: int, effect: "effects.Effect") -> bool:
        cond = effect.condition
        if not cond:
            return True
        if cond.startswith("defender_"):
            hero_class = cond[len("defender_"):].lower()
            defender = self._players[1 - attacker_idx]
            return (defender.hero.hero_class or "").strip().lower() == hero_class
        return self._effect_condition_met(attacker_idx, cond)

    def _token_play_cost_reduction(self, player_idx: int, card: Card) -> int:
        actor = self._players[player_idx]
        reduction = 0
        body = card.text.lower()
        m = re.search(r"costs ((?:\{r\})+|\d+) less to play for each (\w+) you control", body)
        if m:
            txt = m.group(1)
            per = txt.count("{r}") if "{r}" in txt else int(re.search(r"\d+", txt).group(0))
            key = token_defs.normalize_token_name(m.group(2))
            reduction += per * actor.tokens.get(key, 0)
        return reduction

    def _put_item_from_hand(self, player_idx: int, max_cost: int) -> bool:
        actor = self._players[player_idx]
        for i, cid in enumerate(actor.hand):
            card = self._cards[cid]
            if not self._is_arena_permanent(card):
                continue
            if card.cost > max_cost:
                continue
            actor.hand.pop(i)
            actor.equipment.append(cid)
            self._fire_enters_triggers(player_idx, card)
            self._event_append(f"put {card.name} into the arena")
            return True
        return False

    def _put_item_from_banished(self, player_idx: int, max_cost: int) -> bool:
        actor = self._players[player_idx]
        for i, cid in enumerate(actor.banished):
            card = self._cards[cid]
            if not self._is_arena_permanent(card):
                continue
            if card.cost > max_cost:
                continue
            actor.banished.pop(i)
            actor.equipment.append(cid)
            self._fire_enters_triggers(player_idx, card)
            self._event_append(f"put {card.name} from banished into the arena")
            return True
        return False

    def _put_arrow_in_arsenal(self, player_idx: int) -> bool:
        actor = self._players[player_idx]
        if actor.arsenal:
            return False
        for i, cid in enumerate(actor.hand):
            card = self._cards[cid]
            tl = (card.type_line or "").lower()
            if "arrow" not in tl and "arrow" not in card.name.lower():
                continue
            actor.hand.pop(i)
            actor.arsenal.append(cid)
            self._event_append(f"put {card.name} face-up in arsenal")
            return True
        return False

    def _move_card_to_gy(self, player_idx: int, card_id: str) -> None:
        """Move a card to graveyard, honoring replacement effects."""
        card = self._cards[card_id]
        for trig in effects.parse_triggers(card.text):
            if trig.when == "gy_replacement" and trig.effect.kind == "gy_to_bottom":
                self._players[player_idx].deck.insert(0, card_id)
                self._event_append(f"{card.name} put on bottom of deck instead of graveyard")
                return
        self._players[player_idx].discard.append(card_id)

    def _fire_chain_close_triggers(
        self,
        attacker_idx: int,
        card: Card,
        damage: int,
        perspective_idx: int,
        fused: bool,
    ) -> float:
        reward = 0.0
        cs = self._players[attacker_idx].class_state
        for trig in effects.parse_triggers(card.text):
            if trig.when != "on_chain_close":
                continue
            cond = trig.effect.condition
            if cond == "miss" and damage > 0:
                continue
            if cond == "played_from_arsenal" and not cs.get("PlayedFromArsenal", 0):
                continue
            eff = trig.effect
            if cond == "miss":
                eff = dataclasses.replace(eff, condition="")
            reward += self._apply_effect(attacker_idx, card, eff, None, perspective_idx)
        return reward

    def _fire_block_chain_close_triggers(
        self,
        defender_idx: int,
        card: Card,
        damage: int,
        perspective_idx: int,
    ) -> float:
        reward = 0.0
        for trig in effects.parse_triggers(card.text):
            if trig.when != "on_chain_close":
                continue
            cond = trig.effect.condition
            if cond == "miss" and damage > 0:
                continue
            eff = trig.effect
            if cond == "miss":
                eff = dataclasses.replace(eff, condition="")
            reward += self._apply_effect(defender_idx, card, eff, None, perspective_idx)
        return reward

    def _galvanize_defense_bonus(self, player_idx: int, card_id: str, bonus: int) -> None:
        actor = self._players[player_idx]
        actor.class_state["NextDefenseBonus"] = actor.class_state.get("NextDefenseBonus", 0) + bonus
        self._event_append(f"galvanize: +{bonus} defense on next block ({self._cards[card_id].name})")

    def _effective_equipment_defense(self, player_idx: int, card_id: str, base_defense: int) -> int:
        counters = self._permanent_counters(player_idx, card_id)
        bonus = counters.get("defense", 0)
        penalty = counters.get("defense_penalty", 0)
        return max(0, base_defense + bonus - penalty)

    def _effective_weapon_swing_cost(
        self, player_idx: int, base_cost: int, *, consume: bool = False
    ) -> int:
        reduction = self._players[player_idx].class_state.get("NextWeaponSwingCostReduction", 0)
        cost = max(0, base_cost - reduction)
        if consume and reduction > 0 and base_cost > 0:
            self._players[player_idx].class_state["NextWeaponSwingCostReduction"] = 0
        return cost

    def _defend_penalty_for_block(
        self, defender_idx: int, card: Card, *, is_equipment: bool = False
    ) -> int:
        cs = self._players[defender_idx].class_state
        penalty = 0
        if cs.get("NextDefendReactionPenalty", 0) and "defense_reaction" in card.card_types:
            penalty = 1
            cs["NextDefendReactionPenalty"] = 0
        elif cs.get("NextDefendEquipmentPenalty", 0) and is_equipment:
            penalty = 1
            cs["NextDefendEquipmentPenalty"] = 0
        elif (
            cs.get("NextDefendActionPenalty", 0)
            and "attack_action" in card.card_types
            and not is_equipment
        ):
            penalty = 1
            cs["NextDefendActionPenalty"] = 0
        return penalty

    def _apply_equipment_defense_debuff(self, player_idx: int, amount: int = 1) -> None:
        actor = self._players[player_idx]
        if not actor.equipment:
            self._event_append("no equipment to debuff")
            return
        cid = actor.equipment[0]
        self._add_permanent_counter(player_idx, cid, "defense_penalty", amount)
        self._event_append(f"-{amount} defense counter on {self._cards[cid].name}")

    def _consume_pending_next_attack_power(
        self,
        player_idx: int,
        card: Card,
        combat: CombatState,
        *,
        is_weapon: bool = False,
        card_power: Optional[int] = None,
    ) -> None:
        cs = self._players[player_idx].class_state
        pending_power = cs.get("NextAttackPower", 0)
        if pending_power == 0:
            return
        if cs.get("NextAttackWeaponOnly", 0) and not is_weapon:
            return
        if cs.get("NextAttackWeaponClass", ""):
            want = str(cs["NextAttackWeaponClass"]).lower()
            card_name = card.name.lower()
            weapon_id = actor.weapon_id
            weapon_name = (
                self._cards[weapon_id].name.lower() if weapon_id and is_weapon else ""
            )
            if want not in card_name and want not in weapon_name:
                return
        base_power = card_power if card_power is not None else card.power
        min_base = cs.get("NextAttackMinBase", 0)
        if min_base and base_power < min_base:
            return
        max_cost = cs.get("NextAttackPowerMaxCost", -1)
        if max_cost >= 0 and card.cost > max_cost:
            return
        self._apply_combat_power_bonus(
            combat,
            player_idx,
            pending_power,
            reason=f"+{pending_power} power from prior effect",
        )
        cs["NextAttackPower"] = 0
        cs["NextAttackPowerMaxCost"] = 0
        cs["NextAttackMinBase"] = 0
        cs["NextAttackWeaponOnly"] = 0
        cs["NextAttackWeaponClass"] = ""
        hit_rider = cs.pop("NextAttackHitRider", "")
        if hit_rider:
            cs["PendingHitRider"] = hit_rider
        self._apply_named_power_bonuses(player_idx, card, combat)

    def _apply_combat_power_bonus(
        self,
        combat: CombatState,
        player_idx: int,
        amount: int,
        *,
        reason: str = "",
    ) -> int:
        """Apply a power bonus to the current attack, respecting block/reduction effects."""
        if amount == 0 or combat is None:
            return 0
        actor = self._players[player_idx]
        if amount > 0 and actor.class_state.get("BlockPowerGainThisTurn", 0):
            self._event_append("power gain blocked this turn")
            return 0
        if amount > 0 and combat.block_power_gain:
            self._event_append("attack can't gain power")
            return 0
        if amount > 0 and combat.next_power_gain_reduction > 0:
            amount = max(0, amount - combat.next_power_gain_reduction)
            combat.next_power_gain_reduction = 0
            if amount == 0:
                self._event_append("power gain reduced to zero")
                return 0
        combat.attack_bonus += amount
        if reason:
            self._event_append(reason)
        return amount

    def _legal_plays(self, actor_idx: int) -> list[int]:
        actor = self._players[actor_idx]
        if actor.action_points <= 0:
            return []
        plays: list[int] = []
        for i, cid in enumerate(actor.hand):
            card = self._cards[cid]
            if not self._is_playable_action(card):
                continue
            if self._card_requires_arsenal(card):
                continue
            if self._effective_card_cost(actor_idx, card) > actor.resources:
                continue
            if self._play_blocked_reason(actor_idx, i, card):
                continue
            plays.append(i)
        return plays

    def _legal_arsenal_plays(self, actor_idx: int) -> list[int]:
        """Arsenal index (always 0 when legal) for the single stashed card."""
        actor = self._players[actor_idx]
        if actor.action_points <= 0 or not actor.arsenal:
            return []
        card = self._cards[actor.arsenal[0]]
        if not self._is_playable_action(card):
            return []
        if self._effective_card_cost(actor_idx, card) > actor.resources:
            return []
        if self._play_blocked_reason(actor_idx, -1, card, from_arsenal=True):
            return []
        return [0]

    def _in_combat_chain(self) -> bool:
        return self._pending_combat is not None and self._phase in _COMBAT_CHAIN_PHASES

    def _legal_instant_plays(self, actor_idx: int) -> list[int]:
        """Instant cards and play-as-instant utility actions legal right now."""
        actor = self._players[actor_idx]
        in_combat = self._in_combat_chain()
        in_action = self._phase == "action" and self._action_phase_player == actor_idx
        if not in_combat and not in_action:
            return []
        legal: list[int] = []
        for i, cid in enumerate(actor.hand):
            if not self._instant_playable(actor_idx, i, in_action=in_action):
                continue
            legal.append(i)
        return legal

    def _combat_instant_actions_for(self, player_idx: int) -> list[str]:
        """Instant/may-play actions available to a player during an open combat link."""
        if not self._in_combat_chain():
            return []
        actions: list[str] = []
        actions.extend(f"instant {i}" for i in self._legal_instant_plays(player_idx))
        actions.extend(self._legal_may_plays(player_idx))
        if self._can_deck_top_play_now(player_idx):
            actions.append("deckplay")
        return actions

    def _legal_banished_plays(self, actor_idx: int) -> list[int]:
        actor = self._players[actor_idx]
        if actor.action_points <= 0:
            return []
        legal: list[int] = []
        for i, cid in enumerate(actor.banished):
            if not self._can_play_from_banished(actor_idx, cid):
                continue
            card = self._cards[cid]
            if not self._is_playable_action(card):
                continue
            if self._effective_card_cost(actor_idx, card) > actor.resources:
                continue
            legal.append(i)
        return legal

    def _legal_graveyard_plays(self, actor_idx: int) -> list[int]:
        actor = self._players[actor_idx]
        if actor.action_points <= 0:
            return []
        legal: list[int] = []
        for i, cid in enumerate(actor.discard):
            if not self._can_play_from_graveyard(actor_idx, cid):
                continue
            card = self._cards[cid]
            if not self._is_playable_action(card):
                continue
            if self._effective_card_cost(actor_idx, card) > actor.resources:
                continue
            legal.append(i)
        return legal

    def _legal_pitches(
        self,
        actor_idx: int,
        *,
        exclude_card_ids: Optional[set[str]] = None,
    ) -> list[int]:
        actor = self._players[actor_idx]
        blocked = set(actor.arsenal)
        if exclude_card_ids:
            blocked |= exclude_card_ids
        return [
            i
            for i, cid in enumerate(actor.hand)
            if self._cards[cid].pitch > 0
            and cid not in blocked
            and self._cards[cid].pitch not in actor.blocked_pitch_values
        ]

    def _pitchable_total(
        self,
        player_idx: int,
        *,
        exclude_card_ids: Optional[set[str]] = None,
    ) -> int:
        actor = self._players[player_idx]
        blocked = set(actor.arsenal)
        if exclude_card_ids:
            blocked |= exclude_card_ids
        return sum(
            self._cards[cid].pitch
            for cid in actor.hand
            if self._cards[cid].pitch > 0 and cid not in blocked
        )

    def _can_pitch_to_afford(
        self,
        player_idx: int,
        cost: int,
        *,
        exclude_card_ids: Optional[set[str]] = None,
    ) -> bool:
        actor = self._players[player_idx]
        if cost <= 0 or actor.resources >= cost:
            return True
        return actor.resources + self._pitchable_total(
            player_idx, exclude_card_ids=exclude_card_ids
        ) >= cost

    def _instant_playable(self, player_idx: int, hand_idx: int, *, in_action: bool) -> bool:
        actor = self._players[player_idx]
        card = self._cards[actor.hand[hand_idx]]
        if "attack_action" in card.card_types:
            return False
        is_instant_card = "instant" in card.card_types
        is_grant_utility = actor.play_as_instant and "utility_action" in card.card_types
        if not is_instant_card and not is_grant_utility:
            return False
        cls_filter = actor.instant_class_filter
        if cls_filter and cls_filter not in (card.card_class or "").lower():
            return False
        cost = self._effective_card_cost(player_idx, card)
        if not self._can_pitch_to_afford(player_idx, cost, exclude_card_ids={card.id}):
            return False
        if in_action and self._play_blocked_reason(player_idx, hand_idx, card):
            return False
        return True

    def _begin_instant_pay(
        self,
        player_idx: int,
        hand_idx: int,
        perspective_idx: int,
        cost: int,
    ) -> float:
        card = self._cards[self._players[player_idx].hand[hand_idx]]
        self._pending_instant_pay = {
            "player": player_idx,
            "card_id": card.id,
            "perspective": perspective_idx,
            "cost": cost,
            "resume_phase": self._phase,
            "resume_active": self._active_player,
        }
        self._phase = "instant_pay"
        self._active_player = player_idx
        self._last_event = (
            f"P{player_idx} must pitch for {cost} resources to play {card.name} as instant"
        )
        return 0.0

    def _cancel_instant_pay(self) -> None:
        ctx = self._pending_instant_pay
        self._pending_instant_pay = {}
        if not ctx:
            return
        self._phase = ctx.get("resume_phase", "action")
        self._active_player = ctx.get("resume_active", self._active_player)
        self._last_event = "Cancelled instant"

    def _try_complete_instant_pay(self) -> float:
        ctx = self._pending_instant_pay
        if not ctx:
            return 0.0
        player_idx = ctx["player"]
        actor = self._players[player_idx]
        cost = ctx["cost"]
        if actor.resources < cost:
            return 0.0
        hand_idx = next(
            (i for i, cid in enumerate(actor.hand) if cid == ctx["card_id"]),
            None,
        )
        if hand_idx is None:
            self._cancel_instant_pay()
            self._last_event = "Instant card no longer in hand"
            return -0.05
        perspective = ctx["perspective"]
        resume_phase = ctx["resume_phase"]
        resume_active = ctx["resume_active"]
        self._pending_instant_pay = {}
        self._phase = resume_phase
        self._active_player = resume_active
        return self._finish_instant_play(player_idx, hand_idx, perspective)

    @staticmethod
    def _pitch_pay_is_variable(effect: "effects.Effect") -> bool:
        return "up to" in (effect.raw or "").lower()

    def _effect_from_pitch_pay_ctx(self, ctx: dict[str, Any]) -> "effects.Effect":
        e = ctx["effect"]
        return effects.Effect(
            kind=e.get("kind", "pitch_pay"),
            amount=int(e.get("amount", 0)),
            max_cost=int(e.get("max_cost", -1)),
            banish_name=str(e.get("banish_name", "")),
            token_name=str(e.get("token_name", "")),
            optional=bool(e.get("optional", False)),
            raw=str(e.get("raw", "")),
        )

    def _serialize_pitch_pay_effect(self, effect: "effects.Effect") -> dict[str, Any]:
        return {
            "kind": effect.kind,
            "amount": effect.amount,
            "max_cost": effect.max_cost,
            "banish_name": effect.banish_name,
            "token_name": effect.token_name,
            "optional": effect.optional,
            "raw": effect.raw,
        }

    def _can_pay_pitch_cost(self, player_idx: int, cost: int, *, variable: bool) -> bool:
        actor = self._players[player_idx]
        if variable:
            return actor.resources >= 1 or self._pitchable_total(player_idx) > 0
        return self._can_pitch_to_afford(player_idx, cost)

    def _begin_pitch_pay(
        self,
        player_idx: int,
        card: Card,
        effect: "effects.Effect",
        perspective_idx: int,
        *,
        optional_resume: Optional[str] = None,
    ) -> float:
        """Enter a pitch step to pay a {r} asset-cost (CR 1.14.2d)."""
        actor = self._players[player_idx]
        variable = self._pitch_pay_is_variable(effect)
        cost = max(1, effect.amount or 1)

        if not self._can_pay_pitch_cost(player_idx, cost, variable=variable):
            self._event_append("cannot afford pitch cost")
            return -0.05 if not effect.optional else 0.0

        if not variable and actor.resources >= cost:
            actor.resources -= cost
            actor.class_state["LastPitchPayCount"] = cost
            if card.id:
                actor.class_state[f"AdditionalCostPaid:{card.id}"] = 1
            reward = self._resolve_pitch_pay_rider(
                player_idx, card, effect, cost, self._pending_combat, perspective_idx
            )
            self._continue_after_pitch_pay(
                {"optional_resume": optional_resume},
                cancelled=False,
            )
            return reward

        self._pending_pitch_pay = {
            "player": player_idx,
            "card_id": card.id,
            "perspective": perspective_idx,
            "cost": cost,
            "variable": variable,
            "resources_at_start": actor.resources,
            "resume_phase": self._phase,
            "resume_active": self._active_player,
            "optional_resume": optional_resume,
            "effect": self._serialize_pitch_pay_effect(effect),
        }
        self._phase = "pitch_pay"
        self._active_player = player_idx
        if variable:
            self._last_event = (
                f"P{player_idx} may pitch up to {cost} resources for {card.name} "
                f"(pass when done, {actor.resources} ready)"
            )
        else:
            self._last_event = (
                f"P{player_idx} must pitch for {cost} resources to pay for {card.name} "
                f"({actor.resources}/{cost})"
            )
        return 0.0

    def _cancel_pitch_pay(self) -> float:
        ctx = self._pending_pitch_pay
        self._pending_pitch_pay = {}
        if not ctx:
            return 0.0
        self._phase = ctx.get("resume_phase", "action")
        self._active_player = ctx.get("resume_active", self._active_player)
        self._last_event = "Declined pitch cost"
        self._continue_after_pitch_pay(ctx, cancelled=True)
        return 0.0

    def _pass_pitch_pay(self) -> float:
        ctx = self._pending_pitch_pay
        if not ctx:
            return 0.0
        player_idx = ctx["player"]
        actor = self._players[player_idx]
        cost = ctx["cost"]
        if ctx.get("variable"):
            paid = actor.resources - ctx.get("resources_at_start", actor.resources)
            if paid < 1:
                return self._cancel_pitch_pay()
            return self._finish_pitch_pay(min(paid, cost))
        if actor.resources >= cost:
            return self._finish_pitch_pay(cost)
        return self._cancel_pitch_pay()

    def _try_complete_pitch_pay(self) -> float:
        ctx = self._pending_pitch_pay
        if not ctx or ctx.get("variable"):
            return 0.0
        actor = self._players[ctx["player"]]
        cost = ctx["cost"]
        if actor.resources < cost:
            return 0.0
        return self._finish_pitch_pay(cost)

    def _finish_pitch_pay(self, paid: int) -> float:
        ctx = self._pending_pitch_pay
        if not ctx:
            return 0.0
        player_idx = ctx["player"]
        actor = self._players[player_idx]
        paid = max(0, min(paid, ctx["cost"]))
        if paid <= 0:
            return self._cancel_pitch_pay()
        card = self._cards[ctx["card_id"]]
        effect = self._effect_from_pitch_pay_ctx(ctx)
        if actor.resources < paid:
            return self._cancel_pitch_pay()
        actor.resources -= paid
        actor.class_state["LastPitchPayCount"] = paid
        if card.id:
            actor.class_state[f"AdditionalCostPaid:{card.id}"] = 1
        perspective = ctx["perspective"]
        resume_phase = ctx.get("resume_phase", self._phase)
        resume_active = ctx.get("resume_active", self._active_player)
        optional_resume = ctx.get("optional_resume")
        self._pending_pitch_pay = {}
        self._phase = resume_phase
        self._active_player = resume_active
        reward = self._resolve_pitch_pay_rider(
            player_idx, card, effect, paid, self._pending_combat, perspective
        )
        self._continue_after_pitch_pay(
            {"optional_resume": optional_resume},
            cancelled=False,
        )
        return reward

    def _continue_after_pitch_pay(self, ctx: dict[str, Any], *, cancelled: bool) -> None:
        if cancelled:
            self._event_append("declined pitch cost")
        if self._pending_optionals:
            self._phase = "optional"
            self._active_player = self._pending_optionals[0]["player"]
            return
        tag = ctx.get("optional_resume")
        if tag:
            self._optional_resume = tag
            self._resume_after_optional()

    def _resolve_pitch_pay_rider(
        self,
        player_idx: int,
        card: Card,
        effect: "effects.Effect",
        paid: int,
        combat: Optional[CombatState],
        perspective_idx: int,
    ) -> float:
        """Apply the rider after a pitch_pay asset-cost is paid."""
        actor = self._players[player_idx]
        rider = (effect.banish_name or "").lower()
        if paid <= 0:
            self._event_append("declined pitch cost")
            return 0.0
        self._event_append(f"paid {paid} resources")
        if rider == "intimidate":
            target_idx = 1 - player_idx
            for _ in range(paid):
                self._do_intimidate(target_idx)
        elif rider == "defense":
            bonus = max(1, effect.max_cost if effect.max_cost > 0 else 2)
            if combat is not None and combat.blocks:
                idx = len(combat.blocks) - 1
                d_idx, b_cid, val = combat.blocks[idx]
                if d_idx == player_idx:
                    combat.blocks[idx] = (d_idx, b_cid, val + bonus)
                    self._event_append(f"pitch pay: +{bonus} defense on block")
            else:
                actor.class_state["NextDefenseBonus"] = (
                    actor.class_state.get("NextDefenseBonus", 0) + bonus
                )
                self._event_append(f"pitch pay: next defend +{bonus}")
        elif rider == "power":
            bonus = max(1, effect.max_cost if effect.max_cost > 0 else 1)
            if combat is not None:
                self._apply_combat_power_bonus(
                    combat,
                    player_idx,
                    bonus,
                    reason=f"pitch pay: +{bonus} power",
                )
        elif rider == "power_overpower":
            bonus = max(1, effect.max_cost if effect.max_cost > 0 else 1)
            if combat is not None:
                self._apply_combat_power_bonus(
                    combat,
                    player_idx,
                    bonus,
                    reason=f"pitch pay: +{bonus} power and overpower",
                )
                combat.overpower = True
        elif rider == "extra_target":
            actor.extra_attack_targets += 1
            self._event_append("pitch pay: extra attack target")
        elif effect.token_name:
            self._create_token(player_idx, effect.token_name, paid)
        elif rider == "destroy_draw":
            if card.id in actor.equipment:
                actor.equipment.remove(card.id)
            elif card.id == actor.weapon_id:
                actor.weapon_id = None
            if card.id not in actor.discard:
                actor.discard.append(card.id)
                self._fire_on_leave_triggers(player_idx, card.id, perspective_idx)
                self._event_append(f"destroyed {card.name}")
            self._draw_card(player_idx)
        elif rider == "aim_counter":
            arrow_id = actor.class_state.get("LastArrowFromDeckId")
            if not arrow_id and actor.arsenal:
                arrow_id = actor.arsenal[-1]
            if arrow_id:
                self._add_permanent_counter(player_idx, arrow_id, "aim", 1)
                self._event_append(f"put aim counter on {self._cards[arrow_id].name}")
        elif rider.startswith("gain_resources:"):
            gain = int(rider.split(":", 1)[1])
            actor.resources += gain
            self._event_append(f"pitch pay: gained {gain} resources")
        elif rider.startswith("choose_name:"):
            names_str = rider.split(":", 1)[1]
            names = [part.strip() for part in re.split(r", or |, ", names_str) if part.strip()]
            if names:
                chosen = names[self._rng.randrange(len(names))]
                self._permanent_counters(player_idx, card.id)["display_name"] = chosen
                self._event_append(f"{card.name} becomes {chosen}")
        elif rider == "arcane_plus_one":
            actor.class_state["ArcanePlusOneThisPlay"] = 1
            actor.class_state["DestroyMetacarpusEndPhase"] = 1
            self._event_append(
                "arcane damage +1 this play; Metacarpus Node destroys at end phase"
            )
        return 0.0

    def _is_hand_block(self, defender: PlayerState, card_id: str) -> bool:
        return card_id not in defender.equipment and card_id not in defender.arsenal

    def _defender_hand_blocks(self, combat: CombatState, defender_idx: int) -> list[tuple[int, str, int]]:
        defender = self._players[defender_idx]
        return [
            b for b in combat.blocks
            if b[0] == defender_idx and self._is_hand_block(defender, b[1])
        ]

    def _legal_blocks(self, defender_idx: int) -> list[int]:
        combat = self._pending_combat
        if combat is None:
            return []
        hand_blocks = self._defender_hand_blocks(combat, defender_idx)
        # Dominate (CR 8.3.4): at most one defending card from hand.
        if combat.dominate and hand_blocks:
            return []
        action_blocked = any(
            fab_rules.is_action_card(self._cards[b[1]].card_types) for b in hand_blocks
        )
        legal: list[int] = []
        for i, cid in enumerate(self._players[defender_idx].hand):
            card = self._cards[cid]
            if card.defense <= 0:
                continue
            # Defense reactions are played in the defense-reaction step (CR 8.1.3).
            if "defense_reaction" in card.card_types:
                continue
            if combat.defense_reactions_blocked and "defense_reaction" in card.card_types:
                continue
            # Overpower (CR 8.3.22): at most one defending action card.
            if combat.overpower and action_blocked and fab_rules.is_action_card(card.card_types):
                continue
            legal.append(i)
        return legal

    def _legal_reactions(self, attacker_idx: int) -> list[int]:
        attacker = self._players[attacker_idx]
        reactions: list[int] = []
        for i, cid in enumerate(attacker.hand):
            card = self._cards[cid]
            if "attack_reaction" in card.card_types and card.cost <= attacker.resources:
                reactions.append(i)
        return reactions

    def _legal_defense_reactions(self, defender_idx: int) -> list[int]:
        """Defense reaction cards playable during the defense-reaction step."""
        combat = self._pending_combat
        if combat is None or combat.defender != defender_idx:
            return []
        if combat.defense_reactions_blocked:
            return []
        if self._players[defender_idx].class_state.get("BlockDefenseReactionsTurn", 0):
            return []
        hand_blocks = self._defender_hand_blocks(combat, defender_idx)
        if combat.dominate and hand_blocks:
            return []
        action_blocked = any(
            fab_rules.is_action_card(self._cards[b[1]].card_types) for b in hand_blocks
        )
        defender = self._players[defender_idx]
        legal: list[int] = []
        for i, cid in enumerate(defender.hand):
            card = self._cards[cid]
            if "defense_reaction" not in card.card_types:
                continue
            if self._card_requires_arsenal(card):
                continue
            cost = self._effective_card_cost(defender_idx, card) + defender.extra_defense_reaction_cost
            if cost > defender.resources:
                continue
            if card.defense <= 0:
                has_defend_effect = any(
                    trig.when == "on_defend" and trig.effect.implemented
                    for trig in effects.parse_triggers(card.text)
                )
                if not has_defend_effect:
                    continue
            if combat.overpower and action_blocked and fab_rules.is_action_card(card.card_types):
                continue
            legal.append(i)
        return legal

    def _can_weapon_attack(self, actor_idx: int) -> bool:
        actor = self._players[actor_idx]
        _, attack, cost, _ = self._weapon_stats(actor_idx)
        extra = actor.class_state.get("ExtraWeaponAttacks", 0)
        swing_extra = self._first_attack_extra_cost(actor_idx, is_attack=True)
        eff_cost = self._effective_weapon_swing_cost(actor_idx, cost, consume=False)
        if attack <= 0 or actor.action_points <= 0 or actor.resources < eff_cost + swing_extra:
            return False
        if actor.weapon_used and extra <= 0:
            return False
        if actor.weapon_attacks_blocked:
            return False
        return True

    def _ability_list(self, actor_idx: int) -> list[dict[str, Any]]:
        """Ordered activated abilities available from this player's arena.

        Each entry exposes a stable index used by the ``ability <i>`` action.
        Equipment slots come first (in slot order), then the hero ability.
        Only abilities whose effect we can resolve faithfully are listed.
        """
        actor = self._players[actor_idx]
        entries: list[dict[str, Any]] = []
        for cid in actor.equipment:
            card = self._cards[cid]
            for ability in effects.parse_activated_abilities(card.text):
                if ability.implemented:
                    entries.append(
                        {"token": f"equip:{cid}", "name": card.name, "ability": ability, "card_id": cid}
                    )
        if actor.weapon_id is not None:
            weapon = self._cards[actor.weapon_id]
            for wab in effects.parse_activated_abilities(weapon.text):
                if wab.implemented:
                    entries.append(
                        {
                            "token": f"weapon:{actor.weapon_id}",
                            "name": weapon.name,
                            "ability": wab,
                            "card_id": actor.weapon_id,
                        }
                    )
        for hero_ability in effects.parse_activated_abilities(actor.hero.ability_text):
            if hero_ability.implemented:
                entries.append(
                    {
                        "token": "hero",
                        "name": f"{actor.hero.name} (hero)",
                        "ability": hero_ability,
                        "card_id": "",
                    }
                )
        return entries

    def _ability_usable(self, actor_idx: int, entry: dict[str, Any]) -> bool:
        actor = self._players[actor_idx]
        ability = entry["ability"]
        if self._play_restriction_kind == "weapon_attack_only" and ability.effect.kind != "attack":
            return False
        reduction = actor.class_state.get("NextAbilityCostReduction", 0)
        eff_cost = max(0, ability.cost - reduction)
        if ability.effect.kind == "attack" and entry.get("card_id"):
            item = self._cards.get(entry["card_id"])
            if item and item.power > 0 and entry["card_id"] in actor.equipment:
                eff_cost += self._first_attack_extra_cost(actor_idx, is_attack=True)
        if eff_cost > actor.resources:
            return False
        if ability.uses_action_point and actor.action_points <= 0:
            return False
        if ability.once_per_turn and entry["token"] in actor.arena_used:
            return False
        cid = entry.get("card_id") or ""
        if ability.counter_cost > 0 and cid:
            if self._permanent_counters(actor_idx, cid).get(ability.counter_name, 0) < ability.counter_cost:
                return False
        return True

    def _legal_abilities(self, actor_idx: int) -> list[int]:
        entries = self._ability_list(actor_idx)
        return [i for i, e in enumerate(entries) if self._ability_usable(actor_idx, e)]

    def _legal_stash(self, actor_idx: int) -> list[int]:
        """Hand indices that may be stashed face-down into the arsenal."""
        actor = self._players[actor_idx]
        if actor.arsenal:
            return []
        return list(range(len(actor.hand)))

    def _legal_gear_blocks(self, defender_idx: int) -> list[int]:
        """Equipment indices that can still block the pending attack."""
        combat = self._pending_combat
        if combat is None:
            return []
        defender = self._players[defender_idx]
        usable: list[int] = []
        for i, cid in enumerate(defender.equipment):
            card = self._cards[cid]
            if card.defense <= 0:
                continue
            if f"equip:{cid}" in defender.arena_used:
                continue
            usable.append(i)
        return usable

    def _is_trap_card(self, card: Card) -> bool:
        return "trap" in (card.type_line or "").lower()

    def _can_defend_from_arsenal(self, card: Card) -> bool:
        """Ambush / trap cards in arsenal may defend during the defend step (CR 8.3.28)."""
        if card.defense <= 0:
            return False
        if self._is_trap_card(card):
            return True
        return "ambush" in card.keywords

    def _legal_trap_defense(self, defender_idx: int) -> bool:
        combat = self._pending_combat
        if combat is None or combat.defender != defender_idx:
            return False
        defender = self._players[defender_idx]
        if not defender.arsenal:
            return False
        card = self._cards[defender.arsenal[0]]
        if not self._can_defend_from_arsenal(card):
            return False
        hand_blocks = self._defender_hand_blocks(combat, defender_idx)
        action_blocked = any(
            fab_rules.is_action_card(self._cards[b[1]].card_types) for b in hand_blocks
        )
        if combat.overpower and action_blocked and fab_rules.is_action_card(card.card_types):
            return False
        return True

    # ------------------------------------------------------------------
    # Low-level state mutators (used by both human/agent and opponent)
    # ------------------------------------------------------------------
    def _record_opponent_pitch(self, player_idx: int, card: Card) -> None:
        if player_idx != 1:
            return
        if self._action_phase_player != 1 or self._phase != "action":
            return
        if self._last_opponent_turn is None:
            return
        pitches = self._last_opponent_turn.setdefault("pitches", [])
        pitches.append({"name": card.name, "pitch": card.pitch})

    def _record_opponent_attack(
        self,
        player_idx: int,
        *,
        attack_name: str,
        attack_power: int,
        is_weapon: bool = False,
    ) -> None:
        if player_idx != 1 or self._last_opponent_turn is None:
            return
        self._last_opponent_turn["attack_card"] = attack_name
        self._last_opponent_turn["attack_power"] = attack_power
        self._last_opponent_turn["is_weapon"] = is_weapon

    def _do_pitch(self, player_idx: int, hand_idx: int) -> float:
        p = self._players[player_idx]
        if hand_idx < 0 or hand_idx >= len(p.hand):
            self._last_event = "No such card to pitch"
            return -0.05
        card = self._cards[p.hand[hand_idx]]
        if card.id in p.arsenal:
            self._last_event = f"{card.name} cannot be pitched from arsenal"
            return -0.05
        if card.pitch <= 0:
            self._last_event = f"{card.name} cannot be pitched"
            return -0.05
        if card.pitch in p.blocked_pitch_values:
            color = {1: "red", 2: "yellow", 3: "blue"}.get(card.pitch, "that color")
            self._last_event = f"{card.name} cannot be pitched ({color} blocked)"
            return -0.05
        p.hand.pop(hand_idx)
        p.pitch_zone.append(card.id)
        p.resources += card.pitch
        if (
            p.class_state.get("PitchBonusLightPlusOne")
            and p.class_state.get("SoulCardThisTurn", 0) > 0
            and (card.talent or "").lower() == "light"
        ):
            p.resources += 1
            self._event_append("Vestige of Sol: +1 resource")
        self._record_opponent_pitch(player_idx, card)
        self._last_event = f"P{player_idx} pitches {card.name} (+{card.pitch} resources)"
        if card.power >= 6:
            p.class_state["PitchedPower6ThisTurn"] = 1
        reward = 0.0
        for trig in effects.parse_triggers(card.text):
            if trig.when != "on_pitched":
                continue
            reward += self._apply_effect(player_idx, card, trig.effect, None, player_idx)
        if self._pending_instant_pay:
            reward += self._try_complete_instant_pay()
        if self._pending_pitch_pay:
            reward += self._try_complete_pitch_pay()
        return reward

    @staticmethod
    def _play_suffix(fused: bool, elements: tuple[str, ...], go_again: bool) -> str:
        if fused and elements:
            return f" [fused: {', '.join(elements)}]"
        if go_again:
            return " [go again]"
        return ""

    def _note(self, message: str) -> None:
        """Record a player-facing notice (e.g. an unimplemented interaction)."""
        if message not in self._notices:
            self._notices.append(message)

    def _event_append(self, message: str) -> None:
        """Append a positive trigger result to the current event line."""
        self._last_event = f"{self._last_event} | {message}" if self._last_event else message

    @staticmethod
    def _is_lightning_action(card: Card) -> bool:
        return (card.talent or "").strip().lower() == "lightning"

    @staticmethod
    def _intrinsic_go_again(card: Card) -> bool:
        """Printed go again keyword, unless rules text gates it behind a condition."""
        if "go_again" not in card.keywords:
            return False
        text = str(card.text or "").lower()
        if re.search(r"\bif .+ get(s)? ?(?:\*\*)?go again", text):
            return False
        return True

    def _go_again_for_play(self, player_idx: int, card: Card, is_utility: bool) -> bool:
        """Whether this action should have go again when played (flags + keyword)."""
        actor = self._players[player_idx]
        cs = actor.class_state
        go_again = False
        pending = cs.get("NextActionGoAgain", 0)
        if pending > 0:
            go_again = True
            cs["NextActionGoAgain"] = pending - 1
            self._event_append("go again from pending flag")
        if is_utility and cs.get("NextNAACardGoAgain", 0) > 0:
            go_again = True
            cs["NextNAACardGoAgain"] = 0
        if self._intrinsic_go_again(card):
            go_again = True
        if actor.silenced:
            return False
        return go_again

    def _grant_go_again(
        self,
        player_idx: int,
        combat: Optional[CombatState] = None,
        *,
        this_card: bool = True,
        next_actions: int = 0,
    ) -> None:
        """Grant go again to the current chain link and/or future action(s)."""
        actor = self._players[player_idx]
        if actor.silenced:
            self._event_append("silenced — cannot gain go again")
            return
        if this_card:
            if combat is not None:
                combat.go_again = True
            else:
                actor.action_points += 1
        if next_actions > 0:
            actor.class_state["NextActionGoAgain"] = actor.class_state.get("NextActionGoAgain", 0) + next_actions
            label = "action" if next_actions == 1 else "actions"
            self._event_append(f"next {next_actions} {label} gain go again")
        self._fire_whenever_go_again_triggers(player_idx)

    def _fire_whenever_go_again_triggers(self, player_idx: int) -> None:
        """Fire 'whenever you go again this turn' on arena permanents."""
        actor = self._players[player_idx]
        sources: list[Card] = []
        for cid in actor.equipment:
            sources.append(self._cards[cid])
        if actor.weapon_id:
            sources.append(self._cards[actor.weapon_id])
        for card in sources:
            for trig in effects.parse_triggers(card.text):
                if trig.when != "whenever_go_again":
                    continue
                self._apply_effect(player_idx, card, trig.effect, self._pending_combat, player_idx)

    def _process_blood_debt(self, player_idx: int) -> None:
        """Blood Debt — lose 1 at beginning of end phase for public banished cards (CR 8.3.11)."""
        actor = self._players[player_idx]
        debt = 0
        for cid in actor.banished:
            card = self._cards[cid]
            if "blood_debt" in card.keywords or "blood debt" in card.text.lower():
                debt += 1
        if debt:
            actor.life -= debt
            self._event_append(f"blood debt: -{debt} life")

    def _do_intimidate(self, target_idx: int) -> None:
        """Intimidate — banish random hand card face-down until end phase (CR 8.5.10)."""
        target = self._players[target_idx]
        if not target.hand:
            self._event_append(f"P{target_idx} intimidated (empty hand)")
            return
        idx = self._rng.randint(0, len(target.hand) - 1)
        cid = target.hand.pop(idx)
        target.intimidated.append(cid)
        self._event_append(f"P{target_idx} intimidated: {self._cards[cid].name} face-down")

    def _do_clash(
        self,
        player_idx: int,
        token_name: str = "",
        *,
        loser_debuff: bool = False,
        routine: str = "",
        source_card: Optional[Card] = None,
    ) -> None:
        """Clash — reveal deck tops, highest power wins (CR 8.5.45)."""
        opponent_idx = 1 - player_idx
        a_top = self._deck_top_card_id(player_idx)
        d_top = self._deck_top_card_id(opponent_idx)
        a_power = self._cards[a_top].power if a_top else None
        d_power = self._cards[d_top].power if d_top else None
        if a_top:
            self._event_append(f"clash reveal P{player_idx}: {self._cards[a_top].name} ({a_power})")
        if d_top:
            self._event_append(f"clash reveal P{opponent_idx}: {self._cards[d_top].name} ({d_power})")
        result = fab_rules.resolve_clash(a_power, d_power)
        if result.tie:
            self._event_append("clash tied")
            return
        routine = (routine or "").lower()
        if routine == "hit_hero_routine":
            if result.attacker_wins:
                self._destroy_top_of_deck(opponent_idx, 1)
            else:
                if source_card is not None and source_card.id:
                    counters = self._permanent_counters(player_idx, source_card.id)
                    counters["power"] = counters.get("power", 0) - 1
                    self._event_append(f"-1 power counter on {source_card.name}")
            return
        if routine == "destroy_top_loser":
            loser_idx = opponent_idx if result.attacker_wins else player_idx
            self._destroy_top_of_deck(loser_idx, 1)
            return
        if loser_debuff:
            loser_idx = opponent_idx if result.attacker_wins else player_idx
            self._apply_equipment_defense_debuff(loser_idx)
            return
        if result.attacker_wins and token_name:
            self._create_token(player_idx, token_name)
            self._event_append(f"clash won — created {token_name}")
        elif result.defender_wins and token_name:
            self._create_token(opponent_idx, token_name)
            self._event_append(f"clash lost — opponent gets {token_name}")

    def _do_opt(self, player_idx: int, amount: int) -> None:
        """Opt N — look at top N, put each on top or bottom (CR 8.5.22)."""
        actor = self._players[player_idx]
        looked: list[str] = []
        for _ in range(max(1, amount)):
            if not actor.deck and actor.discard:
                actor.deck = actor.discard
                actor.discard = []
                self._rng.shuffle(actor.deck)
            if not actor.deck:
                break
            looked.append(actor.deck.pop())
        if not looked:
            return
        needs_decision = (player_idx == 0 and not self._self_play) or self._self_play
        if needs_decision:
            self._opt_ctx = {
                "player": player_idx,
                "cards": looked,
                "index": 0,
                "top": [],
                "bottom": [],
            }
            self._opt_resume = {"phase": self._phase, "active": self._active_player}
            self._phase = "opt"
            self._active_player = player_idx
            card = self._cards[looked[0]]
            self._event_append(
                f"opt {len(looked)}: choose top/bottom for {card.name} (1/{len(looked)})"
            )
            return
        actor.deck.extend(reversed(looked))
        names = ", ".join(self._cards[c].name for c in looked)
        self._event_append(f"opt {len(looked)}: kept {names} on top")

    def _do_opt_choice(self, player_idx: int, *, to_bottom: bool) -> None:
        ctx = self._opt_ctx
        if not ctx or ctx.get("player") != player_idx:
            return
        i = ctx["index"]
        cid = ctx["cards"][i]
        if to_bottom:
            ctx["bottom"].append(cid)
        else:
            ctx["top"].append(cid)
        ctx["index"] += 1
        if ctx["index"] < len(ctx["cards"]):
            next_cid = ctx["cards"][ctx["index"]]
            self._event_append(
                f"opt: choose top/bottom for {self._cards[next_cid].name} "
                f"({ctx['index'] + 1}/{len(ctx['cards'])})"
            )
            return
        self._finish_opt()

    def _finish_opt(self) -> None:
        ctx = self._opt_ctx
        if not ctx:
            return
        actor = self._players[ctx["player"]]
        for cid in reversed(ctx["top"]):
            actor.deck.append(cid)
        for cid in ctx["bottom"]:
            actor.deck.insert(0, cid)
        top_names = ", ".join(self._cards[c].name for c in ctx["top"]) or "none"
        bot_names = ", ".join(self._cards[c].name for c in ctx["bottom"]) or "none"
        self._event_append(f"opt done: top=[{top_names}] bottom=[{bot_names}]")
        resume = self._opt_resume or {"phase": "action", "active": ctx["player"]}
        self._opt_ctx = {}
        self._opt_resume = None
        self._phase = resume.get("phase", "action")
        self._active_player = resume.get("active", ctx["player"])

    def _find_gambler_gloves(self) -> tuple[Optional[int], Optional[str]]:
        for owner_idx in (0, 1):
            for cid in self._players[owner_idx].equipment:
                card = self._cards[cid]
                if "gambler" not in card.name.lower():
                    continue
                for trig in effects.parse_triggers(card.text):
                    if trig.when == "on_die_roll" and trig.effect.kind == "destroy_item":
                        return owner_idx, cid
        return None, None

    def _pause_for_gambler(self, controller_idx: int) -> bool:
        """Offer Gambler's Gloves before a d6 roll. Returns True if paused."""
        owner, cid = self._find_gambler_gloves()
        if cid is None:
            return False
        pending = dict(self._pending_die_roll or {})
        pending["controller"] = controller_idx
        pending.setdefault("reroll", False)
        self._pending_die_roll = pending
        if owner == 1 and not self._self_play:
            return False
        self._pending_optionals.append(
            {
                "player": owner,
                "card_id": cid,
                "effect": effects.Effect(
                    "destroy_item",
                    banish_name="reroll_d6",
                    optional=True,
                    raw="destroy Gambler's Gloves to reroll",
                ),
                "perspective": owner,
            }
        )
        self._optional_resume = "die_roll"
        self._phase = "optional"
        self._active_player = owner
        return True

    def _roll_d6(self, controller_idx: int, *, allow_intercept: bool = True) -> int:
        """Roll a d6; tracks Rolled6ThisTurn."""
        ctx = self._pending_die_roll if isinstance(self._pending_die_roll, dict) else {}
        reroll = bool(ctx.get("reroll"))
        if reroll and isinstance(self._pending_die_roll, dict):
            self._pending_die_roll.pop("reroll", None)
        roll = self._rng.randint(1, 6)
        if reroll:
            self._event_append(f"Gambler's Gloves: rerolled {roll}")
        if roll == 6:
            self._players[controller_idx].class_state["Rolled6ThisTurn"] = 1
        return roll

    def _apply_kayo_power6(self, player_idx: int, attack_card: Card, combat: CombatState) -> None:
        actor = self._players[player_idx]
        if attack_card.power < 6:
            return
        if not any(
            t.when == "whenever_power6_attack"
            for t in effects.parse_triggers(actor.hero.ability_text)
        ):
            return
        self._pending_die_roll = {
            "controller": player_idx,
            "kind": "kayo",
            "card_id": attack_card.id,
        }
        if self._pause_for_gambler(player_idx):
            return
        self._continue_pending_die_roll()

    def _continue_pending_die_roll(self) -> None:
        ctx = dict(self._pending_die_roll or {})
        if not ctx:
            return
        kind = ctx.get("kind")
        controller = int(ctx.get("controller", 0))
        roll = self._roll_d6(controller, allow_intercept=False)
        if kind == "kayo":
            card = self._cards.get(ctx.get("card_id", ""))
            combat = self._pending_combat
            if card and combat:
                if roll <= 4:
                    combat.attack_power = card.power // 2
                else:
                    combat.attack_power = card.power * 2
                self._event_append(
                    f"Kayo roll {roll}: base power {card.power} -> {combat.attack_power}"
                )
        elif kind == "gain_ap_half":
            actor = self._players[controller]
            ap = roll // 2
            actor.action_points += ap
            self._event_append(f"rolled {roll}: gained {ap} action point(s)")
        elif kind == "gain_resources_half":
            actor = self._players[controller]
            res = roll // 2
            actor.resources += res
            self._event_append(f"rolled {roll}: gained {res} resource(s)")
        elif kind == "prevent_d6":
            target = self._players[controller]
            target.prevent_damage += roll
            self._event_append(
                f"P{controller} rolled {roll}: will prevent {roll} damage this turn"
            )
        self._pending_die_roll = None

    def _apply_card_choice_rider(
        self,
        target_idx: int,
        card_id: str,
        rider: str,
        chooser_idx: int,
    ) -> None:
        target = self._players[target_idx]
        parts = (rider or "").lower().split(":")
        action = parts[0] if parts else ""
        if action == "banish_same_name":
            limit = int(parts[1]) if len(parts) > 1 else 3
            self._banish_same_name_cards(target_idx, card_id, limit)
            target.revealed_hand = []
            return
        if card_id not in target.hand and action != "destroy_permanent":
            return
        if action == "destroy_permanent":
            if card_id in target.equipment:
                target.equipment.remove(card_id)
                target.discard.append(card_id)
                self._fire_on_leave_triggers(target_idx, card_id, chooser_idx)
                self._event_append(f"destroyed {self._cards[card_id].name}")
            return
        target.hand.remove(card_id)
        if action == "put_bottom":
            target.deck.insert(0, card_id)
            self._event_append(f"put {self._cards[card_id].name} on bottom of deck")
            if len(parts) > 1 and parts[1] == "draw":
                self._draw_card(target_idx, from_action=True)
                self._event_append("defender drew a card")
        elif action == "discard":
            target.discard.append(card_id)
            self._event_append(f"{self._cards[card_id].name} discarded")
            if len(parts) > 1 and parts[1] == "draw":
                self._draw_card(chooser_idx, from_action=True)
        elif action == "banish":
            target.banished.append(card_id)
            self._event_append(f"banished {self._cards[card_id].name}")
        target.revealed_hand = [c for c in target.revealed_hand if c != card_id]

    def _choice_options_for_hand(
        self,
        target_idx: int,
        *,
        from_revealed: bool = False,
        filter_no_defense: bool = False,
    ) -> list[dict[str, Any]]:
        target = self._players[target_idx]
        pool = list(target.revealed_hand if from_revealed else target.hand)
        if filter_no_defense:
            pool = [cid for cid in pool if self._cards[cid].defense <= 0]
        return [
            {"index": i, "card_id": cid, "name": self._cards[cid].name}
            for i, cid in enumerate(pool)
        ]

    def _begin_card_choice(
        self,
        chooser_idx: int,
        target_idx: int,
        options: list[dict[str, Any]],
        *,
        rider: str,
        optional: bool,
        prompt: str,
        resume: str,
    ) -> bool:
        """Return True if choice phase started (paused). False if auto-resolved."""
        if not options:
            return False
        if optional and len(options) == 0:
            return False
        needs_ui = (chooser_idx == 0 and not self._self_play) or self._self_play
        if not needs_ui:
            pick = self._rng.randrange(len(options))
            cid = options[pick]["card_id"]
            self._apply_card_choice_rider(target_idx, cid, rider, chooser_idx)
            return False
        self._choice_ctx = {
            "chooser": chooser_idx,
            "target": target_idx,
            "options": options,
            "rider": rider,
            "optional": optional,
            "prompt": prompt,
            "resume": resume,
        }
        self._choice_resume = resume
        self._phase = "choice"
        self._active_player = chooser_idx
        names = ", ".join(o["name"] for o in options)
        self._event_append(f"choose a card: {names}")
        return True

    def _record_soul_banish_chain(self, player_idx: int) -> None:
        if self._pending_combat is None:
            return
        cs = self._players[player_idx].class_state
        cs["SoulBanishedThisChain"] = cs.get("SoulBanishedThisChain", 0) + 1

    def _reset_chain_soul_counters(self) -> None:
        for player in self._players:
            player.class_state["SoulBanishedThisChain"] = 0

    def _mode_pick_count(self, effect: effects.Effect, player_idx: int, card: Card) -> int:
        pick = effect.condition or ""
        actor = self._players[player_idx]
        if pick == "pick:soul_banish_chain":
            return int(actor.class_state.get("SoulBanishedThisChain", 0))
        if pick == "pick:blue_pitched":
            return sum(1 for cid in actor.pitch_zone if self._cards[cid].pitch == 3)
        if pick == "pick:fixed:2":
            return 2
        if pick == "pick:random:1":
            return 1
        if pick.startswith("pick:played_blue_other:"):
            parts = pick.split(":")
            hi, lo = int(parts[2]), int(parts[3])
            if self._effect_condition_met(player_idx, "played_blue_other", card):
                return hi
            return lo
        return 0

    def _decode_mode_specs(self, encoded: str) -> list[effects.Effect]:
        out: list[effects.Effect] = []
        for part in (encoded or "").split("|"):
            if not part:
                continue
            fields = part.split(":")
            kind = fields[0]
            if kind == "create_token" and len(fields) >= 2:
                payload = part.split(":", 1)[1]
                amt_s, rest = payload.split(":", 1)
                name, tgt = rest.rsplit(":", 1)
                out.append(
                    effects.Effect(
                        "create_token",
                        int(amt_s),
                        token_name=name,
                        target=tgt,
                    )
                )
            elif kind == "draw" and len(fields) >= 3:
                out.append(effects.Effect("draw", int(fields[1]), target=fields[2]))
            elif kind == "gain_life" and len(fields) >= 3:
                out.append(effects.Effect("gain_life", int(fields[1]), target=fields[2]))
            elif kind == "power" and len(fields) >= 2:
                out.append(effects.Effect("power", int(fields[1])))
            elif kind == "go_again":
                out.append(effects.Effect("go_again"))
            elif kind == "put_counter" and len(fields) >= 4:
                out.append(
                    effects.Effect(
                        "put_counter",
                        int(fields[1]),
                        token_name=fields[2],
                        banish_name=fields[3],
                    )
                )
            elif kind == "create_in_hand" and len(fields) >= 2:
                payload = part.split(":", 1)[1]
                amt_s, rest = payload.split(":", 1)
                name, tgt = rest.rsplit(":", 1)
                out.append(
                    effects.Effect(
                        "create_in_hand",
                        int(amt_s),
                        banish_name=name,
                        target=tgt,
                    )
                )
            elif kind == "named_power_bonus" and len(fields) >= 2:
                payload = part.split(":", 1)[1]
                amt_s, rest = payload.split(":", 1)
                name, tgt = rest.rsplit(":", 1)
                out.append(
                    effects.Effect(
                        "named_power_bonus",
                        int(amt_s),
                        token_name=name,
                        target=tgt,
                    )
                )
            elif kind == "banish_graveyard" and len(fields) >= 3:
                out.append(
                    effects.Effect(
                        "banish_graveyard",
                        int(fields[1]),
                        target=fields[2],
                    )
                )
            elif kind == "equip_inventory":
                out.append(
                    effects.Effect(
                        "equip_inventory",
                        banish_name=fields[2] if len(fields) > 2 else "",
                    )
                )
            elif kind == "modular_equip":
                out.append(effects.Effect("modular_equip"))
            elif kind == "destroy_hand" and len(fields) >= 2:
                payload = part.split(":", 1)[1]
                amt_s, rest = payload.split(":", 1)
                name, tgt = rest.rsplit(":", 1)
                out.append(
                    effects.Effect(
                        "destroy_hand",
                        int(amt_s),
                        banish_name=name,
                        target=tgt,
                    )
                )
            elif kind == "banish_arsenal" and len(fields) >= 3:
                out.append(
                    effects.Effect(
                        "banish_arsenal",
                        target=fields[2],
                    )
                )
            elif kind == "banish_top" and len(fields) >= 3:
                out.append(
                    effects.Effect(
                        "banish_top",
                        int(fields[1]),
                        target=fields[2],
                    )
                )
            elif kind == "transcend":
                out.append(effects.Effect("transcend"))
        return out

    def _apply_mode_spec(
        self,
        player_idx: int,
        card: Card,
        mode_eff: effects.Effect,
        combat: Optional[CombatState],
        perspective_idx: int,
    ) -> None:
        if mode_eff.target == "each_hero":
            for idx in (0, 1):
                hero_eff = effects.Effect(
                    mode_eff.kind,
                    mode_eff.amount,
                    token_name=mode_eff.token_name,
                    target="self",
                    banish_name=mode_eff.banish_name,
                )
                self._apply_effect(idx, card, hero_eff, combat, perspective_idx)
            return
        self._apply_effect(player_idx, card, mode_eff, combat, perspective_idx)

    def _resume_after_choice(self, ctx: dict[str, Any]) -> float:
        chooser_idx = int(ctx["chooser"])
        resume = str(ctx.get("resume", ""))
        self._choice_resume = None
        if resume == "after_play":
            card_id = ctx.get("card_id")
            if card_id:
                play_card = self._cards[card_id]
                fused = bool(ctx.get("fused"))
                perspective = int(ctx.get("perspective", chooser_idx))
                self._phase = str(ctx.get("return_phase", "action"))
                self._active_player = chooser_idx
                return self._finish_attack_triggers(chooser_idx, play_card, perspective, fused)
        if resume == "after_attack":
            self._phase = str(ctx.get("return_phase", "action"))
            self._active_player = chooser_idx
            self._enter_defense()
            return 0.0
        if resume == "after_play_direct":
            self._phase = "action"
            self._active_player = chooser_idx
            return 0.0
        if resume == "after_hit_combat":
            fin = ctx.get("combat_finish") or {}
            if fin:
                return self._complete_combat_resolution(
                    float(fin.get("reward", 0.0)),
                    int(fin.get("perspective", chooser_idx)),
                    int(fin.get("attacker_idx", chooser_idx)),
                    int(fin.get("defender_idx", 1 - chooser_idx)),
                    int(fin.get("damage", 0)),
                    bool(fin.get("go_again")),
                    bool(fin.get("fused")),
                )
            self._phase = str(ctx.get("return_phase", "action"))
            self._active_player = chooser_idx
            return 0.0
        if resume == "after_hit":
            self._phase = str(ctx.get("return_phase", "action"))
            self._active_player = chooser_idx
            return 0.0
        self._phase = str(ctx.get("return_phase", "action"))
        self._active_player = chooser_idx
        return 0.0

    def _begin_mode_choice(
        self,
        chooser_idx: int,
        card: Card,
        effect: effects.Effect,
        *,
        resume: str,
        perspective_idx: int,
        combat: Optional[CombatState],
    ) -> bool:
        pick_any = (effect.condition or "") == "pick:any"
        pick_random = (effect.condition or "") == "pick:random:1"
        picks = self._mode_pick_count(effect, chooser_idx, card)
        if not pick_any and not pick_random and picks <= 0:
            return False
        mode_specs = self._decode_mode_specs(effect.banish_name or "")
        if len(mode_specs) < 2:
            return False
        if pick_random:
            idx = self._rng.randrange(len(mode_specs))
            self._apply_mode_spec(
                chooser_idx, card, mode_specs[idx], combat, perspective_idx
            )
            return False
        labels = (effect.token_name or "").split("|")
        options = [
            {
                "index": i,
                "name": labels[i] if i < len(labels) else (mode_specs[i].raw or f"Mode {i}"),
                "mode_idx": i,
            }
            for i in range(len(mode_specs))
        ]
        needs_ui = (chooser_idx == 0 and not self._self_play) or self._self_play
        if not needs_ui:
            picked = [0] * len(mode_specs)
            if pick_any:
                count = self._rng.randint(0, len(mode_specs))
                for idx in self._rng.sample(range(len(mode_specs)), count):
                    self._apply_mode_spec(
                        chooser_idx, card, mode_specs[idx], combat, perspective_idx
                    )
            else:
                for _ in range(picks):
                    legal = [
                        i
                        for i in range(len(mode_specs))
                        if picked[i] < max(1, effect.amount or 1)
                    ]
                    if not legal:
                        break
                    idx = legal[self._rng.randrange(len(legal))]
                    picked[idx] += 1
                    self._apply_mode_spec(
                        chooser_idx, card, mode_specs[idx], combat, perspective_idx
                    )
            return False
        prompt = effect.raw or "Choose a mode"
        if pick_any:
            prompt = f"{prompt} (pass when done)"
        elif picks > 1:
            prompt = f"{prompt} ({picks} remaining)"
        self._choice_ctx = {
            "kind": "mode",
            "chooser": chooser_idx,
            "target": chooser_idx,
            "options": options,
            "modes_enc": effect.banish_name or "",
            "max_per_mode": max(1, effect.amount or 1),
            "picks_remaining": picks,
            "pick_any": pick_any,
            "picked": [0] * len(mode_specs),
            "selected_any": [],
            "optional": pick_any,
            "prompt": prompt,
            "resume": resume,
            "card_id": card.id,
            "fused": bool(combat.fused if combat else False),
            "perspective": perspective_idx,
            "return_phase": self._phase,
        }
        self._choice_resume = resume
        self._phase = "choice"
        self._active_player = chooser_idx
        self._event_append(f"choose mode: {', '.join(o['name'] for o in options)}")
        return True

    def _resolve_mode_choice(self, choice_idx: Optional[int]) -> float:
        ctx = self._choice_ctx
        if not ctx:
            return 0.0
        chooser_idx = int(ctx["chooser"])
        pick_any = bool(ctx.get("pick_any"))
        optional = bool(ctx.get("optional"))
        mode_specs = self._decode_mode_specs(str(ctx.get("modes_enc", "")))
        card = self._cards[str(ctx["card_id"])]
        combat = self._pending_combat
        perspective = int(ctx.get("perspective", chooser_idx))
        picked = list(ctx.get("picked") or [0] * len(mode_specs))
        max_per = int(ctx.get("max_per_mode") or 1)

        if choice_idx is None:
            if pick_any or optional:
                self._choice_ctx = {}
                self._event_append("finished mode choice")
                return self._resume_after_choice(ctx)
            self._event_append("must choose a mode")
            return 0.0

        options = ctx.get("options") or []
        if choice_idx < 0 or choice_idx >= len(options):
            return 0.0
        mode_idx = int(options[choice_idx].get("mode_idx", choice_idx))
        if mode_idx < 0 or mode_idx >= len(mode_specs):
            return 0.0
        if picked[mode_idx] >= max_per:
            return 0.0

        self._apply_mode_spec(chooser_idx, card, mode_specs[mode_idx], combat, perspective)
        picked[mode_idx] += 1
        label = options[choice_idx].get("name", f"mode {mode_idx}")
        self._event_append(f"chose mode: {label}")

        if pick_any:
            selected = set(ctx.get("selected_any") or [])
            selected.add(mode_idx)
            remaining = [o for o in options if int(o.get("mode_idx", -1)) not in selected]
            if not remaining:
                self._choice_ctx = {}
                return self._resume_after_choice(ctx)
            ctx["picked"] = picked
            ctx["selected_any"] = list(selected)
            ctx["options"] = remaining
            self._choice_ctx = ctx
            return 0.0

        picks_left = int(ctx.get("picks_remaining", 0)) - 1
        if picks_left <= 0:
            self._choice_ctx = {}
            return self._resume_after_choice(ctx)
        ctx["picked"] = picked
        ctx["picks_remaining"] = picks_left
        ctx["prompt"] = f"{ctx.get('prompt', 'Choose a mode').split('(')[0].strip()} ({picks_left} remaining)"
        self._choice_ctx = ctx
        return 0.0

    def _resolve_card_choice(self, choice_idx: Optional[int]) -> float:
        ctx = self._choice_ctx
        if not ctx:
            return 0.0
        if ctx.get("kind") == "mode":
            return self._resolve_mode_choice(choice_idx)
        chooser_idx = int(ctx["chooser"])
        target_idx = int(ctx["target"])
        resume = str(ctx.get("resume", ""))
        optional = bool(ctx.get("optional"))
        self._choice_ctx = {}
        if choice_idx is None:
            if optional:
                self._event_append("declined card choice")
            else:
                self._event_append("no card chosen")
        else:
            options = ctx.get("options") or []
            if 0 <= choice_idx < len(options):
                cid = options[choice_idx]["card_id"]
                self._apply_card_choice_rider(
                    target_idx, cid, str(ctx.get("rider", "")), chooser_idx
                )
        return self._resume_after_choice(ctx)

    def _search_deck(
        self,
        player_idx: int,
        *,
        name_pattern: str = "",
        max_cost: int = 99,
        card_type: str = "",
    ) -> bool:
        actor = self._players[player_idx]
        pattern = name_pattern.lower().strip()
        for i in range(len(actor.deck) - 1, -1, -1):
            cid = actor.deck[i]
            card = self._cards[cid]
            if max_cost >= 0 and card.cost > max_cost:
                continue
            if card_type and card_type not in card.card_types:
                continue
            if pattern:
                hay = f"{card.name} {' '.join(card.card_types)}".lower()
                if pattern not in hay:
                    continue
            actor.deck.pop(i)
            actor.hand.append(cid)
            self._event_append(f"searched deck: found {card.name}")
            return True
        self._event_append("search found no matching card")
        return False

    def _search_deck_to_top(self, player_idx: int, *, card_type: str = "") -> bool:
        actor = self._players[player_idx]
        if actor.deck:
            self._rng.shuffle(actor.deck)
        ctype = card_type.lower().strip()
        for i in range(len(actor.deck) - 1, -1, -1):
            cid = actor.deck[i]
            card = self._cards[cid]
            if ctype and ctype not in card.card_types:
                continue
            cid = actor.deck.pop(i)
            actor.deck.append(cid)
            self._event_append(f"searched deck: put {card.name} on top")
            return True
        self._event_append("search found no matching card for deck top")
        return False

    def _return_from_gy_to_deck(
        self, player_idx: int, name_pattern: str, *, to_bottom: bool = False
    ) -> bool:
        actor = self._players[player_idx]
        pattern = name_pattern.lower().strip()
        pitch_filter: Optional[int] = None
        for color, pitch in (("red", 1), ("yellow", 2), ("blue", 3)):
            if color in pattern:
                pitch_filter = pitch
                break
        for i, cid in enumerate(actor.discard):
            card = self._cards[cid]
            if pitch_filter is not None and card.pitch != pitch_filter:
                continue
            if pattern and pitch_filter is None:
                hay = f"{card.name} {' '.join(card.card_types)}".lower()
                if pattern not in hay and pattern not in card.name.lower():
                    continue
            cid = actor.discard.pop(i)
            if to_bottom:
                actor.deck.insert(0, cid)
                self._event_append(f"put {card.name} from graveyard on bottom of deck")
            else:
                actor.deck.append(cid)
                self._event_append(f"put {card.name} from graveyard on top of deck")
            return True
        self._event_append("no matching card in graveyard")
        return False

    def _return_from_gy_to_deck_top(self, player_idx: int, name_pattern: str) -> bool:
        return self._return_from_gy_to_deck(player_idx, name_pattern, to_bottom=False)

    def _queue_fusion_optional(
        self,
        player_idx: int,
        card: Card,
        perspective_idx: int,
        elements: tuple[str, ...],
    ) -> None:
        if not elements or not self._can_fuse(player_idx, elements):
            return
        self._pending_optionals.append(
            {
                "player": player_idx,
                "card_id": card.id,
                "effect": effects.Effect(
                    "fusion",
                    optional=True,
                    banish_name=",".join(elements),
                    raw=f"fusion: {', '.join(elements)}",
                ),
                "perspective": perspective_idx,
            }
        )

    def _queue_play_costs(
        self,
        player_idx: int,
        card: Card,
        perspective_idx: int,
    ) -> None:
        """Queue optional Heave / Scrap / additional-pay before on-play triggers."""
        for eff in effects.parse_play_costs(card.text):
            if not eff.optional:
                self._apply_effect(
                    player_idx, card, eff, self._pending_combat, perspective_idx
                )
                continue
            if self._optional_available(player_idx, eff):
                self._pending_optionals.append(
                    {
                        "player": player_idx,
                        "card_id": card.id,
                        "effect": eff,
                        "perspective": perspective_idx,
                    }
                )

    def _queue_play_keywords(
        self,
        player_idx: int,
        card: Card,
        perspective_idx: int,
    ) -> None:
        """Queue optional Boost / Reload decisions when a card is played (CR 8.3.9, 8.5.23)."""
        actor = self._players[player_idx]
        keywords = set(card.keywords)
        if "boost" in keywords and actor.deck:
            self._pending_optionals.append(
                {
                    "player": player_idx,
                    "card_id": card.id,
                    "effect": effects.Effect("boost", optional=True, raw="boost"),
                    "perspective": perspective_idx,
                }
            )
        if "reload" in keywords and not actor.arsenal and actor.hand:
            self._pending_optionals.append(
                {
                    "player": player_idx,
                    "card_id": card.id,
                    "effect": effects.Effect("stash_hand", optional=True, raw="reload"),
                    "perspective": perspective_idx,
                }
            )

    def _apply_defender_targeting_penalty(self, combat: CombatState) -> None:
        defender = self._players[combat.defender]
        penalty = defender.class_state.get("AttacksTargetingYouPenalty", 0)
        if penalty:
            combat.opposing_power_mod -= penalty

    def _count_ice_markers(self, player_idx: int) -> int:
        target = self._players[player_idx]
        count = target.tokens.get("frostbite", 0)
        for key, val in target.class_state.items():
            if val and key.startswith("Frozen"):
                count += 1
        return count

    def _apply_damage_floor(self, attacker_idx: int, damage: int) -> int:
        actor = self._players[attacker_idx]
        threshold = actor.class_state.get("DamageFloorThreshold", 0)
        floor_amt = actor.class_state.get("DamageFloorAmount", 0)
        if threshold and floor_amt and 0 < damage < threshold:
            actor.class_state["DamageFloorThreshold"] = 0
            actor.class_state["DamageFloorAmount"] = 0
            self._event_append(f"damage floor: {damage} -> {floor_amt}")
            return floor_amt
        return damage

    def _mark_once_per_turn_used(self, player_idx: int, card: Card) -> None:
        self._players[player_idx].class_state[f"OncePerTurn:{card.id}"] = 1

    def _mitigate_damage(
        self,
        defender_idx: int,
        damage: int,
        *,
        arcane: bool = False,
        source_idx: Optional[int] = None,
    ) -> int:
        """Apply Ward equipment, then prevent layers, before life loss."""
        if damage <= 0:
            return 0
        defender = self._players[defender_idx]
        block_arcane = (
            arcane
            and source_idx is not None
            and defender.class_state.get("BlockArcaneFromSource") == source_idx
        )
        remaining = damage
        while remaining > 0 and self._has_soul_pay_equipment(defender_idx) and defender.soul:
            soul_id = defender.soul.pop()
            defender.banished.append(soul_id)
            self._record_soul_banish_chain(defender_idx)
            remaining -= 1
            self._event_append(
                f"banished {self._cards[soul_id].name} from soul to prevent 1 damage"
            )
        # Ward (CR 8.3.20): destroy equipment/aura with Ward N to prevent N damage.
        for i in range(len(defender.equipment) - 1, -1, -1):
            if remaining <= 0:
                break
            cid = defender.equipment[i]
            card = self._cards[cid]
            has_blue = any(self._cards[cid].pitch == 3 for cid in defender.pitch_zone)
            ward_n = fab_rules.parse_ward_value(card.text, card.keywords, has_blue_pitched=has_blue)
            if ward_n <= 0:
                continue
            absorbed = min(ward_n, remaining)
            remaining -= absorbed
            defender.equipment.pop(i)
            defender.discard.append(cid)
            self._fire_on_leave_triggers(defender_idx, cid)
            self._event_append(f"ward on {card.name} prevented {absorbed} (destroyed)")
        if defender.prevent_damage_charges > 0 and defender.prevent_damage_per_hit > 0 and remaining > 0:
            if block_arcane:
                pass
            else:
                absorbed = min(defender.prevent_damage_per_hit, remaining)
                remaining -= absorbed
                defender.prevent_damage_charges -= 1
                if absorbed:
                    self._event_append(
                        f"prevented {absorbed} damage ({defender.prevent_damage_charges} preventions left)"
                    )
        if defender.prevent_damage > 0 and remaining > 0 and not block_arcane:
            prevent_pool = defender.prevent_damage
            if defender.class_state.get("PreventionReductionTurn", 0):
                prevent_pool = max(0, prevent_pool - 1)
                defender.class_state["PreventionReductionTurn"] = 0
            absorbed = min(prevent_pool, remaining)
            defender.prevent_damage -= absorbed
            remaining -= absorbed
            if absorbed:
                self._event_append(f"prevented {absorbed} damage")
        if arcane and remaining > 0 and defender.arcane_barrier > 0 and not block_arcane:
            while remaining > 0 and defender.arcane_barrier > 0 and defender.resources > 0:
                defender.resources -= 1
                defender.arcane_barrier -= 1
                remaining -= 1
                self._event_append("arcane barrier prevented 1")
        return remaining

    def _has_soul_pay_equipment(self, player_idx: int) -> bool:
        for cid in self._players[player_idx].equipment:
            for trig in effects.parse_triggers(self._cards[cid].text):
                if (
                    trig.effect.kind == "prevent_damage"
                    and (trig.effect.banish_name or "").lower() == "soul_pay"
                ):
                    return True
        return False

    def _discard_random(self, player_idx: int, amount: int = 1) -> int:
        actor = self._players[player_idx]
        discarded = 0
        for _ in range(amount):
            if not actor.hand:
                break
            idx = self._rng.randint(0, len(actor.hand) - 1)
            cid = actor.hand.pop(idx)
            card = self._cards[cid]
            self._event_append(f"P{player_idx} discards {card.name}")
            actor.discard.append(cid)
            if card.power >= 6:
                actor.class_state["DiscardedPower6ThisTurn"] = 1
            self._fire_self_random_discard_triggers(player_idx, card, player_idx)
            self._fire_on_random_discard_triggers(player_idx, card, player_idx)
            discarded += 1
        return discarded

    def _fire_self_random_discard_triggers(
        self, player_idx: int, discarded: Card, perspective_idx: int
    ) -> float:
        reward = 0.0
        actor = self._players[player_idx]
        for trig in effects.parse_triggers(discarded.text):
            if trig.when != "on_discarded_random":
                continue
            if trig.effect.kind == "put_bottom" and discarded.id in actor.discard:
                actor.discard.remove(discarded.id)
                actor.deck.insert(0, discarded.id)
                self._event_append(f"{discarded.name} put on bottom of deck")
            else:
                reward += self._apply_effect(
                    player_idx, discarded, trig.effect, None, perspective_idx
                )
        return reward

    def _destroy_top_of_deck(self, player_idx: int, count: int = 1) -> None:
        actor = self._players[player_idx]
        for _ in range(max(1, count)):
            if not actor.deck and actor.discard:
                actor.deck = actor.discard
                actor.discard = []
                self._rng.shuffle(actor.deck)
            if not actor.deck:
                break
            cid = actor.deck.pop()
            actor.discard.append(cid)
            self._event_append(f"destroyed {self._cards[cid].name} from deck top")

    def _destroy_arsenal(self, player_idx: int, amount: int = 99) -> None:
        actor = self._players[player_idx]
        while actor.arsenal and amount > 0:
            cid = actor.arsenal.pop()
            actor.discard.append(cid)
            self._event_append(f"destroyed arsenal {self._cards[cid].name}")
            amount -= 1

    def _banish_from_graveyard(self, player_idx: int, amount: int = 1) -> None:
        actor = self._players[player_idx]
        for _ in range(amount):
            if not actor.discard:
                break
            cid = actor.discard.pop()
            actor.banished.append(cid)
            self._event_append(f"banished {self._cards[cid].name} from graveyard")

    def _banish_same_name_cards(
        self, target_idx: int, chosen_id: str, limit: int
    ) -> None:
        target = self._players[target_idx]
        needle = self._cards[chosen_id].name.lower().strip()
        if not needle:
            return
        banished = 0

        def _matches(cid: str) -> bool:
            return self._cards[cid].name.lower().strip() == needle

        for cid in list(target.hand):
            if banished >= limit:
                break
            if _matches(cid):
                target.hand.remove(cid)
                target.banished.append(cid)
                banished += 1
        for i in range(len(target.deck) - 1, -1, -1):
            if banished >= limit:
                break
            cid = target.deck[i]
            if _matches(cid):
                target.deck.pop(i)
                target.banished.append(cid)
                banished += 1
        for i in range(len(target.discard) - 1, -1, -1):
            if banished >= limit:
                break
            cid = target.discard[i]
            if _matches(cid):
                target.discard.pop(i)
                target.banished.append(cid)
                banished += 1
        if target.deck:
            self._rng.shuffle(target.deck)
        self._event_append(
            f"banished {banished} card(s) named {self._cards[chosen_id].name} from P{target_idx}"
        )

    def _fire_controlled_hit_triggers(
        self, attacker_idx: int, perspective_idx: int, fused: bool
    ) -> float:
        """Fire 'when an attack you control hits' on arena sources."""
        reward = 0.0
        defender = self._players[1 - attacker_idx]
        actor = self._players[attacker_idx]
        sources: list[Card] = [self._cards[cid] for cid in actor.equipment]
        if actor.weapon_id:
            sources.append(self._cards[actor.weapon_id])
        for card in sources:
            for trig in effects.parse_triggers(card.text):
                if trig.when != "on_controlled_hit":
                    continue
                if trig.effect.condition == "light_hero":
                    defender = self._players[1 - attacker_idx]
                    if (defender.hero.talent or "").strip().lower() != "light":
                        continue
                low = trig.raw.lower()
                if "marked" in low and not defender.marked:
                    continue
                if trig.effect.optional:
                    if self._optional_available(attacker_idx, trig.effect):
                        self._pending_optionals.append(
                            {
                                "player": attacker_idx,
                                "card_id": card.id,
                                "effect": trig.effect,
                                "perspective": perspective_idx,
                            }
                        )
                    continue
                reward += self._apply_effect(
                    attacker_idx, card, trig.effect, self._pending_combat, perspective_idx
                )
        return reward

    def _fire_chain_hit_triggers(self, attacker_idx: int, perspective_idx: int) -> float:
        """Fire 'whenever an attack hits this combat chain' on arena sources."""
        reward = 0.0
        actor = self._players[attacker_idx]
        for cid in actor.equipment:
            card = self._cards[cid]
            for trig in effects.parse_triggers(card.text):
                if trig.when != "on_chain_hit":
                    continue
                if trig.effect.optional:
                    if self._optional_available(attacker_idx, trig.effect):
                        self._pending_optionals.append(
                            {
                                "player": attacker_idx,
                                "card_id": card.id,
                                "effect": trig.effect,
                                "perspective": perspective_idx,
                            }
                        )
                    continue
                reward += self._apply_effect(
                    attacker_idx, card, trig.effect, self._pending_combat, perspective_idx
                )
        return reward

    def _fire_whenever_wager_triggers(self, player_idx: int) -> None:
        actor = self._players[player_idx]
        for cid in actor.equipment:
            card = self._cards[cid]
            for trig in effects.parse_triggers(card.text):
                if trig.when != "whenever_wager":
                    continue
                self._apply_effect(player_idx, card, trig.effect, self._pending_combat, player_idx)

    def _fire_whenever_contract_triggers(self, player_idx: int, perspective_idx: int) -> float:
        return self._fire_when_triggers(
            player_idx, "whenever_contract", perspective_idx, hero=True, equipment=True
        )

    def _fire_when_triggers(
        self,
        player_idx: int,
        when: str,
        perspective_idx: int,
        *,
        hero: bool = True,
        equipment: bool = True,
    ) -> float:
        reward = 0.0
        actor = self._players[player_idx]
        proxy: Optional[Card] = None
        if actor.weapon_id:
            proxy = self._cards[actor.weapon_id]
        elif actor.equipment:
            proxy = self._cards[actor.equipment[0]]
        texts: list[tuple[Optional[Card], str]] = []
        if hero and actor.hero.ability_text:
            texts.append((proxy, actor.hero.ability_text))
        if equipment:
            for cid in actor.equipment:
                card = self._cards[cid]
                texts.append((card, card.text))
        for card, text in texts:
            if not text.strip() or card is None:
                continue
            for trig in effects.parse_triggers(text):
                if trig.when != when:
                    continue
                eff = trig.effect
                if eff.condition and not self._effect_condition_met(
                    player_idx, eff.condition, card, combat=self._pending_combat
                ):
                    continue
                if eff.optional:
                    if self._optional_available(player_idx, eff):
                        self._pending_optionals.append(
                            {
                                "player": player_idx,
                                "card_id": card.id,
                                "effect": eff,
                                "perspective": perspective_idx,
                            }
                        )
                    continue
                reward += self._apply_effect(
                    player_idx, card, eff, self._pending_combat, perspective_idx
                )
        return reward

    def _fire_whenever_play_from_hand_triggers(
        self, player_idx: int, perspective_idx: int
    ) -> float:
        return self._fire_when_triggers(
            player_idx, "whenever_play_from_hand", perspective_idx, hero=True, equipment=False
        )

    def _fire_whenever_gain_gold_triggers(
        self, player_idx: int, perspective_idx: int
    ) -> float:
        if self._active_player != player_idx:
            return 0.0
        return self._fire_when_triggers(
            player_idx, "whenever_gain_gold", perspective_idx, hero=True, equipment=False
        )

    def _fire_whenever_trap_triggers(
        self, player_idx: int, perspective_idx: int
    ) -> float:
        return self._fire_when_triggers(
            player_idx, "whenever_trap_triggers", perspective_idx, hero=True, equipment=True
        )

    def _fire_trap_triggered(
        self,
        defender_idx: int,
        card: Card,
        combat: CombatState,
        perspective_idx: int,
    ) -> float:
        reward = self._run_triggers(
            defender_idx, card, "on_defend", combat, perspective_idx, False
        )
        if "defense_reaction" in card.card_types:
            reward += self._run_triggers(
                defender_idx, card, "on_play", combat, perspective_idx, False
            )
        reward += self._fire_whenever_trap_triggers(defender_idx, perspective_idx)
        return reward

    def _fire_on_random_discard_triggers(
        self, player_idx: int, discarded: Card, perspective_idx: int
    ) -> float:
        reward = 0.0
        actor = self._players[player_idx]
        if discarded.power < 6:
            return 0.0
        for cid in (*actor.equipment, actor.weapon_id or ""):
            if not cid:
                continue
            card = self._cards[cid]
            for trig in effects.parse_triggers(card.text):
                if trig.when != "on_random_discard":
                    continue
                if trig.effect.optional:
                    if self._optional_available(player_idx, trig.effect):
                        self._pending_optionals.append(
                            {
                                "player": player_idx,
                                "card_id": card.id,
                                "effect": trig.effect,
                                "perspective": perspective_idx,
                            }
                        )
                    continue
                reward += self._apply_effect(
                    player_idx, card, trig.effect, self._pending_combat, perspective_idx
                )
        return reward

    def _fire_action_phase_triggers(self, player_idx: int) -> None:
        """Fire start-of-action-phase triggers on arena permanents."""
        actor = self._players[player_idx]
        for cid in actor.equipment:
            self._run_triggers(player_idx, self._cards[cid], "on_action_phase", None, player_idx, False)
        if actor.weapon_id:
            self._run_triggers(player_idx, self._cards[actor.weapon_id], "on_action_phase", None, player_idx, False)

    def _fire_turn_start_triggers(self, player_idx: int) -> None:
        """Fire start-of-turn triggers on arena permanents."""
        actor = self._players[player_idx]
        for cid in actor.equipment:
            self._run_triggers(player_idx, self._cards[cid], "on_turn_start", None, player_idx, False)
        if actor.weapon_id:
            self._run_triggers(player_idx, self._cards[actor.weapon_id], "on_turn_start", None, player_idx, False)

    def _fire_end_phase_triggers(self, player_idx: int) -> None:
        """Fire end-of-turn triggers on arena permanents."""
        actor = self._players[player_idx]
        if actor.class_state.get("EndPhaseDeckTopArsenal"):
            actor.class_state["EndPhaseDeckTopArsenal"] = 0
            self._put_deck_top_in_arsenal(player_idx, face_up=True)
        if actor.class_state.get("DestroyMetacarpusEndPhase", 0):
            for i, cid in enumerate(list(actor.equipment)):
                if "metacarpus" in self._cards[cid].name.lower():
                    actor.equipment.pop(i)
                    actor.discard.append(cid)
                    self._fire_on_leave_triggers(player_idx, cid, player_idx)
                    self._event_append(f"destroyed {self._cards[cid].name} at end phase")
                    break
            actor.class_state["DestroyMetacarpusEndPhase"] = 0
        for cid in actor.equipment:
            self._run_triggers(player_idx, self._cards[cid], "on_end_phase", None, player_idx, False)
        if actor.weapon_id:
            self._run_triggers(player_idx, self._cards[actor.weapon_id], "on_end_phase", None, player_idx, False)

    def _fire_enters_triggers(self, player_idx: int, card: Card) -> None:
        """Fire when-this-enters triggers for a permanent entering the arena."""
        self._run_triggers(player_idx, card, "on_enters", None, player_idx, False)
        self._register_static_may_play_from_text(player_idx, card.text)

    def _apply_hero_passives(self, player_idx: int) -> None:
        """Apply always-on hero ability text (e.g. Dash deck-top item play)."""
        actor = self._players[player_idx]
        text = actor.hero.ability_text
        if not text.strip():
            return
        proxy_id = actor.weapon_id or (actor.equipment[0] if actor.equipment else None)
        if not proxy_id:
            return
        proxy = self._cards[proxy_id]
        grants: list[dict[str, Any]] = []
        for trig in effects.parse_triggers(text):
            if trig.effect.kind == "play_from_deck_top":
                self._apply_effect(player_idx, proxy, trig.effect, None, player_idx)
            elif trig.effect.kind == "grant_may_play":
                grants.append(self._may_play_grant_from_effect(trig.effect))
        body = effects._clean(text)
        for sent in re.split(r"(?<=[.!?])\s+", body):
            eff = effects._parse_grant_may_play(
                " ".join(sent.lower().split()),
                sent.strip(),
                optional=False,
                condition="",
            )
            if eff is None or not eff.implemented:
                continue
            if eff.condition != "static" and "if it's not your turn" not in sent.lower():
                continue
            grants.append(self._may_play_grant_from_effect(eff))
        actor.hero_may_play_grants = grants
        actor.may_play_grants = list(grants)
        if grants:
            self._event_append("hero may-play abilities active")

    def _mark_played_from_arsenal(
        self, player_idx: int, card_id: str, *, from_arsenal: bool = False
    ) -> None:
        if from_arsenal:
            self._players[player_idx].class_state["PlayedFromArsenal"] = 1

    def _deck_top_playable_card(self, player_idx: int) -> Optional[str]:
        actor = self._players[player_idx]
        if not actor.deck_top_play_class or actor.deck_top_play_used:
            return None
        cid = self._deck_top_card_id(player_idx)
        if not cid:
            return None
        card = self._cards[cid]
        if not self._is_arena_permanent(card):
            return None
        if card.cost > 1:
            return None
        if actor.deck_top_play_class not in (card.card_class or "").lower():
            return None
        return cid

    def _can_deck_top_play_now(self, player_idx: int) -> bool:
        cid = self._deck_top_playable_card(player_idx)
        if not cid:
            return False
        actor = self._players[player_idx]
        card = self._cards[cid]
        cost = card.cost + actor.deck_top_play_extra_cost
        if actor.resources < cost:
            return False
        if self._phase == "action" and self._active_player == player_idx:
            return True
        if self._phase in _COMBAT_CHAIN_PHASES:
            return True
        return False

    def _do_play_deck_top(self, player_idx: int, perspective_idx: int = 0) -> float:
        cid = self._deck_top_playable_card(player_idx)
        if not cid or not self._can_deck_top_play_now(player_idx):
            self._last_event = "Cannot play from deck top"
            return -0.05
        actor = self._players[player_idx]
        card = self._cards[cid]
        cost = card.cost + actor.deck_top_play_extra_cost
        actor.resources -= cost
        if actor.deck and actor.deck[-1] == cid:
            actor.deck.pop()
        else:
            actor.deck.remove(cid)
        actor.deck_top_play_used = True
        actor.equipment.append(cid)
        self._fire_enters_triggers(player_idx, card)
        self._last_event = f"P{player_idx} played {card.name} from deck top"
        return 0.0

    def _may_play_grant_from_effect(self, effect: "effects.Effect") -> dict[str, Any]:
        return {
            "zone": effect.target or "hand",
            "filter": (effect.banish_name or "").lower(),
            "pitch": effect.amount or 0,
            "class_filter": (effect.token_name or "").lower(),
            "chain_only": effect.condition == "chain_only",
            "not_own_turn": effect.condition == "not_own_turn",
            "free_cost": effect.condition == "free_cost",
            "static": effect.condition == "static",
        }

    def _append_may_play_grant(self, player_idx: int, effect: "effects.Effect") -> None:
        grant = self._may_play_grant_from_effect(effect)
        self._players[player_idx].may_play_grants.append(grant)
        zone = grant["zone"]
        filt = grant["filter"] or "action"
        self._event_append(f"may play {filt} from {zone} as instant")

    def _register_static_may_play_from_text(self, player_idx: int, text: str) -> None:
        if not text.strip():
            return
        grants: list[dict[str, Any]] = []
        for trig in effects.parse_triggers(text):
            if trig.effect.kind == "grant_may_play" and trig.effect.condition == "static":
                grants.append(self._may_play_grant_from_effect(trig.effect))
        body = effects._clean(text)
        for sent in re.split(r"(?<=[.!?])\s+", body):
            eff = effects._parse_grant_may_play(
                " ".join(sent.lower().split()),
                sent.strip(),
                optional=False,
                condition="",
            )
            if eff is not None and eff.implemented and eff.condition == "static":
                grants.append(
                    self._may_play_grant_from_effect(
                        effects.Effect(
                            eff.kind,
                            eff.amount,
                            eff.raw,
                            target=eff.target,
                            banish_name=eff.banish_name,
                            token_name=eff.token_name,
                            condition="static",
                        )
                    )
                )
        for grant in grants:
            self._players[player_idx].may_play_grants.append(grant)

    def _clear_chain_may_play_grants(self, player_idx: int) -> None:
        actor = self._players[player_idx]
        actor.may_play_grants = [g for g in actor.may_play_grants if not g.get("chain_only")]

    def _is_own_action_phase(self, player_idx: int) -> bool:
        return self._phase == "action" and self._action_phase_player == player_idx

    def _may_play_timing_ok(self, player_idx: int, grant: dict[str, Any]) -> bool:
        if grant.get("chain_only"):
            if self._pending_combat is None:
                return False
            if self._phase not in (*_COMBAT_CHAIN_PHASES, "action"):
                return False
            return True
        if grant.get("not_own_turn"):
            return not self._is_own_action_phase(player_idx)
        if self._phase in _COMBAT_CHAIN_PHASES:
            return True
        if self._phase == "action" and self._active_player == player_idx:
            return True
        return False

    def _card_matches_may_play_grant(self, card: Card, grant: dict[str, Any]) -> bool:
        filt = grant.get("filter") or ""
        if filt == "non-attack" and "attack_action" in card.card_types:
            return False
        if filt == "aura":
            tl = (card.type_line or "").lower()
            if " aura" not in tl and not tl.endswith("aura"):
                return False
        elif filt == "evo":
            if "evo" not in card.name.lower():
                return False
        elif filt == "face_up":
            pass
        elif filt and filt not in ("non-attack", "aura", "evo", "face_up"):
            if filt not in card.name.lower() and filt not in (card.text or "").lower():
                return False
        pitch = grant.get("pitch") or 0
        if pitch and card.pitch != pitch:
            return False
        cls_filter = grant.get("class_filter") or ""
        if cls_filter and cls_filter not in (card.card_class or "").lower():
            return False
        zone = grant.get("zone") or "hand"
        if zone == "hand" and filt == "non-attack":
            if "utility_action" not in card.card_types:
                return False
        return True

    def _may_play_cards_in_zone(self, player_idx: int, zone: str) -> list[str]:
        actor = self._players[player_idx]
        if zone == "hand":
            return list(actor.hand)
        if zone == "arsenal":
            return list(actor.arsenal)
        if zone == "banished":
            return list(actor.banished)
        if zone == "opponent_banished":
            return list(self._players[1 - player_idx].banished)
        if zone == "opponent_arsenal":
            return list(self._players[1 - player_idx].arsenal)
        return []

    def _legal_may_plays(self, actor_idx: int) -> list[str]:
        actor = self._players[actor_idx]
        legal: list[str] = []
        for grant in actor.may_play_grants:
            if not self._may_play_timing_ok(actor_idx, grant):
                continue
            zone = grant.get("zone") or "hand"
            for i, cid in enumerate(self._may_play_cards_in_zone(actor_idx, zone)):
                card = self._cards[cid]
                if not self._card_matches_may_play_grant(card, grant):
                    continue
                if zone == "hand" and self._play_blocked_reason(actor_idx, i, card):
                    continue
                cost = 0 if grant.get("free_cost") else card.cost
                if cost > actor.resources:
                    continue
                legal.append(f"mayplay {zone} {i}")
        return legal

    def _do_may_play(self, player_idx: int, zone: str, idx: int, perspective_idx: int = 0) -> float:
        actor = self._players[player_idx]
        cards = self._may_play_cards_in_zone(player_idx, zone)
        if idx < 0 or idx >= len(cards):
            self._last_event = "No such card to play"
            return -0.05
        cid = cards[idx]
        card = self._cards[cid]
        grant = next(
            (
                g
                for g in actor.may_play_grants
                if self._may_play_timing_ok(player_idx, g)
                and self._card_matches_may_play_grant(card, g)
                and (g.get("zone") or "hand") == zone
            ),
            None,
        )
        free_cost = False
        if grant is None and zone == "hand" and actor.play_as_instant:
            if self._card_matches_may_play_grant(
                card,
                {
                    "zone": "hand",
                    "filter": "non-attack",
                    "class_filter": actor.instant_class_filter,
                },
            ):
                grant = {"zone": "hand", "filter": "non-attack", "free_cost": False}
        if grant is None:
            self._last_event = "No may-play grant applies"
            return -0.05
        free_cost = bool(grant.get("free_cost"))
        cost = 0 if free_cost else self._effective_card_cost(player_idx, card)
        if actor.resources < cost:
            self._last_event = f"Need {cost} resources"
            return -0.05
        if zone == "hand":
            hand_idx = actor.hand.index(cid)
            if self._play_blocked_reason(player_idx, hand_idx, card):
                self._last_event = "That card cannot be played now"
                return -0.05
        actor.resources -= cost
        if not free_cost:
            self._consume_cost_reduction(player_idx, card, cost)
        if zone == "hand":
            actor.hand.pop(actor.hand.index(cid))
        elif zone == "arsenal":
            actor.arsenal.remove(cid)
            self._players[player_idx].class_state["PlayedFromArsenal"] = 1
        elif zone == "banished":
            actor.banished.remove(cid)
            actor.playable_banished.discard(cid)
        elif zone == "opponent_banished":
            opp = self._players[1 - player_idx]
            opp.banished.remove(cid)
        elif zone == "opponent_arsenal":
            opp = self._players[1 - player_idx]
            opp.arsenal.remove(cid)
            actor.class_state["PlayedFromArsenal"] = 0
        actor.play_as_instant = False
        is_attack = "attack_action" in card.card_types
        is_utility = "utility_action" in card.card_types
        keywords = set(card.keywords)
        go_again = self._go_again_for_play(player_idx, card, is_utility)
        dominate = "dominate" in keywords
        damage, arcane = _parse_action_damage(card.text, card.power, is_attack)
        self._last_event = f"P{player_idx} may-play {card.name} from {zone}"
        if is_attack and not arcane:
            combat = CombatState(
                attacker=player_idx,
                defender=1 - player_idx,
                attack_card_id=card.id,
                attack_power=damage,
                blocks=[],
                go_again=go_again,
                dominate=dominate,
                fused=False,
            )
            self._pending_combat = combat
            go_again, dominate = self._apply_play_modifiers(
                player_idx, card, combat, go_again=go_again, dominate=dominate
            )
            combat.go_again = go_again
            combat.dominate = dominate
            self._record_play_counters(player_idx, card, True, False, False, None)
            self._consume_pending_next_attack_power(player_idx, card, combat)
            return self._finish_attack_triggers(player_idx, card, perspective_idx, False)
        return self._resolve_direct(
            player_idx, card, damage, arcane, go_again, dominate, False, (), perspective_idx
        )

    def _fire_damage_triggers(
        self,
        attacker_idx: int,
        card: Card,
        damage: int,
        perspective_idx: int,
        fused: bool,
    ) -> float:
        """Fire on_crush / on_surge triggers after combat damage is dealt."""
        reward = 0.0
        for trig in effects.parse_triggers(card.text):
            if trig.when == "on_crush" and damage >= max(1, trig.threshold):
                if not self._crush_condition_met(attacker_idx, trig.effect):
                    continue
                reward += self._apply_effect(attacker_idx, card, trig.effect, None, perspective_idx)
            elif trig.when == "on_surge" and damage > trig.threshold:
                reward += self._apply_effect(attacker_idx, card, trig.effect, None, perspective_idx)
        return reward

    def _record_play_counters(
        self,
        player_idx: int,
        card: Card,
        is_attack: bool,
        is_utility: bool,
        fused: bool,
        element: Optional[str],
        *,
        from_hand: bool = True,
    ) -> None:
        cs = self._players[player_idx].class_state
        if "runeblade" in (card.card_class or "").lower() and cs.get("NumNonAttackCards", 0) > 0:
            self._fire_equipment_triggers(player_idx, "whenever_runeblade_play", player_idx)
        cs["NumCardsPlayed"] += 1
        if is_attack:
            cs["NumActionsPlayed"] += 1
            cs["NumAttacks"] += 1
        elif is_utility:
            cs["NumActionsPlayed"] += 1
            cs["NumNonAttackCards"] += 1
        if is_attack or is_utility:
            cs["LastActionTalentLightning"] = 1 if self._is_lightning_action(card) else 0
        if "lightning" in (card.name + " " + card.text).lower():
            cs["NumLightningPlayed"] += 1
        color = {1: "NumRedPlayed", 2: "NumYellowPlayed", 3: "NumBluePlayed"}.get(card.pitch)
        if color:
            cs[color] += 1
        if fused and element:
            fkey = {"lightning": "NumFusedLightning", "ice": "NumFusedIce", "earth": "NumFusedEarth"}.get(element)
            if fkey:
                cs[fkey] += 1
            if element == "ice":
                self._fire_equipment_triggers(player_idx, "on_ice_fuse", player_idx)
        if "contract" in card.keywords or re.search(r"\bcontract\b", card.text, re.I):
            self._fire_whenever_contract_triggers(player_idx, player_idx)
        if from_hand:
            self._fire_whenever_play_from_hand_triggers(player_idx, player_idx)
        if "blood_debt" in card.keywords:
            cs["BloodDebtPlayedThisTurn"] = cs.get("BloodDebtPlayedThisTurn", 0) + 1
        if "wax on" in card.name.lower():
            cs["WaxOnPlayedThisTurn"] = 1

    def _deck_top_card_id(self, player_idx: int) -> Optional[str]:
        """Return the top card id of a player's deck, reshuffling discard if needed."""
        p = self._players[player_idx]
        if not p.deck and p.discard:
            p.deck = p.discard
            p.discard = []
            self._rng.shuffle(p.deck)
        if not p.deck:
            return None
        return p.deck[-1]

    def _banish_top_card(self, player_idx: int) -> Optional[str]:
        """Banish the top card of a player's deck into their banished zone."""
        p = self._players[player_idx]
        if not p.deck and p.discard:
            p.deck = p.discard
            p.discard = []
            self._rng.shuffle(p.deck)
        if not p.deck:
            return None
        cid = p.deck.pop()
        p.banished.append(cid)
        self._players[player_idx].class_state["CardsBanishedThisTurn"] += 1
        self._event_append(f"P{player_idx} banished {self._cards[cid].name} from deck top")
        return cid

    def _banish_defending_card(self, combat: Optional[CombatState], defender_idx: int) -> None:
        """Banish one defending card from the current combat chain."""
        if combat is None:
            return
        for i in range(len(combat.blocks) - 1, -1, -1):
            block_player, cid, _ = combat.blocks[i]
            if block_player != defender_idx:
                continue
            combat.blocks.pop(i)
            self._players[defender_idx].banished.append(cid)
            self._event_append(f"banished defending {self._cards[cid].name}")
            return

    def _create_token(self, player_idx: int, token_name: str, amount: int = 1) -> None:
        key = token_defs.normalize_token_name(token_name)
        actor = self._players[player_idx]
        actor.tokens[key] = actor.tokens.get(key, 0) + amount
        actor.tokens_controlled_turn.add(key)
        if "aura" in token_name.lower() or key in (
            "runechant",
            "might",
            "vigor",
            "agility",
            "fealty",
            "confidence",
            "toughness",
        ):
            actor.class_state["AurasPlayedOrCreatedThisTurn"] = (
                actor.class_state.get("AurasPlayedOrCreatedThisTurn", 0) + amount
            )
        label = token_name.strip() or key
        suffix = f"x{amount} " if amount > 1 else ""
        self._event_append(f"created {suffix}{label} token")

    def _create_in_banished(
        self,
        player_idx: int,
        card_name: str,
        *,
        playable: bool = False,
        power_bonus: int = 0,
    ) -> None:
        cid = token_defs.resolve_banished_card_id(card_name, self._token_name_index)
        if cid is None:
            self._note(f"Unknown banished card to create: {card_name!r}")
            return
        actor = self._players[player_idx]
        actor.banished.append(cid)
        if playable:
            actor.playable_banished.add(cid)
        self._event_append(
            f"created {self._cards[cid].name} in banished zone"
            + (" (playable this turn)" if playable else "")
        )

    def _create_in_hand(self, player_idx: int, card_name: str, amount: int = 1) -> None:
        names = [card_name.strip()]
        if re.search(r"\s+and\s+", card_name, re.I):
            names = [n.strip() for n in re.split(r"\s+and\s+", card_name, flags=re.I)]
        actor = self._players[player_idx]
        for _ in range(max(1, amount)):
            for name in names:
                cid = token_defs.resolve_banished_card_id(name, self._token_name_index)
                if cid is None:
                    self._note(f"Unknown card to create in hand: {name!r}")
                    continue
                actor.hand.append(cid)
                self._event_append(f"created {self._cards[cid].name} in hand")

    def _apply_named_power_bonuses(
        self, player_idx: int, card: Card, combat: Optional[CombatState]
    ) -> None:
        if combat is None:
            return
        cs = self._players[player_idx].class_state
        card_low = card.name.lower()
        for key, bonus in list(cs.items()):
            if not str(key).startswith("NamedPower:") or not bonus:
                continue
            pattern = str(key).split(":", 1)[1]
            if pattern == "this_chain":
                self._apply_combat_power_bonus(
                    combat,
                    player_idx,
                    int(bonus),
                    reason=f"+{bonus} power (named card this chain)",
                )
                continue
            if pattern in card_low:
                self._apply_combat_power_bonus(
                    combat,
                    player_idx,
                    int(bonus),
                    reason=f"+{bonus} power ({pattern})",
                )

    def _process_token_upkeep(self, player_idx: int) -> None:
        """Resolve start-of-action-phase token upkeeps (e.g. Seismic Surge)."""
        actor = self._players[player_idx]
        key = "seismic surge"
        if actor.tokens.get(key, 0) <= 0:
            return
        actor.tokens[key] -= 1
        actor.class_state["NextGuardianAttackCostReduction"] = 1
        self._event_append("Seismic Surge: next Guardian attack costs 1 less")

    def _effective_card_cost(self, player_idx: int, card: Card) -> int:
        cost = card.cost
        actor = self._players[player_idx]
        if "attack_action" in card.card_types and (card.card_class or "").strip().lower() == "guardian":
            reduction = actor.class_state.get("NextGuardianAttackCostReduction", 0)
            cost = max(0, cost - reduction)
        play_reduction = actor.class_state.get("NextPlayCostReduction", 0)
        cost = max(0, cost - play_reduction)
        cost = max(0, cost - self._token_play_cost_reduction(player_idx, card))
        cost += actor.extra_play_cost
        if "attack_action" in card.card_types:
            cost += self._first_attack_extra_cost(player_idx, is_attack=True)
        if "defense_reaction" in card.card_types:
            cost += actor.extra_defense_reaction_cost
        return cost

    def _consume_cost_reduction(self, player_idx: int, card: Card, paid_cost: int) -> None:
        actor = self._players[player_idx]
        if (
            "attack_action" in card.card_types
            and (card.card_class or "").strip().lower() == "guardian"
            and paid_cost < card.cost
            and actor.class_state.get("NextGuardianAttackCostReduction", 0) > 0
        ):
            actor.class_state["NextGuardianAttackCostReduction"] = 0
        if actor.class_state.get("NextPlayCostReduction", 0) > 0 and paid_cost < card.cost:
            actor.class_state["NextPlayCostReduction"] = 0

    def _pitch_cards(self, player_idx: int, count: int) -> int:
        """Pitch up to *count* cards from hand; return number actually pitched."""
        actor = self._players[player_idx]
        pitched = 0
        for _ in range(max(0, count)):
            idx = next(
                (
                    i
                    for i, cid in enumerate(actor.hand)
                    if self._cards[cid].pitch > 0 and cid not in actor.arsenal
                ),
                None,
            )
            if idx is None:
                break
            cid = actor.hand.pop(idx)
            card = self._cards[cid]
            actor.pitch_zone.append(cid)
            pitched += 1
            self._record_opponent_pitch(player_idx, card)
            self._event_append(f"pitched {card.name} to pay cost")
        return pitched

    def _gy_play_pattern_match(self, card: Card, pattern: str) -> bool:
        p = (pattern or "").strip().lower()
        if not p or p == "this":
            return True
        if p in card.name.lower():
            return True
        if p in (card.text or "").lower():
            return True
        if p in (card.type_line or "").lower():
            return True
        return False

    def _enable_graveyard_play(
        self, player_idx: int, source: Card, pattern: str
    ) -> None:
        actor = self._players[player_idx]
        pat = (pattern or "").strip().lower()
        if pat in ("", "this"):
            actor.playable_graveyard.add(source.id)
            self._event_append(f"{source.name} may be played from graveyard this turn")
            return
        enabled = 0
        for cid in actor.discard:
            if self._gy_play_pattern_match(self._cards[cid], pat):
                actor.playable_graveyard.add(cid)
                enabled += 1
        if enabled:
            self._event_append(f"{enabled} graveyard card(s) may be played this turn")
        else:
            self._event_append(f"no matching cards in graveyard for {pat!r}")

    def _can_play_from_graveyard(self, player_idx: int, card_id: str) -> bool:
        if card_id in self._players[player_idx].playable_graveyard:
            return True
        text = self._cards[card_id].text.lower()
        return "you may play this from your graveyard" in text

    def _can_play_from_banished(self, player_idx: int, card_id: str) -> bool:
        actor = self._players[player_idx]
        if card_id in actor.playable_banished:
            return True
        card = self._cards[card_id]
        text = card.text.lower()
        if "you may play this from your banished zone" in text:
            return True
        for src in [actor.hero.ability_text] + [self._cards[c].text for c in actor.equipment]:
            low = (src or "").lower()
            if "you may play evos from your banished zone" in low and "evo" in card.name.lower():
                return True
        return False

    def _effect_condition_met(
        self,
        player_idx: int,
        condition: str,
        card: Optional[Card] = None,
        *,
        condition_arg: str = "",
        combat: Optional[CombatState] = None,
    ) -> bool:
        """Evaluate a parsed play-time condition from card rules text."""
        if not condition:
            return True
        actor = self._players[player_idx]
        opponent = self._players[1 - player_idx]
        cs = actor.class_state
        if condition == "life_less":
            return actor.life < opponent.life
        if condition == "empty_deck":
            return len(actor.deck) == 0
        if condition == "played_red_other":
            red = cs.get("NumRedPlayed", 0)
            if card is not None and card.pitch == 1:
                return red >= 1
            return red > 0
        if condition == "played_blue_other":
            blue = cs.get("NumBluePlayed", 0)
            if card is not None and card.pitch == 3:
                return blue >= 1
            return blue > 0
        if condition == "pitched_power_6":
            return any(self._cards[cid].power >= 6 for cid in actor.pitch_zone)
        if condition == "last_action_lightning":
            return cs.get("LastActionTalentLightning", 0) > 0
        if condition == "controlled_seismic_surge":
            return "seismic surge" in actor.tokens_controlled_turn
        if condition == "combo_red":
            return cs.get("LastChainAttackPitch", 0) == 1
        if condition == "combo_yellow":
            return cs.get("LastChainAttackPitch", 0) == 2
        if condition == "combo_blue":
            return cs.get("LastChainAttackPitch", 0) == 3
        if condition == "combo_draconic":
            return cs.get("ComboLastAttackDraconic", 0) > 0
        if condition.startswith("combo_named:"):
            want = condition.split(":", 1)[1].strip().lower()
            last = str(cs.get("LastChainAttackName", "")).lower()
            return want in last or last.endswith(want)
        if condition.startswith("auras_ge:"):
            return cs.get("AurasPlayedOrCreatedThisTurn", 0) >= int(condition.split(":", 1)[1])
        if condition.startswith("controls_ge:"):
            parts = condition.split(":")
            token = parts[1] if len(parts) > 1 else "aura"
            need = int(parts[2]) if len(parts) > 2 else 1
            return actor.tokens.get(token_defs.normalize_token_name(token), 0) >= need
        if condition == "cheered_this_turn":
            return actor.cheered_this_turn
        if condition.startswith("hand_ge:"):
            return len(actor.hand) >= int(condition.split(":", 1)[1])
        if condition == "no_hit_this_turn":
            return cs.get("HitCounter", 0) <= 0
        if condition == "no_gold_tokens":
            return actor.gold <= 0 and actor.tokens.get("gold", 0) <= 0
        if condition == "wax_on_played":
            return cs.get("WaxOnPlayedThisTurn", 0) > 0
        if condition == "naa_played_this_turn":
            return cs.get("NumNonAttackCards", 0) > 0
        if condition == "empty_arsenal":
            return not actor.arsenal
        if condition == "pitch_ge:6":
            return card is not None and card.pitch >= 6
        if condition.startswith("weapon_attacks_ge:"):
            return cs.get("WeaponAttacksThisTurn", 0) >= int(condition.split(":", 1)[1])
        if condition == "once_per_turn":
            return not cs.get(f"OncePerTurn:{card.id if card else 'hero'}", 0)
        if condition == "less_gold_than_opponent":
            return actor.gold < opponent.gold
        if condition == "more_gold_than_opponent":
            return actor.gold > opponent.gold
        if condition == "scrapped_this_play":
            return actor.class_state.get("ScrappedThisPlay", 0) > 0
        if condition == "additional_cost_paid":
            return actor.class_state.get(f"AdditionalCostPaid:{card.id if card else ''}", 0) > 0
        if condition == "power_ge_6":
            return card is not None and card.power >= 6
        if condition == "power_ge_10":
            return card is not None and card.power >= 10
        if condition.startswith("attacks_lt:"):
            return cs.get("WeaponAttacksThisTurn", 0) < int(condition.split(":", 1)[1])
        if condition == "chain_link_ge":
            threshold = int(condition_arg or "1")
            return self._combat_chain_links + 1 >= threshold
        if condition == "blue_pitched_each":
            return any(self._cards[cid].pitch == 3 for cid in actor.pitch_zone)
        if condition == "has_token":
            key = token_defs.normalize_token_name(condition_arg or "")
            return actor.tokens.get(key, 0) > 0
        if condition == "yellow_in_pitch":
            return any(self._cards[cid].pitch == 2 for cid in actor.pitch_zone)
        if condition == "banished_this_turn":
            return cs.get("CardsBanishedThisTurn", 0) > 0
        if condition == "charged_yellow":
            return cs.get("ChargedYellowThisPlay", 0) > 0
        if condition == "attack_reaction_chain":
            combat = self._pending_combat
            return combat is not None and combat.attack_reactions_played > 0
        if condition == "defending_chain_link_ge":
            threshold = int(condition_arg or "1")
            return self._combat_chain_links + 1 >= threshold
        if condition == "played_from_arsenal":
            return cs.get("PlayedFromArsenal", 0) > 0
        if condition == "rolled_6_this_turn":
            return cs.get("Rolled6ThisTurn", 0) > 0
        if condition.startswith("hyper_drivers_ge:"):
            return cs.get("LastHyperDriversTurned", 0) >= int(condition.split(":", 1)[1])
        if condition == "revealed_attack_reaction":
            for cid in opponent.revealed_hand or opponent.hand:
                if "attack_reaction" in self._cards[cid].card_types:
                    return True
            return False
        if condition == "royal_hero":
            if combat is None:
                return False
            defender = self._players[combat.defender]
            return "royal" in defender.hero.name.lower()
        if condition == "no_soul":
            return not actor.soul
        if condition == "light_hero":
            if combat is None:
                return False
            defender = self._players[combat.defender]
            return (defender.hero.talent or "").strip().lower() == "light"
        if condition == "has_aim_counter":
            return (
                card is not None
                and self._permanent_counters(player_idx, card.id).get("aim", 0) > 0
            )
        if condition == "stealth_hit_marked":
            defender = self._players[1 - player_idx]
            return cs.get("StealthHitThisTurn", 0) > 0 and defender.marked
        if condition == "attacking_marked":
            if combat is None:
                return False
            defender = self._players[combat.defender]
            return defender.marked
        if condition == "has_guardian_offhand":
            actor = self._players[player_idx]
            for cid in actor.equipment:
                eq = self._cards[cid]
                line = (eq.type_line or "").lower()
                cls = (eq.card_class or "").lower()
                if "off-hand" in line and "guardian" in cls:
                    return True
            return False
        if condition == "defends_alone":
            if combat is None:
                return False
            return len(combat.blocks) == 1
        if condition == "attack_power_gt_base":
            if combat is None or not combat.attack_card_id:
                return False
            attack_card = self._cards.get(combat.attack_card_id)
            if attack_card is None:
                return False
            return combat.attack_power > attack_card.power
        if condition.startswith("defends_class:"):
            if combat is None or not combat.attack_card_id:
                return False
            want = condition.split(":", 1)[1].lower()
            attack_card = self._cards.get(combat.attack_card_id)
            if attack_card is None:
                return False
            atk_class = (attack_card.card_class or "").lower()
            atk_talent = (attack_card.talent or "").lower()
            return want in (atk_class, atk_talent)
        if condition.startswith("defends_card_pitch:"):
            if combat is None or not combat.attack_card_id:
                return False
            want_pitch = int(condition.split(":", 1)[1])
            attack_card = self._cards.get(combat.attack_card_id)
            return attack_card is not None and attack_card.pitch == want_pitch
        if condition == "reaction_played_chain":
            if combat is None:
                return False
            return bool(combat.reaction_cards) or combat.attack_reactions_played > 0
        if condition == "attack_reaction_played_chain":
            if combat is None:
                return False
            return combat.attack_reactions_played > 0
        if condition.startswith("attack_reactions_ge:"):
            if combat is None:
                return False
            threshold = int(condition.split(":", 1)[1])
            return combat.attack_reactions_played >= threshold
        if condition == "charged_this_turn":
            return cs.get("ChargedThisTurn", 0) > 0
        if condition == "transcended_this_turn":
            return cs.get("TranscendedThisTurn", 0) > 0
        if condition == "chi_pitched":
            return cs.get("ChiPitchedThisPlay", 0) > 0
        if condition.startswith("suspense_left_ge:"):
            return cs.get("SuspenseAurasLeftThisTurn", 0) >= int(condition.split(":", 1)[1])
        if condition == "defending_attack_power_le:2":
            if combat is None:
                return False
            return combat.attack_power <= 2
        if condition.startswith("pitched_attack_and_nonattack"):
            return cs.get("PitchedAttackAndNonattack", 0) > 0
        if condition == "other_hero:life_less":
            return actor.life > self._players[1 - player_idx].life
        if condition == "dealt_hero_damage":
            return actor.class_state.get("LastArcaneHeroDamage", 0) > 0 or (
                combat is None and actor.class_state.get("ArcaneDamageDealt", 0) > 0
            )
        if condition == "soul_this_turn":
            return actor.class_state.get("SoulCardThisTurn", 0) > 0
        if condition == "earth_pitched_weapon":
            return any(
                (self._cards[cid].talent or "").lower() == "earth"
                for cid in actor.pitch_zone
            )
        if condition == "hero_thief":
            hero = (actor.hero.hero_class or actor.hero.name or "").lower()
            return "thief" in hero
        if condition == "arsenal_crush":
            return bool(actor.arsenal) and any(
                "crush" in self._cards[cid].keywords
                or "crush" in (self._cards[cid].text or "").lower()
                for cid in actor.arsenal
            )
        if condition == "arcane_dealt_turn":
            return actor.class_state.get("ArcaneDamageDealt", 0) > 0
        if condition == "defends_weapon_attack":
            return combat is not None and combat.is_weapon
        if condition == "guardian_offhand_defending":
            if combat is None:
                return False
            defender = self._players[1 - combat.attacker]
            for cid in defender.equipment:
                eq = self._cards[cid]
                line = (eq.type_line or "").lower()
                cls = (eq.card_class or "").lower()
                if "off-hand" in line and "guardian" in cls and eq.defense >= 1:
                    return True
            return False
        if condition.startswith("defended_by_ge"):
            if combat is None:
                return False
            want = int(condition.split(":", 1)[1]) if ":" in condition else 1
            return len(combat.blocks) >= want
        if condition == "defended_by_ge_pay":
            if combat is None:
                return False
            need = int((condition_arg or "1"))
            return len(combat.blocks) >= need
        if condition == "hero_thief:pay_gold":
            if not self._effect_condition_met(player_idx, "hero_thief", card, combat=combat):
                return False
            return actor.gold >= 1
        if condition == "gy_yellow":
            return any(self._cards[cid].pitch == 2 for cid in actor.discard) or any(
                self._cards[cid].pitch == 2 for cid in self._players[1 - player_idx].discard
            )
        if condition == "discarded_power6_turn":
            return cs.get("DiscardedPower6ThisTurn", 0) > 0
        if condition.startswith("earth_banish_ge:"):
            threshold = int(condition.split(":", 1)[1])
            return self._count_earth_in_banish(player_idx) >= threshold
        if condition.startswith("steam_removed_ge:"):
            threshold = int(condition.split(":", 1)[1])
            return cs.get("LastSteamRemovedCount", 0) >= threshold
        if condition.startswith("control_token:"):
            token = condition.split(":", 1)[1].strip()
            return actor.tokens.get(token_defs.normalize_token_name(token), 0) > 0
        if condition.startswith("control_tokens:"):
            tokens = condition.split(":", 1)[1].split(",")
            return all(
                actor.tokens.get(token_defs.normalize_token_name(t.strip()), 0) > 0
                for t in tokens
            )
        if condition.startswith("defender_controls_token:"):
            pending = self._pending_combat
            if pending is None:
                return False
            token = condition.split(":", 1)[1].strip()
            defender = self._players[pending.defender]
            return defender.tokens.get(token_defs.normalize_token_name(token), 0) > 0
        return False

    def _apply_play_modifiers(
        self,
        player_idx: int,
        card: Card,
        combat: Optional[CombatState],
        *,
        go_again: bool,
        dominate: bool,
    ) -> tuple[bool, bool]:
        """Apply inline play bonuses; return updated (go_again, dominate)."""
        actor = self._players[player_idx]
        for mod in effects.parse_play_modifiers(card.text):
            if mod.condition and not self._effect_condition_met(
                player_idx,
                mod.condition,
                card,
                condition_arg=mod.condition_arg,
            ):
                continue
            if mod.condition == "defended_by_action_penalty":
                continue
            if mod.condition == "arcane_dealt_turn":
                if actor.class_state.get("ArcaneDamageDealt", 0) <= 0:
                    continue
            if mod.condition == "defended_by_ge_pay":
                continue
            if mod.power and combat is not None:
                self._apply_combat_power_bonus(
                    combat,
                    player_idx,
                    mod.power,
                    reason=f"+{mod.power} power ({mod.raw[:40]})",
                )
            if mod.defense:
                actor = self._players[player_idx]
                bonus = mod.defense
                if mod.condition == "blue_pitched_each":
                    n_blue = sum(1 for cid in actor.pitch_zone if self._cards[cid].pitch == 3)
                    bonus *= max(0, n_blue)
                if bonus > 0:
                    actor.class_state["NextDefenseBonus"] = (
                        actor.class_state.get("NextDefenseBonus", 0) + bonus
                    )
                    self._event_append(f"+{bonus} defense ({mod.raw[:40]})")
            if mod.go_again:
                go_again = True
            if mod.next_action_go_again:
                actor = self._players[player_idx]
                actor.class_state["NextActionGoAgain"] = (
                    actor.class_state.get("NextActionGoAgain", 0) + mod.next_action_go_again
                )
                self._event_append(
                    f"next {mod.next_action_go_again} action(s) gain go again"
                )
            if mod.dominate:
                dominate = True
            if mod.next_attack_power:
                actor = self._players[player_idx]
                actor.class_state["NextAttackPower"] = mod.next_attack_power
                actor.class_state["NextAttackPowerMaxCost"] = mod.next_attack_max_cost
                if mod.condition == "weapon_only":
                    actor.class_state["NextAttackWeaponOnly"] = 1
                    actor.class_state["NextAttackMinBase"] = 0
                elif mod.condition == "min_base_power":
                    actor.class_state["NextAttackMinBase"] = int(mod.condition_arg or "0")
                    actor.class_state["NextAttackWeaponOnly"] = 0
                else:
                    actor.class_state["NextAttackMinBase"] = 0
                    actor.class_state["NextAttackWeaponOnly"] = 0
                self._event_append(f"next attack +{mod.next_attack_power} power")
        return go_again, dominate

    def _card_matches_banish_combo(self, card: Card, target: str) -> bool:
        """Match graveyard banish_combo targets by name, card type, or type line."""
        needle = (target or "").strip().lower()
        if not needle:
            return False
        if needle in card.name.lower():
            return True
        tl = (card.type_line or "").lower()
        if f" {needle}" in tl or tl.endswith(needle) or tl.startswith(needle):
            return True
        for ct in card.card_types:
            if needle in ct.lower():
                return True
        return False

    def _item_attack_power(self, player_idx: int, card_id: str) -> int:
        card = self._cards[card_id]
        bonus = self._permanent_counters(player_idx, card_id).get("power", 0)
        return max(0, card.power + bonus)

    def _apply_banish_combo_rider(
        self,
        player_idx: int,
        card: Card,
        effect: "effects.Effect",
        combat: Optional[CombatState],
        *,
        banished_name: str,
    ) -> None:
        raw = (effect.raw or "").lower()
        if effect.amount and combat is not None:
            self._apply_combat_power_bonus(
                combat,
                player_idx,
                effect.amount,
                reason=f"banished {banished_name} (+{effect.amount} power)",
            )
            if effect.go_again:
                self._grant_go_again(player_idx, combat, this_card=True)
            return
        m = re.search(r"deal (\d+) arcane damage", raw)
        if m:
            arcane = effects.Effect(
                "arcane_damage",
                int(m.group(1)),
                raw=effect.raw or "",
                target=effect.target,
            )
            self._apply_effect(player_idx, card, arcane, combat, 0)
            return

    def _decode_hit_rider(self, encoded: str) -> effects.Effect:
        parts = (encoded or "").split(":", 2)
        kind = parts[0] if parts else "unimplemented"
        banish = parts[1] if len(parts) > 1 else ""
        return effects.Effect(kind, banish_name=banish)

    def _apply_pending_hit_rider(
        self,
        player_idx: int,
        card: Card,
        combat: Optional[CombatState],
        perspective_idx: int,
    ) -> float:
        rider = self._players[player_idx].class_state.pop("PendingHitRider", "")
        if not rider:
            return 0.0
        return self._apply_effect(
            player_idx,
            card,
            self._decode_hit_rider(rider),
            combat,
            perspective_idx,
        )

    def _apply_effect(
        self,
        player_idx: int,
        card: Card,
        effect: "effects.Effect",
        combat: Optional[CombatState],
        perspective_idx: int,
    ) -> float:
        """Apply one parsed effect; return signed reward from any damage dealt."""
        if not effect.implemented:
            self._note(f"{card.name}: interaction not implemented yet (\"{effect.raw[:60]}\")")
            return 0.0
        if effect.condition and not self._effect_condition_met(
            player_idx, effect.condition, card, combat=combat
        ):
            return 0.0

        actor = self._players[player_idx]
        defender = self._players[1 - player_idx]

        if effect.kind == "go_again":
            n = max(1, effect.amount or 1)
            if combat is not None and n == 1:
                self._grant_go_again(player_idx, combat, this_card=True)
            elif combat is not None:
                combat.go_again = True
                if n > 1:
                    actor.action_points += n - 1
            else:
                actor.action_points += n
            return 0.0
        if effect.kind == "next_naa_go_again":
            actor.class_state["NextNAACardGoAgain"] = 1
            return 0.0
        if effect.kind == "next_action_go_again":
            self._grant_go_again(player_idx, combat, this_card=False, next_actions=max(1, effect.amount or 1))
            return 0.0
        if effect.kind == "next_attack_power":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            cs = self._players[target_idx].class_state
            cs["NextAttackPower"] = effect.amount
            cs["NextAttackPowerMaxCost"] = effect.max_cost
            if effect.condition == "min_base_power":
                cs["NextAttackMinBase"] = int(effect.banish_name or "0")
                cs["NextAttackWeaponOnly"] = 0
                cs["NextAttackWeaponClass"] = ""
            elif effect.condition == "weapon_class":
                cs["NextAttackMinBase"] = 0
                cs["NextAttackWeaponOnly"] = 0
                cs["NextAttackWeaponClass"] = (effect.banish_name or "").lower()
            elif effect.condition == "weapon_only" or (effect.banish_name or "").lower() == "wrench":
                cs["NextAttackMinBase"] = 0
                cs["NextAttackWeaponOnly"] = 1
                cs["NextAttackWeaponClass"] = ""
            else:
                cs["NextAttackMinBase"] = 0
                cs["NextAttackWeaponOnly"] = 0
                cs["NextAttackWeaponClass"] = ""
            if (effect.token_name or "").startswith("hit:"):
                cs["NextAttackHitRider"] = effect.token_name[4:]
            self._event_append(f"next attack {effect.amount:+d} power on P{target_idx}")
            return 0.0
        if effect.kind == "banish_combo":
            target = (effect.banish_name or "").lower()
            actor = self._players[player_idx]
            for j, cid in enumerate(actor.discard):
                gy_card = self._cards[cid]
                if not self._card_matches_banish_combo(gy_card, target):
                    continue
                banished = gy_card.name
                actor.discard.pop(j)
                actor.banished.append(cid)
                self._event_append(f"banished {banished} from graveyard")
                self._apply_banish_combo_rider(
                    player_idx,
                    card,
                    effect,
                    combat,
                    banished_name=banished,
                )
                break
            return 0.0
        if effect.kind == "power":
            if (effect.banish_name or "").lower() == "gold_count":
                bonus = actor.gold + actor.tokens.get("gold", 0)
                if combat is not None and bonus > 0:
                    self._apply_combat_power_bonus(
                        combat,
                        player_idx,
                        bonus,
                        reason=f"+{bonus} power (Gold controlled)",
                    )
                return 0.0
            if (effect.banish_name or "").lower() == "hyper_drivers_destroyed":
                count = actor.class_state.get("LastHyperDriversDestroyed", 0)
                per = max(1, effect.amount or 1)
                bonus = count * per
                if combat is not None and bonus > 0:
                    self._apply_combat_power_bonus(
                        combat,
                        player_idx,
                        bonus,
                        reason=f"+{bonus} power ({count} Hyper Drivers destroyed)",
                    )
                return 0.0
            if (effect.banish_name or "").lower() == "attacks_targeting_you":
                actor.class_state["AttacksTargetingYouPenalty"] = abs(effect.amount or 1)
                self._event_append(
                    f"attacks targeting you get {effect.amount:+d} power this turn"
                )
            elif (effect.banish_name or "").lower() == "all_pitch_zones_x2":
                if combat is not None:
                    total = sum(len(self._players[i].pitch_zone) for i in (0, 1))
                    bonus = total * 2
                    if bonus > 0:
                        self._apply_combat_power_bonus(
                            combat,
                            player_idx,
                            bonus,
                            reason=f"+{bonus} power ({total} cards in pitch zones x2)",
                        )
            elif (effect.banish_name or "").lower() == "last_banish_count":
                if combat is not None:
                    bonus = actor.class_state.get("LastVariableBanishCount", 0)
                    if bonus > 0:
                        self._apply_combat_power_bonus(
                            combat,
                            player_idx,
                            bonus,
                            reason=f"+{bonus} power (items banished to play)",
                        )
            elif combat is not None:
                if (effect.banish_name or "").lower() == "chain" and effect.target == "opponent":
                    combat.opposing_power_mod += effect.amount
                    self._event_append(
                        f"opposing attacks {effect.amount:+d} power this combat chain"
                    )
                else:
                    self._apply_combat_power_bonus(
                        combat,
                        player_idx,
                        effect.amount,
                        reason=f"{effect.amount:+d} power on chain",
                    )
                if effect.go_again:
                    self._grant_go_again(player_idx, combat, this_card=True)
            return 0.0
        if effect.kind == "dominate":
            if combat is not None:
                combat.dominate = True
            return 0.0
        if effect.kind == "intimidate":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            self._do_intimidate(target_idx)
            return 0.0
        if effect.kind == "draw":
            if effect.target == "each_hero":
                if (effect.banish_name or "").lower() == "up_to_intellect":
                    for idx in (0, 1):
                        self._draw_up(idx)
                    return 0.0
                for idx in (0, 1):
                    for _ in range(max(1, effect.amount or 1)):
                        self._draw_card(idx, from_action=True)
                return 0.0
            target_idx = player_idx
            if effect.target in ("opponent", "ally"):
                target_idx = 1 - player_idx
            for _ in range(max(1, effect.amount or 1)):
                self._draw_card(target_idx, from_action=True)
            if target_idx == player_idx:
                pass  # NumCardsDrawn updated per card in _draw_card
            return 0.0
        if effect.kind in ("damage", "arcane_damage"):
            if (effect.banish_name or "").lower() == "cleave":
                amount = max(0, actor.class_state.get("LastHitDamage", 0))
                if amount <= 0:
                    return 0.0
                target_idx = 1 - player_idx
                target = self._players[target_idx]
                amount = self._mitigate_damage(target_idx, amount)
                if amount <= 0:
                    return 0.0
                target.life -= amount
                actor.class_state["DamageDealt"] += amount
                target.class_state["DamageTaken"] += amount
                self._event_append(f"cleave deals {amount} damage to P{target_idx}")
                r = float(amount) * 0.01
                return r if perspective_idx == player_idx else -r
            hits = 1
            if effect.condition.startswith("multi:"):
                hits = max(1, int(effect.condition.split(":")[1]))
            target_idx = self._damage_target_idx(player_idx, effect, combat)
            target = self._players[target_idx]
            total_r = 0.0
            total_dealt = 0
            for _ in range(hits):
                amount = effect.amount
                if (effect.banish_name or "").startswith("token_count:"):
                    token = (effect.banish_name or "").split(":", 1)[1]
                    key = token_defs.normalize_token_name(token)
                    amount = target.tokens.get(key, 0)
                if (effect.banish_name or "").lower() == "equipment_count":
                    amount = len(target.equipment)
                if (effect.banish_name or "").lower().startswith("ice_markers:"):
                    base = int((effect.banish_name or "ice_markers:0").split(":", 1)[1])
                    amount = base + self._count_ice_markers(target_idx)
                if (effect.banish_name or "").lower() == "red_reveal_double":
                    amount = actor.class_state.get("LastRevealRedCount", 0) * 2
                if effect.kind == "damage":
                    amount = self._apply_damage_floor(player_idx, amount)
                if effect.kind == "arcane_damage" and actor.amp > 0:
                    amount += actor.amp
                    self._event_append(f"amp +{actor.amp} arcane damage")
                    actor.amp = 0
                if effect.kind == "arcane_damage" and actor.class_state.get("ArcanePlusOneThisPlay", 0):
                    amount += 1
                    actor.class_state["ArcanePlusOneThisPlay"] = 0
                    self._event_append("Metacarpus Node: +1 arcane damage")
                if effect.kind == "arcane_damage" and actor.class_state.get("ArcanePlusOneTurn", 0):
                    amount += 1
                    self._event_append("action arcane +1 this turn")
                if effect.kind == "arcane_damage":
                    amount = self._mitigate_damage(
                        target_idx, amount, arcane=True, source_idx=player_idx
                    )
                else:
                    amount = self._mitigate_damage(target_idx, amount)
                if amount <= 0:
                    continue
                target.life -= amount
                target.class_state["DamageTakenThisTurn"] = (
                    target.class_state.get("DamageTakenThisTurn", 0) + amount
                )
                total_dealt += amount
                r = float(amount) * 0.01
                total_r += r if perspective_idx == player_idx else -r
            if total_dealt:
                key = "DamageDealt" if effect.kind == "damage" else "ArcaneDamageDealt"
                actor.class_state[key] += total_dealt
                target.class_state["DamageTaken"] += total_dealt
            return total_r
        if effect.kind == "create_token":
            if effect.target == "each_hero":
                count = max(1, effect.amount or 1)
                for idx in (0, 1):
                    self._create_token(idx, effect.token_name, count)
                return 0.0
            if effect.condition == "hero_thief:pay_gold":
                if actor.gold <= 0:
                    return 0.0
                actor.gold -= 1
            if effect.target == "ally":
                target_idx = 1 - player_idx
            elif effect.target == "defender":
                target_idx = combat.defender if combat is not None else (1 - player_idx)
            elif effect.target == "opponent":
                target_idx = 1 - player_idx
            else:
                target_idx = player_idx
            count = max(1, effect.amount or 1)
            if (effect.banish_name or "").lower() == "other_heroes":
                count = 1
            elif (effect.banish_name or "").lower() == "weapon_hits":
                count = max(0, actor.class_state.get("WeaponHitsThisTurn", 0))
            elif (effect.banish_name or "").lower() == "damage_dealt":
                count = max(0, actor.class_state.get("LastHitDamage", 0))
            elif (effect.banish_name or "").lower() == "pitch_value":
                count = max(1, card.pitch if card else 1)
            elif (effect.banish_name or "").lower() == "naa_played_this_turn":
                count = max(0, actor.class_state.get("NumNonAttackCards", 0))
            elif (effect.banish_name or "").lower().startswith("naa_played:"):
                count = max(0, actor.class_state.get("NumNonAttackCards", 0))
            elif (effect.banish_name or "").lower().startswith("life_diff_double:"):
                token_name = (effect.banish_name or "").split(":", 1)[1]
                opp = self._players[1 - player_idx]
                diff = max(0, opp.life - actor.life)
                count = diff * 2
                if count > 0:
                    self._create_token(player_idx, token_name, count)
                return 0.0
            if count <= 0:
                return 0.0
            self._create_token(target_idx, effect.token_name, count)
            rider = (effect.banish_name or "").lower()
            if ":go_again_if_ge:" in rider:
                threshold = int(rider.rsplit(":", 1)[1])
                if count >= threshold:
                    self._grant_go_again(player_idx, combat)
            return 0.0
        if effect.kind == "create_banished":
            amount = max(1, effect.amount or 1)
            if effect.amount == 0 and effect.token_name:
                key = token_defs.normalize_token_name(effect.token_name)
                amount = max(1, actor.tokens.get(key, 0))
            for _ in range(amount):
                self._create_in_banished(
                    player_idx,
                    effect.banish_name or effect.token_name,
                    playable=effect.playable_banished,
                    power_bonus=0,
                )
            return 0.0
        if effect.kind == "create_in_hand":
            self._create_in_hand(
                player_idx,
                effect.banish_name or effect.token_name or "",
                max(1, effect.amount or 1),
            )
            return 0.0
        if effect.kind == "named_power_bonus":
            if (effect.banish_name or "").lower() == "this_chain":
                pattern = actor.named_card if actor.named_card else "named"
                key = f"NamedPower:{pattern}"
                actor.class_state[key] = actor.class_state.get(key, 0) + max(
                    1, effect.amount or 1
                )
                self._event_append(
                    f"named card attacks get +{effect.amount or 1} power this combat chain"
                )
                return 0.0
            pattern = token_defs.normalize_token_name(
                effect.token_name or effect.banish_name or ""
            )
            if pattern:
                key = f"NamedPower:{pattern}"
                actor.class_state[key] = actor.class_state.get(key, 0) + max(
                    1, effect.amount or 1
                )
                self._event_append(f"{pattern} attacks get +{effect.amount or 1} power this turn")
            return 0.0
        if effect.kind == "banish_top":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            for _ in range(max(1, effect.amount or 1)):
                self._banish_top_card(target_idx)
            return 0.0
        if effect.kind == "banish_defending":
            defender_idx = 1 - player_idx
            self._banish_top_card(defender_idx)
            self._banish_defending_card(combat, defender_idx)
            return 0.0
        if effect.kind == "banish_graveyard":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            self._banish_from_graveyard(target_idx, max(1, effect.amount or 1))
            return 0.0
        if effect.kind == "banish_arsenal":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            target = self._players[target_idx]
            if target.arsenal:
                cid = target.arsenal.pop()
                target.banished.append(cid)
                self._event_append(f"banished {self._cards[cid].name} from arsenal")
            return 0.0
        if effect.kind == "discard":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            self._discard_random(target_idx, max(1, effect.amount or 1))
            return 0.0
        if effect.kind == "destroy_top":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            self._destroy_top_of_deck(target_idx, max(1, effect.amount or 1))
            return 0.0
        if effect.kind == "destroy_arsenal":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            self._destroy_arsenal(target_idx, max(1, effect.amount or 99))
            return 0.0
        if effect.kind == "destroy_hand":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            target = self._players[target_idx]
            rider = (effect.banish_name or "").lower()
            if rider == "soul":
                if not target.soul:
                    self._event_append("no cards in soul to banish")
                    return 0.0
                cid = target.soul.pop()
                target.banished.append(cid)
                self._record_soul_banish_chain(target_idx)
                self._event_append(f"banished {self._cards[cid].name} from soul")
                return 0.0
            if rider.startswith("create:"):
                token = rider.split(":", 1)[1]
                if not actor.hand:
                    self._event_append("no card in hand to banish")
                    return 0.0
                cid = actor.hand.pop()
                actor.banished.append(cid)
                self._event_append(f"banished {self._cards[cid].name} from hand")
                self._create_token(player_idx, token, 1)
                return 0.0
            self._discard_random(target_idx, max(1, effect.amount or 1))
            return 0.0
        if effect.kind == "gain_resources":
            rider = (effect.banish_name or "").lower()
            if rider == "roll_d6_half":
                self._pending_die_roll = {
                    "controller": player_idx,
                    "kind": "gain_resources_half",
                }
                if self._pause_for_gambler(player_idx):
                    return 0.0
                self._continue_pending_die_roll()
                return 0.0
            actor.resources += max(1, effect.amount or 1)
            self._event_append(f"gained {effect.amount or 1} resources")
            return 0.0
        if effect.kind == "damage_floor":
            threshold = max(1, effect.max_cost if effect.max_cost > 0 else (effect.amount or 1))
            amount = max(1, effect.amount or 1)
            actor.class_state["DamageFloorThreshold"] = threshold
            actor.class_state["DamageFloorAmount"] = amount
            self._event_append(
                f"next damage below {threshold} will become {amount} instead"
            )
            return 0.0
        if effect.kind == "prevent_damage":
            target_idx = player_idx
            if effect.target in ("opponent", "any"):
                target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            target = self._players[target_idx]
            if (effect.banish_name or "").lower() == "roll_d6":
                self._pending_die_roll = {
                    "controller": target_idx,
                    "kind": "prevent_d6",
                }
                if self._pause_for_gambler(target_idx):
                    return 0.0
                self._continue_pending_die_roll()
                return 0.0
            elif effect.condition.startswith("per_hit:"):
                charges = int(effect.condition.split(":", 1)[1])
                target.prevent_damage_charges = charges
                target.prevent_damage_per_hit = max(1, effect.amount or 1)
                self._event_append(
                    f"P{target_idx} will prevent {target.prevent_damage_per_hit} damage "
                    f"the next {charges} times they would be dealt damage"
                )
            else:
                target.prevent_damage += max(1, effect.amount or 1)
                self._event_append(f"P{target_idx} will prevent {effect.amount or 1} damage")
            return 0.0
        if effect.kind == "ward":
            # Ward is a static ability on permanents (CR 8.3.20), not a hero buff.
            self._event_append(f"{card.name}: ward {effect.amount or 1} (static on permanent)")
            return 0.0
        if effect.kind == "opt":
            self._do_opt(player_idx, max(1, effect.amount or 1))
            return 0.0
        if effect.kind == "mark":
            defender.marked = True
            self._event_append("hero marked (CR 8.5.50)")
            return 0.0
        if effect.kind == "put_soul":
            actor = self._players[player_idx]
            color_filter = (effect.banish_name or "").lower()
            if color_filter == "self_from_chain":
                soul_id = card.id
                for zone in (actor.hand, actor.discard, actor.banished):
                    if soul_id in zone:
                        zone.remove(soul_id)
                        break
            if soul_id not in actor.soul:
                actor.soul.append(soul_id)
                actor.class_state["SoulCardThisTurn"] = 1
                self._event_append(f"{card.name} put into soul")
                return 0.0
            if color_filter == "destroyed_light":
                return 0.0
            if color_filter in ("red", "yellow", "blue"):
                pitch_map = {"red": 1, "yellow": 2, "blue": 3}
                target_pitch = pitch_map[color_filter]
                for i, cid in enumerate(actor.hand):
                    if self._cards[cid].pitch == target_pitch:
                        soul_id = actor.hand.pop(i)
                        break
                else:
                    soul_id = None
            elif card.id in actor.hand:
                actor.hand.remove(card.id)
                soul_id = card.id
            elif card.id in actor.discard:
                actor.discard.remove(card.id)
                soul_id = card.id
            elif actor.hand:
                soul_id = actor.hand.pop()
            else:
                soul_id = None
            if soul_id is None:
                self._event_append("no card available to put into soul")
                return 0.0
            if soul_id not in actor.soul:
                actor.soul.append(soul_id)
            actor.class_state["SoulCardThisTurn"] = 1
            self._event_append(f"{self._cards[soul_id].name} charged to soul")
            actor.class_state["ChargedThisTurn"] = 1
            soul_card = self._cards[soul_id]
            if soul_card.pitch == 2:
                actor.class_state["ChargedYellowThisPlay"] = 1
                actor.class_state["YellowSoulThisTurn"] = 1
            for trig in effects.parse_triggers(soul_card.text):
                if trig.when == "on_soul_enter":
                    self._apply_effect(player_idx, soul_card, trig.effect, combat, perspective_idx)
            rider = (effect.banish_name or "")
            if rider.startswith("create_if:"):
                _, cls_filter, token_name = rider.split(":", 2)
                if cls_filter.lower() in (soul_card.card_class or "").lower():
                    self._create_token(player_idx, token_name, 1)
                    self._event_append(f"created {token_name} token")
            return 0.0
        if effect.kind == "reveal_hand":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            target = self._players[target_idx]
            if (effect.banish_name or "").lower() == "hand_and_deck":
                hand_names = [self._cards[cid].name for cid in target.hand]
                top = self._deck_top_card_id(target_idx)
                deck_name = self._cards[top].name if top else None
                parts = []
                if hand_names:
                    who = "opponent" if target_idx != player_idx else "your"
                    parts.append(f"{who} hand: {', '.join(hand_names)}")
                if deck_name:
                    parts.append(f"deck top: {deck_name}")
                if parts:
                    self._event_append("looked at " + "; ".join(parts))
                else:
                    self._event_append("hand and deck top empty")
                return 0.0
            n = max(1, effect.amount or 1)
            if (effect.banish_name or "").lower() == "store_revealed":
                if effect.amount <= 0:
                    n = len(target.hand)
                elif effect.condition == "opponent_turn_all" and self._active_player != player_idx:
                    n = len(target.hand)
                revealed = list(target.hand[: min(n, len(target.hand))])
                target.revealed_hand = revealed
                names = [self._cards[cid].name for cid in revealed]
                if names:
                    who = "opponent" if target_idx != player_idx else "your"
                    self._event_append(f"{who} hand revealed: {', '.join(names)}")
                else:
                    self._event_append("no cards in hand to reveal")
                return 0.0
            sample = [self._cards[cid].name for cid in target.hand[:n]]
            if sample:
                who = "opponent" if target_idx != player_idx else "your"
                self._event_append(f"{who} hand revealed: {', '.join(sample)}")
            else:
                self._event_append("no cards in hand to reveal")
            return 0.0
        if effect.kind == "choose_card":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            target = self._players[target_idx]
            rider = (effect.banish_name or "put_bottom").lower()
            if rider == "destroy_item_landmark":
                options = []
                for i, cid in enumerate(target.equipment):
                    card_obj = self._cards[cid]
                    tl = (card_obj.type_line or "").lower()
                    if self._is_ally_card(card_obj) or "landmark" in tl:
                        options.append(
                            {"index": i, "card_id": cid, "name": card_obj.name}
                        )
                prompt = effect.raw or "Choose an item or landmark"
                resume = "after_attack" if combat is not None else "after_play"
                paused = self._begin_card_choice(
                    target_idx,
                    target_idx,
                    options,
                    rider="destroy_permanent",
                    optional=effect.optional,
                    prompt=prompt,
                    resume=resume,
                )
                if paused:
                    self._choice_ctx.update(
                        {
                            "return_phase": self._phase,
                            "card_id": card.id,
                            "fused": bool(combat.fused if combat else False),
                            "perspective": perspective_idx,
                        }
                    )
                return 0.0
            target.revealed_hand = list(target.hand)
            from_revealed = effect.condition == "revealed_only"
            no_defense = effect.condition == "no_defense"
            options = self._choice_options_for_hand(
                target_idx,
                from_revealed=from_revealed,
                filter_no_defense=no_defense,
            )
            rider = (effect.banish_name or "put_bottom").lower()
            prompt = effect.raw or "Choose a card"
            resume = "after_attack" if combat is not None else "after_play"
            paused = self._begin_card_choice(
                player_idx,
                target_idx,
                options,
                rider=rider,
                optional=effect.optional,
                prompt=prompt,
                resume=resume,
            )
            if paused:
                self._choice_ctx.update(
                    {
                        "return_phase": self._phase,
                        "card_id": card.id,
                        "fused": bool(combat.fused if combat else False),
                        "perspective": perspective_idx,
                    }
                )
            return 0.0
        if effect.kind == "choose_mode":
            if combat is not None:
                resume = "after_attack"
            elif self._pending_combat is not None:
                resume = "after_hit_combat"
            else:
                resume = "after_play_direct"
            paused = self._begin_mode_choice(
                player_idx,
                card,
                effect,
                resume=resume,
                perspective_idx=perspective_idx,
                combat=combat,
            )
            return 0.0
        if effect.kind == "reduce_defense":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            rider = (effect.banish_name or "").lower()
            if rider == "next_defend_reactions":
                self._players[target_idx].class_state["NextDefendReactionPenalty"] = max(
                    1, effect.amount or 1
                )
                self._event_append("next defend with reactions gets -1 defense")
                return 0.0
            if rider == "next_defend_equipment":
                self._players[target_idx].class_state["NextDefendEquipmentPenalty"] = max(
                    1, effect.amount or 1
                )
                self._event_append("next defend with equipment gets -1 defense")
                return 0.0
            if rider == "next_defend_actions":
                self._players[target_idx].class_state["NextDefendActionPenalty"] = max(
                    1, effect.amount or 1
                )
                self._event_append("next defend with attack actions gets -1 defense")
                return 0.0
            self._apply_equipment_defense_debuff(target_idx, max(1, effect.amount or 1))
            return 0.0
        if effect.kind == "clash":
            routine = (effect.banish_name or "").lower()
            loser_debuff = routine == "loser_equipment_debuff"
            self._do_clash(
                player_idx,
                effect.token_name or "",
                loser_debuff=loser_debuff,
                routine=routine,
                source_card=card,
            )
            return 0.0
        if effect.kind == "pitch_bonus":
            actor.class_state["PitchBonusLightPlusOne"] = 1
            self._event_append("light pitch gains +1 resource while equipped")
            return 0.0
        if effect.kind == "amp":
            if (effect.banish_name or "").lower() == "action_arcane_turn":
                actor.class_state["ArcanePlusOneTurn"] = 1
                self._event_append("action arcane effects deal +1 this turn")
            elif (effect.banish_name or "").lower() == "attack_damage_turn":
                actor.class_state["AttackDamagePlusOneTurn"] = 1
                self._event_append("attack damage +1 this turn")
            else:
                actor.amp += max(1, effect.amount or 1)
                self._event_append(f"amp {effect.amount or 1}: next arcane +{effect.amount or 1}")
            return 0.0
        if effect.kind in ("reload", "stash_hand"):
            if effect.condition == "empty_arsenal" and actor.arsenal:
                return 0.0
            legal = self._legal_stash(player_idx)
            if not legal:
                return 0.0
            self._do_stash(player_idx, legal[0])
            return 0.0
        if effect.kind == "unless_pay":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            target = self._players[target_idx]
            cost = max(1, effect.amount or 1)
            rider = (effect.banish_name or "discard").lower()
            if target.resources >= cost:
                target.resources -= cost
                if rider.startswith("power:"):
                    self._event_append(
                        f"P{target_idx} paid {cost} resource(s) to avoid power loss"
                    )
                else:
                    self._event_append(f"P{target_idx} paid {cost} to avoid discard")
            elif rider.startswith("power:"):
                pen = int(rider.split(":", 1)[1])
                if combat is not None:
                    self._apply_combat_power_bonus(
                        combat,
                        player_idx,
                        -pen,
                        reason=f"-{pen} power (didn't pay {cost})",
                    )
                else:
                    self._event_append(
                        f"P{target_idx} didn't pay {cost}; attack gets -{pen} power"
                    )
            else:
                self._discard_random(target_idx, 1)
            return 0.0
        if effect.kind == "search":
            rider = (effect.banish_name or "").lower()
            if ":deck_top" in rider:
                card_type = rider.split(":", 1)[0]
                self._search_deck_to_top(player_idx, card_type=card_type)
                return 0.0
            card_type = ""
            name_pattern = effect.banish_name or ""
            if name_pattern == "attack_action":
                card_type = "attack_action"
                name_pattern = ""
            self._search_deck(
                player_idx,
                name_pattern=name_pattern,
                max_cost=effect.max_cost,
                card_type=card_type,
            )
            return 0.0
        if effect.kind == "boost":
            if not actor.deck:
                return 0.0
            top = actor.deck.pop()
            actor.banished.append(top)
            actor.class_state["CardsBanishedThisTurn"] += 1
            if self._cards[top].power >= 6:
                actor.class_state["BanishedPower6ThisTurn"] = 1
            actor.class_state["BoostedThisTurn"] = 1
            self._event_append(f"boost: banished {self._cards[top].name}")
            if self._is_arena_permanent(self._cards[top]):
                self._fire_deck_banish_item_triggers(player_idx, perspective_idx)
            if "hyper driver" in self._cards[top].name.lower():
                self._fire_equipment_triggers(player_idx, "on_boost_banish", perspective_idx)
            hero_class = (actor.hero.name or "").lower()
            card_class = (card.card_class or "").lower()
            if "mechanologist" in card_class or "mechanologist" in hero_class:
                if combat is not None:
                    self._grant_go_again(player_idx, combat, this_card=True)
                else:
                    actor.action_points += 1
                self._event_append("Mechanologist boost: go again")
            return 0.0
        if effect.kind == "gain_gold":
            target_idx = player_idx
            if effect.target in ("opponent", "ally"):
                target_idx = 1 - player_idx
            target = self._players[target_idx]
            amount = effect.amount or 1
            if amount > 0 and target.class_state.get("BlockGoldGainTurn", 0):
                self._event_append(f"P{target_idx} can't gain {{g}} this turn")
                return 0.0
            if amount < 0:
                target.gold = max(0, target.gold + amount)
                self._event_append(f"P{target_idx} lost {-amount}{{g}} (total {target.gold})")
            else:
                target.gold += amount
                self._event_append(f"P{target_idx} gained {amount}{{g}} (total {target.gold})")
            if amount > 0 and target_idx == player_idx:
                self._fire_whenever_gain_gold_triggers(player_idx, perspective_idx)
            return 0.0
        if effect.kind == "lose_gold":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            amount = max(1, effect.amount or 1)
            target = self._players[target_idx]
            target.gold = max(0, target.gold - amount)
            self._event_append(f"P{target_idx} lost {amount}{{g}} (total {target.gold})")
            return 0.0
        if effect.kind == "block_power_gain":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            if combat is not None:
                combat.block_power_gain = True
            self._players[target_idx].class_state["BlockPowerGainThisTurn"] = 1
            self._event_append("attacks can't gain power this turn")
            return 0.0
        if effect.kind == "reduce_next_power_gain":
            if combat is not None:
                combat.next_power_gain_reduction = max(1, effect.amount or 1)
                self._event_append(
                    f"next power gain on chain reduced by {combat.next_power_gain_reduction}"
                )
            return 0.0
        if effect.kind == "block_hit_effects":
            if combat is not None:
                combat.hit_effects_blocked = True
                combat.hit_effects_unblock_cost = max(1, effect.amount or 1)
                self._event_append(
                    "hit effects blocked unless attacker pays "
                    f"{combat.hit_effects_unblock_cost} resources"
                )
            return 0.0
        if effect.kind == "block_defense_reactions":
            if effect.condition == "turn":
                for idx in (0, 1):
                    self._players[idx].class_state["BlockDefenseReactionsTurn"] = 1
                self._event_append("defense reactions can't be played this turn")
            elif combat is not None:
                combat.defense_reactions_blocked = True
                self._event_append("defense reactions can't be played to this chain link")
            return 0.0
        if effect.kind == "return_gy_to_deck":
            self._return_from_gy_to_deck(
                player_idx,
                effect.banish_name or "",
                to_bottom=effect.target == "bottom",
            )
            return 0.0
        if effect.kind == "cost_reduction":
            actor.class_state["NextPlayCostReduction"] = (
                actor.class_state.get("NextPlayCostReduction", 0) + max(1, effect.amount or 1)
            )
            self._event_append(f"next card costs {effect.amount or 1} less to play")
            return 0.0
        if effect.kind == "silence":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            self._players[target_idx].silenced = True
            self._event_append(f"P{target_idx} silenced until end of next turn")
            return 0.0
        if effect.kind == "wager":
            token = effect.token_name or "wager"
            for idx in (player_idx, 1 - player_idx):
                self._create_token(idx, token)
            self._event_append(f"wager: both heroes staked {token} token")
            self._fire_whenever_wager_triggers(player_idx)
            return 0.0
        if effect.kind == "look_deck":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            if (effect.banish_name or "").lower() == "event_deck":
                self._event_append("looked at top 3 cards of the event deck (event deck not modeled)")
                return 0.0
            if (effect.banish_name or "").lower() == "reveal_red_count":
                actor = self._players[player_idx]
                red = 0
                names: list[str] = []
                deck = actor.deck
                n = max(1, effect.amount or 1)
                for i in range(min(n, len(deck))):
                    cid = deck[-(i + 1)]
                    names.append(self._cards[cid].name)
                    if self._cards[cid].pitch == 1:
                        red += 1
                actor.class_state["LastRevealRedCount"] = red
                if names:
                    self._event_append(
                        f"revealed top {len(names)}: {', '.join(names)} ({red} red)"
                    )
                return 0.0
            names = []
            for _ in range(max(1, effect.amount or 1)):
                top = self._deck_top_card_id(target_idx)
                if top:
                    names.append(self._cards[top].name)
            if names:
                who = "opponent" if target_idx != player_idx else "your"
                self._event_append(f"looked at {who} deck top: {', '.join(names)}")
            return 0.0
        if effect.kind == "put_counter":
            token = (effect.token_name or "counter").lower()
            if effect.condition == "arsenal_crush":
                for cid in actor.arsenal:
                    cc = self._cards[cid]
                    if "crush" in cc.keywords or "crush" in (cc.text or "").lower():
                        amt = max(1, effect.amount or 1)
                        self._add_permanent_counter(player_idx, cid, token, amt)
                        self._event_append(f"put +{amt} {token} counter on {cc.name} in arsenal")
                        return 0.0
                return 0.0
            if token == "gold":
                actor.gold += 1
                target = effect.banish_name or "permanent"
                self._event_append(f"put gold counter on {target} (hero gold={actor.gold})")
            elif (effect.banish_name or "").lower() == "ward_auras":
                amt = max(1, effect.amount or 1)
                token = (effect.token_name or "power").lower()
                touched = 0
                for cid in actor.equipment:
                    eq = self._cards[cid]
                    line = (eq.type_line or "").lower()
                    if " aura" not in line and not line.endswith("aura"):
                        continue
                    if "ward" not in (eq.text or "").lower() and "ward" not in eq.keywords:
                        continue
                    self._add_permanent_counter(player_idx, cid, token, amt)
                    touched += 1
                if touched:
                    self._event_append(f"put +{amt} {token} counter on {touched} ward aura(s)")
            elif (effect.banish_name or "").lower() == "reveal_red_count":
                count = actor.class_state.get("LastRevealRedCount", 0)
                token = (effect.token_name or "power").lower()
                if count > 0 and card.id:
                    self._add_permanent_counter(player_idx, card.id, token, count)
                    self._event_append(f"put +{count} {token} counter on {card.name}")
            elif card.id:
                self._add_permanent_counter(player_idx, card.id, token)
                self._event_append(f"put {token} counter on {card.name}")
            else:
                self._add_permanent_counter(player_idx, card.id or "hero", token)
                self._event_append(f"put {token} counter")
            return 0.0
        if effect.kind == "reveal_top":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            target = self._players[target_idx]
            top = self._deck_top_card_id(target_idx)
            if not top:
                self._event_append("no card on deck top to reveal")
                return 0.0
            card = self._cards[top]
            if (effect.banish_name or "").lower() == "store_revealed":
                target.revealed_hand = [top]
                actor.class_state["LastRevealedDeckTopId"] = top
                actor.class_state["LastRevealedDeckTopPower"] = card.power
            who = "opponent" if target_idx != player_idx else "your"
            self._event_append(f"{who} deck top revealed: {card.name} ({card.power} power)")
            return 0.0
        if effect.kind == "put_bottom":
            if (effect.banish_name or "").lower().startswith("yellow_any_gy"):
                moved = False
                for idx in (0, 1):
                    target = self._players[idx]
                    for i, cid in enumerate(list(target.discard)):
                        if self._cards[cid].pitch != 2:
                            continue
                        cid = target.discard.pop(i)
                        target.deck.insert(0, cid)
                        self._event_append(
                            f"put {self._cards[cid].name} from P{idx} graveyard on bottom of deck"
                        )
                        moved = True
                        break
                    if moved:
                        break
                if not moved:
                    self._event_append("no yellow card in any graveyard")
                    return 0.0
                if ":create_gold" in (effect.banish_name or ""):
                    self._create_token(player_idx, "gold")
                    self._event_append("created Gold token")
                return 0.0
            if effect.target == "self" and (effect.banish_name or "").lower() == "hand_or_arsenal":
                if actor.hand:
                    cid = actor.hand.pop()
                elif actor.arsenal:
                    cid = actor.arsenal.pop()
                else:
                    self._event_append("no card in hand or arsenal to put on bottom")
                    return 0.0
                actor.deck.insert(0, cid)
                self._event_append(f"put {self._cards[cid].name} on bottom of deck")
                return 0.0
            if effect.target == "self" and card.id:
                actor.deck.insert(0, card.id)
                actor.class_state["SkipGyThisCard"] = card.id
                self._event_append(f"put {card.name} on bottom of deck")
                return 0.0
            if (effect.banish_name or "").lower() == "all_arsenals":
                for idx, p in enumerate(self._players):
                    while p.arsenal:
                        cid = p.arsenal.pop()
                        p.deck.insert(0, cid)
                        self._event_append(
                            f"put {self._cards[cid].name} from P{idx} arsenal on bottom of deck"
                        )
                return 0.0
            if (effect.banish_name or "").lower() == "draw":
                if actor.hand:
                    cid = actor.hand.pop()
                    actor.deck.insert(0, cid)
                    self._draw_card(player_idx)
                    self._event_append(
                        f"put {self._cards[cid].name} on bottom, drew a card"
                    )
                return 0.0
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            target = self._players[target_idx]
            if (effect.banish_name or "").lower() == "arsenal" and target.arsenal:
                cid = target.arsenal.pop()
                target.deck.insert(0, cid)
                self._event_append(
                    f"put {self._cards[cid].name} from arsenal on bottom of deck"
                )
            elif target.hand:
                cid = target.hand.pop()
                target.deck.insert(0, cid)
                self._event_append(f"put {self._cards[cid].name} on bottom of deck")
            elif target.arsenal:
                cid = target.arsenal.pop()
                target.deck.insert(0, cid)
                self._event_append(f"put {self._cards[cid].name} on bottom of deck")
            return 0.0
        if effect.kind == "enable_banish_play":
            pat = (effect.banish_name or "this").strip().lower()
            if pat in ("", "this"):
                actor.playable_banished.add(card.id)
            else:
                enabled = 0
                for cid in actor.banished:
                    if self._gy_play_pattern_match(self._cards[cid], pat):
                        actor.playable_banished.add(cid)
                        enabled += 1
                if enabled:
                    self._event_append(f"{enabled} banished card(s) may be played this turn")
            return 0.0
        if effect.kind == "enable_gy_play":
            self._enable_graveyard_play(player_idx, card, effect.banish_name or "this")
            return 0.0
        if effect.kind == "pitch_pay":
            return self._begin_pitch_pay(player_idx, card, effect, perspective_idx)
        if effect.kind == "for_each":
            count = max(1, sum(actor.tokens.values()))
            if effect.token_name:
                self._create_token(player_idx, effect.token_name, count)
            return 0.0
        if effect.kind == "overpower":
            if combat is not None:
                combat.overpower = True
            return 0.0
        if effect.kind in ("transcend", "contract", "blood_debt"):
            if effect.kind == "transcend":
                actor.hand.append(card.id)
                actor.class_state["TranscendedThisTurn"] = 1
                self._event_append(f"{card.name} transcended to hand")
            elif effect.kind == "blood_debt":
                self._event_append(f"{card.name} has blood debt while banished")
            else:
                self._event_append(f"contract tracked on {card.name}")
            return 0.0
        if effect.kind == "arcane_barrier":
            if (effect.banish_name or "").lower() == "per_runechant":
                amount = actor.tokens.get("runechant", 0) * max(1, effect.amount or 1)
                actor.arcane_barrier += amount
                self._event_append(
                    f"Runechants grant spellvoid: arcane barrier {amount} until end of turn"
                )
            else:
                actor.arcane_barrier += max(1, effect.amount or 1)
                self._event_append(f"arcane barrier {actor.arcane_barrier} until end of turn")
            return 0.0
        if effect.kind == "steal_equipment":
            defender = self._players[1 - player_idx]
            max_cost = effect.amount if (effect.amount or 0) > 0 else 99
            stolen = False
            for i, cid in enumerate(list(defender.equipment)):
                item = self._cards[cid]
                tl = (item.type_line or "").lower()
                if " item" not in tl and not tl.endswith("item"):
                    continue
                if item.cost > max_cost:
                    continue
                defender.equipment.pop(i)
                actor.equipment.append(cid)
                self._event_append(f"stole {item.name} from opponent")
                stolen = True
                break
            if not stolen and (effect.banish_name or "").lower() == "or_draw":
                self._draw_card(player_idx, from_action=True)
                self._event_append("no item to steal: drew a card")
            elif not stolen:
                self._event_append("no item to steal")
            return 0.0
        if effect.kind == "steal_ally":
            opp_idx = 1 - player_idx if effect.target != "self" else player_idx
            opp = self._players[opp_idx]
            stolen_id: Optional[str] = None
            for i, cid in enumerate(list(opp.equipment)):
                if not self._is_ally_card(self._cards[cid]):
                    continue
                stolen_id = opp.equipment.pop(i)
                actor.equipment.append(stolen_id)
                self._stolen_until_phase_end.append((opp_idx, player_idx, stolen_id))
                self._event_append(
                    f"untapped and stole {self._cards[stolen_id].name} from P{opp_idx}"
                )
                break
            if not stolen_id:
                self._event_append("no ally to steal")
            return 0.0
        if effect.kind == "put_deck_top_arsenal":
            targets = [0, 1] if effect.target == "each_hero" else [player_idx]
            rider = effect.banish_name or ""
            only_empty = rider.startswith("if_empty_arsenal")
            go_again_from_arsenal = ":go_again_if_played_from_arsenal" in rider
            count = 0
            for idx in targets:
                target = self._players[idx]
                if only_empty and target.arsenal:
                    continue
                if not target.deck:
                    self._event_append(f"P{idx} has empty deck")
                    continue
                if target.arsenal:
                    self._event_append(f"P{idx} arsenal full")
                    continue
                cid = target.deck.pop()
                target.arsenal.append(cid)
                self._event_append(
                    f"P{idx} put {self._cards[cid].name} face-down in arsenal"
                )
                count += 1
            if rider.startswith("go_again_if_ge:"):
                threshold = int(rider.split(":", 1)[1])
                if count >= threshold:
                    self._grant_go_again(player_idx, combat)
            elif go_again_from_arsenal and self._players[player_idx].class_state.get(
                "PlayedFromArsenal", 0
            ):
                self._grant_go_again(player_idx, combat)
            return 0.0
        if effect.kind == "schedule_end_phase":
            rider = (effect.banish_name or "").lower()
            if rider == "return_banished_cost":
                actor.class_state["EndPhaseReturnBanishedCost"] = 1
            elif rider.startswith("draw_up_to_intellect"):
                actor.class_state["EndPhaseDrawUpToIntellect"] = 1
            else:
                actor.class_state["EndPhaseDeckTopArsenal"] = 1
            self._event_append("scheduled end-phase effect")
            return 0.0
        if effect.kind == "extra_turn":
            actor.class_state["ExtraTurnPending"] = 1
            self._event_append("extra turn granted after this one")
            return 0.0
        if effect.kind == "intellect_mod":
            actor.class_state["EndPhaseIntellectDelta"] = (
                actor.class_state.get("EndPhaseIntellectDelta", 0) + (effect.amount or 0)
            )
            self._event_append(
                f"P{player_idx} intellect {effect.amount or 0:+d} during next end phase"
            )
            return 0.0
        if effect.kind == "lose_life_per_hand_card":
            opp_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            opp = self._players[opp_idx]
            amount = len(opp.hand)
            if amount > 0:
                opp.life -= amount
                self._event_append(f"P{opp_idx} loses {amount}{{h}} (hand size)")
            return 0.0
        if effect.kind == "lose_life_per_dagger_hit":
            opp_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            opp = self._players[opp_idx]
            # Count dagger hits this chain via HitCounter on the acting player.
            amount = actor.class_state.get("HitCounter", 0)
            if amount > 0:
                opp.life -= amount
                self._event_append(f"P{opp_idx} loses {amount}{{h}} ({amount} dagger hit(s))")
            return 0.0
        if effect.kind == "power_per_block":
            if combat is not None:
                n_defenders = len(combat.reaction_cards)
                if n_defenders > 0:
                    combat.power += n_defenders
                    self._event_append(f"attack gets +{n_defenders}{{p}} ({n_defenders} defending card(s))")
            return 0.0
        if effect.kind == "limit_actions_next_turn":
            opp_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            self._players[opp_idx].class_state["MaxActionsNextTurn"] = 1
            self._event_append(f"P{opp_idx} limited to 1 action next turn")
            return 0.0
        if effect.kind == "look_face_down":
            # Face-down cards are not tracked separately; treat as no-op for RL.
            self._event_append(f"P{player_idx} looks at a face-down card (look_face_down no-op)")
            return 0.0
        if effect.kind == "set_next_instant_return_self":
            # Flag that the next instant card played on this chain link returns this card to hand.
            actor.class_state["NextInstantEffect"] = "return_self"
            if combat is not None:
                actor.class_state["NextInstantCardId"] = combat.attack_card_id
            self._event_append(f"P{player_idx} set: next instant returns attacker to hand")
            return 0.0
        if effect.kind == "set_next_instant_return_aura":
            # Flag that the next instant card played returns an opponent aura.
            actor.class_state["NextInstantEffect"] = "return_aura"
            self._event_append(f"P{player_idx} set: next instant returns target aura")
            return 0.0
        if effect.kind == "reveal_for_blue_bonus":
            # Reveal opponent's top card; if it's a blue pitch card, grant +3 power or +3 defense.
            opp_idx = 1 - player_idx
            opp = self._players[opp_idx]
            if opp.deck:
                top_cid = opp.deck[-1]
                top_card = self._cards.get(top_cid)
                if top_card is not None and getattr(top_card, "pitch", 0) == 3:
                    if combat is not None and combat.attacker == player_idx:
                        combat.power += 3
                        self._event_append("Attune: top card is blue, +3{p}")
                    elif combat is not None:
                        combat.defense += 3
                        self._event_append("Attune: top card is blue, +3{d}")
            return 0.0
        if effect.kind == "reveal_top_draconic_power":
            # Red Hot: reveal X = draconic chain links, gain +1{p} per card with cost ≥ 3.
            if combat is not None:
                x = self._draconic_chain_links(player_idx)
                revealed = actor.deck[-x:] if x > 0 else []
                bonus = sum(
                    1 for cid in revealed
                    if (self._cards.get(cid) and (getattr(self._cards[cid], "cost", 0) or 0) >= 3)
                )
                if bonus > 0:
                    combat.power += bonus
                    self._event_append(f"Red Hot: revealed {x} cards, +{bonus}{{p}} from high-cost cards")
            return 0.0
        if effect.kind == "lose_game":
            if effect.target == "self":
                target_idx = player_idx
            elif combat is not None and effect.target == "opponent":
                target_idx = combat.defender
            else:
                target_idx = 1 - player_idx
            self._players[target_idx].life = 0
            self._event_append(f"P{target_idx} loses the game")
            return 0.0
        if effect.kind == "equip_inventory":
            pattern = (effect.banish_name or "").lower()
            for cid, card in self._cards.items():
                hay = f"{card.name} {(card.type_line or '')}".lower()
                if pattern:
                    tokens = [t for t in pattern.split() if t not in ("off-hand", "off", "hand")]
                    if tokens and not all(t in hay for t in tokens):
                        continue
                    if "off-hand" in pattern and "off-hand" not in hay:
                        continue
                elif pattern not in hay:
                    continue
                if "equipment" not in card.card_types and "weapon" not in card.card_types:
                    continue
                if cid in actor.equipment or cid == actor.weapon_id:
                    continue
                actor.equipment.append(cid)
                self._fire_enters_triggers(player_idx, card)
                self._event_append(f"equipped {card.name} from inventory")
                return 0.0
            self._event_append(f"no {pattern or 'matching equipment'} in inventory to equip")
            return 0.0
        if effect.kind == "inventory_to_hand":
            pattern = (effect.banish_name or "").lower()
            for cid, card_obj in self._cards.items():
                hay = f"{card_obj.name} {(card_obj.type_line or '')} {' '.join(card_obj.card_types)}".lower()
                if pattern and pattern not in hay:
                    continue
                if "attack_action" not in card_obj.card_types:
                    continue
                if cid in actor.hand:
                    continue
                actor.hand.append(cid)
                self._event_append(f"put {card_obj.name} from inventory into hand")
                return 0.0
            self._event_append(f"no {pattern or 'matching card'} in inventory")
            return 0.0
        if effect.kind == "extra_bow_activations":
            actor.class_state["ExtraBowActivations"] = 1
            actor.class_state["BowAsInstant"] = 1
            self._event_append("bows may be activated an additional time as instant")
            return 0.0
        if effect.kind == "retrieve_gy":
            pattern = (effect.banish_name or "").lower()
            if self._pitch_cards(player_idx, 1) <= 0:
                self._event_append("declined retrieve cost")
                return 0.0
            for i, cid in enumerate(actor.discard):
                card_obj = self._cards[cid]
                hay = f"{card_obj.name} {(card_obj.type_line or '')}".lower()
                if pattern and pattern not in hay:
                    continue
                actor.discard.pop(i)
                actor.equipment.append(cid)
                self._fire_enters_triggers(player_idx, card_obj)
                self._event_append(f"retrieved {card_obj.name} from graveyard")
                return 0.0
            self._event_append("no matching card in graveyard to retrieve")
            return 0.0
        if effect.kind == "put_hand_top":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            target = self._players[target_idx]
            max_cost = effect.max_cost if effect.max_cost > 0 else 99
            type_filter = (effect.banish_name or "").lower()
            for i, cid in enumerate(list(target.hand)):
                card_obj = self._cards[cid]
                if type_filter == "action" and "action" not in card_obj.card_types:
                    continue
                if card_obj.cost > max_cost:
                    continue
                cid = target.hand.pop(i)
                target.deck.append(cid)
                self._event_append(f"put {card_obj.name} from hand on top of deck")
                return 0.0
            self._event_append("no matching card in hand to put on deck")
            return 0.0
        if effect.kind == "steal_aura":
            opp = self._players[1 - player_idx]
            stolen = False
            for i, cid in enumerate(list(opp.equipment)):
                tl = (self._cards[cid].type_line or "").lower()
                if " aura" in tl or tl.endswith("aura"):
                    opp.equipment.pop(i)
                    actor.equipment.append(cid)
                    self._event_append(f"gained control of {self._cards[cid].name}")
                    stolen = True
                    break
            if not stolen:
                self._event_append("no aura to steal")
            return 0.0
        if effect.kind == "steal_token":
            opp = self._players[1 - player_idx]
            token = token_defs.normalize_token_name(effect.token_name or "gold")
            if token == "gold":
                if opp.gold <= 0:
                    self._event_append("opponent has no gold to steal")
                    return 0.0
                opp.gold -= 1
                actor.gold += 1
            else:
                if opp.tokens.get(token, 0) <= 0:
                    self._event_append(f"opponent has no {token} token to steal")
                    return 0.0
                opp.tokens[token] -= 1
                actor.tokens[token] = actor.tokens.get(token, 0) + 1
            self._event_append(f"stole {token} token from opponent")
            return 0.0
        if effect.kind == "block_arsenal_play":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            self._players[target_idx].arsenal_play_blocked = True
            self._event_append(f"P{target_idx} cannot play face-up cards from arsenal")
            return 0.0
        if effect.kind == "block_weapon_attacks":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            self._players[target_idx].weapon_attacks_blocked = True
            self._event_append(f"P{target_idx} cannot attack with weapons this turn")
            return 0.0
        if effect.kind == "remove_counter":
            token = (effect.token_name or "").lower()
            rider = (effect.banish_name or "").lower()
            if rider == "target_all_steam" and token == "steam":
                best_cid: Optional[str] = None
                best_idx = player_idx
                best_steam = 0
                for pidx in (player_idx, 1 - player_idx):
                    target = self._players[pidx]
                    perms = list(target.equipment)
                    if target.weapon_id:
                        perms.append(target.weapon_id)
                    for cid in perms:
                        steam = self._permanent_counters(pidx, cid).get("steam", 0)
                        if steam > best_steam:
                            best_steam = steam
                            best_cid = cid
                            best_idx = pidx
                removed = 0
                if best_cid and best_steam > 0:
                    for _ in range(best_steam):
                        self._remove_permanent_counter(best_idx, best_cid, "steam")
                        removed += 1
                    actor.class_state["LastSteamRemovedCount"] = removed
                    actor.class_state["LastSteamRemovedController"] = best_idx
                self._event_append(f"removed {removed} steam counter(s) from target permanent")
                return 0.0
            if effect.target == "opponent" and token == "steam":
                target_idx = 1 - player_idx
                max_perms = 1
                if rider == "evo_count":
                    max_perms = max(
                        1,
                        sum(
                            1
                            for cid in actor.equipment
                            if "evo" in self._cards[cid].name.lower()
                        ),
                    )
                removed = 0
                touched = 0
                for cid in list(self._players[target_idx].equipment):
                    if touched >= max_perms:
                        break
                    steam = self._permanent_counters(target_idx, cid).get("steam", 0)
                    if steam <= 0:
                        continue
                    for _ in range(steam):
                        self._remove_permanent_counter(target_idx, cid, "steam")
                        removed += 1
                    touched += 1
                self._event_append(
                    f"removed {removed} steam counter(s) from P{target_idx} equipment"
                )
                return 0.0
            removed = False
            if effect.target == "attacking_weapon":
                if combat is None or not combat.is_weapon:
                    self._event_append("no attacking weapon to remove counter from")
                    return 0.0
                attacker = self._players[combat.attacker]
                weapon_id = attacker.weapon_id
                if not weapon_id or self._permanent_counters(combat.attacker, weapon_id).get(token, 0) <= 0:
                    self._event_append(f"no {token} counter on attacking weapon")
                    return 0.0
                self._remove_permanent_counter(combat.attacker, weapon_id, token)
                removed = True
                rider = effect.banish_name or ""
                if rider.startswith("create:"):
                    parts = rider.split(":")
                    tok_name = parts[1] if len(parts) > 1 else ""
                    if tok_name:
                        self._create_token(player_idx, tok_name, 1)
                    if len(parts) > 2 and parts[2] == "draw":
                        self._draw_card(player_idx, from_action=True)
                return 0.0
            if effect.target == "chest":
                for cid in actor.equipment:
                    if _equipment_slot(self._cards[cid]) != "chest":
                        continue
                    if self._permanent_counters(player_idx, cid).get(token, 0) > 0:
                        self._remove_permanent_counter(player_idx, cid, token)
                        removed = True
                        self._event_append(
                            f"removed {token} counter from {self._cards[cid].name}"
                        )
                        break
                if not removed:
                    self._event_append(f"no {token} counter on chest equipment")
                return 0.0
            if card.id and self._permanent_counters(player_idx, card.id).get(token, 0) > 0:
                self._remove_permanent_counter(player_idx, card.id, token)
                removed = True
            if not removed:
                for cid in actor.equipment:
                    if self._permanent_counters(player_idx, cid).get(token, 0) > 0:
                        self._remove_permanent_counter(player_idx, cid, token)
                        removed = True
                        break
            if not removed:
                self._event_append(f"no {token} counter on aura to remove")
                return 0.0
            self._check_no_frost_destroy(player_idx, card.id)
            rider = (effect.banish_name or "").lower()
            if rider.startswith("gain_resources:"):
                gain = int(rider.split(":", 1)[1])
                actor.resources += gain
                self._event_append(f"removed {token} counter: gained {gain} resources")
                return 0.0
            if rider == "defense":
                bonus = max(1, effect.amount or 1)
                if combat is not None and combat.blocks:
                    idx = len(combat.blocks) - 1
                    d_idx, b_cid, val = combat.blocks[idx]
                    if d_idx == player_idx:
                        combat.blocks[idx] = (d_idx, b_cid, val + bonus)
                        self._event_append(f"removed {token} counter: +{bonus} defense on block")
                else:
                    actor.class_state["NextDefenseBonus"] = (
                        actor.class_state.get("NextDefenseBonus", 0) + bonus
                    )
                    self._event_append(f"removed {token} counter: +{bonus} defense")
            return 0.0
        if effect.kind == "upkeep_or_destroy":
            token = (effect.token_name or "").lower()
            counters = self._permanent_counters(player_idx, card.id)
            if counters.get(token, 0) > 0:
                self._remove_permanent_counter(player_idx, card.id, token)
                self._event_append(f"removed {token} counter from {card.name} (upkeep)")
            else:
                if card.id in actor.equipment:
                    actor.equipment.remove(card.id)
                elif card.id == actor.weapon_id:
                    actor.weapon_id = None
                actor.discard.append(card.id)
                self._fire_on_leave_triggers(player_idx, card.id, perspective_idx)
                self._event_append(f"destroyed {card.name} (failed upkeep)")
            return 0.0
        if effect.kind == "play_power_cap":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            self._players[target_idx].attack_play_power_cap = max(0, effect.amount or 0)
            self._event_append(
                f"P{target_idx} cannot play attacks with "
                f"{effect.amount or 0} or less base power this turn"
            )
            return 0.0
        if effect.kind == "dagger_damage":
            riders = (effect.banish_name or "").lower()
            each = "each" in riders
            not_on_chain = "not_on_chain" in riders
            destroy = "destroy" in riders
            daggers = self._dagger_ids_controlled(player_idx)
            if not_on_chain and combat is not None:
                on_chain = self._daggers_on_chain(combat)
                daggers = [d for d in daggers if d not in on_chain]
            if not each:
                daggers = daggers[:1]
            if not daggers:
                self._event_append("no legal dagger for damage")
                return 0.0
            if effect.target == "defender" and combat is not None:
                target_idx = combat.defender
            elif effect.target in ("attacked", "defender") and combat is not None:
                target_idx = combat.defender
            else:
                target_idx = self._damage_target_idx(player_idx, effect, combat)
            target = self._players[target_idx]
            amount = max(1, effect.amount or 1)
            total_r = 0.0
            total_dealt = 0
            destroyed: list[str] = []
            for dagger_id in daggers:
                dmg = self._mitigate_damage(target_idx, amount)
                if dmg <= 0:
                    continue
                target.life -= dmg
                target.class_state["DamageTakenThisTurn"] = (
                    target.class_state.get("DamageTakenThisTurn", 0) + dmg
                )
                total_dealt += dmg
                r = float(dmg) * 0.01
                total_r += r if perspective_idx == player_idx else -r
                self._event_append(
                    f"{self._cards[dagger_id].name} deals {dmg} damage to P{target_idx}"
                )
                if destroy:
                    destroyed.append(dagger_id)
            if total_dealt:
                actor.class_state["DamageDealt"] += total_dealt
                target.class_state["DamageTaken"] += total_dealt
            for dagger_id in destroyed:
                self._destroy_controlled_dagger(player_idx, dagger_id, perspective_idx)
            return total_r
        if effect.kind == "destroy_item":
            if (effect.banish_name or "").lower() == "all_cogs":
                destroyed = 0
                for cid in list(actor.equipment):
                    if "cog" not in self._cards[cid].name.lower():
                        continue
                    actor.equipment.remove(cid)
                    actor.discard.append(cid)
                    self._fire_on_leave_triggers(player_idx, cid, perspective_idx)
                    destroyed += 1
                self._event_append(f"destroyed {destroyed} cog(s)")
                return 0.0
            if (effect.banish_name or "").lower() == "your_hero":
                if card.id in actor.hand:
                    actor.hand.remove(card.id)
                actor.discard.append(card.id)
                self._event_append(f"destroyed {card.name} after hit")
                return 0.0
            if (effect.banish_name or "").lower() == "reroll_d6" and self._pending_die_roll is not None:
                self._pending_die_roll["reroll"] = True
            if effect.condition == "no_soul" and actor.soul:
                return 0.0
            destroyed = False
            create_after = ""
            rider = (effect.banish_name or "").lower()
            if rider.startswith("create:"):
                create_after = effect.banish_name.split(":", 1)[1].strip()
            if rider == "defender_equipment":
                if card.id in actor.equipment or card.id == actor.weapon_id:
                    if card.id in actor.equipment:
                        actor.equipment.remove(card.id)
                    elif card.id == actor.weapon_id:
                        actor.weapon_id = None
                    actor.discard.append(card.id)
                    self._fire_on_destroy_triggers(player_idx, card.id, perspective_idx)
                    self._fire_controlled_destroy_triggers(player_idx, card, perspective_idx)
                    self._fire_on_leave_triggers(player_idx, card.id, perspective_idx)
                    self._event_append(f"destroyed {card.name}")
                    destroyed = True
                defender_idx = 1 - player_idx
                def_actor = self._players[defender_idx]
                if def_actor.equipment:
                    d_cid = def_actor.equipment.pop(0)
                    def_actor.discard.append(d_cid)
                    self._fire_on_leave_triggers(defender_idx, d_cid, perspective_idx)
                    self._event_append(f"destroyed defending {self._cards[d_cid].name}")
                    destroyed = True
                if destroyed and effect.optional and effect.raw:
                    from .effect_coverage import _parse_destroy_then_clause

                    for fe in _parse_destroy_then_clause(effect.raw):
                        self._apply_effect(
                            player_idx, card, fe, combat, perspective_idx
                        )
                return 0.0
            if card.id in actor.equipment or card.id == actor.weapon_id:
                if card.id in actor.equipment:
                    actor.equipment.remove(card.id)
                elif card.id == actor.weapon_id:
                    actor.weapon_id = None
                actor.discard.append(card.id)
                self._fire_on_destroy_triggers(player_idx, card.id, perspective_idx)
                self._fire_controlled_destroy_triggers(player_idx, card, perspective_idx)
                self._fire_on_leave_triggers(player_idx, card.id, perspective_idx)
                self._event_append(f"destroyed {card.name}")
                destroyed = True
            if not destroyed:
                for i, cid in enumerate(actor.equipment):
                    tl = (self._cards[cid].type_line or "").lower()
                    if " item" in tl or tl.endswith("item"):
                        cid = actor.equipment.pop(i)
                        actor.discard.append(cid)
                        self._fire_on_destroy_triggers(player_idx, cid, perspective_idx)
                        self._fire_controlled_destroy_triggers(
                            player_idx, self._cards[cid], perspective_idx
                        )
                        self._fire_on_leave_triggers(player_idx, cid, perspective_idx)
                        self._event_append(f"destroyed {self._cards[cid].name}")
                        destroyed = True
                        break
            if destroyed and (effect.banish_name or "").lower() == "go_again":
                actor.action_points += 1
                self._event_append("gain 1 action point")
            if destroyed and create_after:
                self._create_token(player_idx, create_after)
                self._event_append(f"created {create_after} token")
            if destroyed and effect.optional and effect.raw:
                from .effect_coverage import _parse_destroy_then_clause

                for fe in _parse_destroy_then_clause(effect.raw):
                    self._apply_effect(
                        player_idx, card, fe, combat, perspective_idx
                    )
                pm = re.search(r"attack gets \+(\d+)", (effect.raw or "").lower())
                if pm and combat is not None:
                    self._apply_combat_power_bonus(
                        combat,
                        player_idx,
                        int(pm.group(1)),
                        reason=f"destroy {card.name}: +{pm.group(1)} power",
                    )
            return 0.0
        if effect.kind == "grant_light_block":
            bonus = max(1, effect.amount or 1)
            if (effect.banish_name or "").lower() == "action":
                actor.class_state["ActionBlockBonusThisChain"] = max(
                    actor.class_state.get("ActionBlockBonusThisChain", 0),
                    bonus,
                )
                self._event_append(f"action cards get +{bonus} defense this chain")
            else:
                actor.class_state["LightBlockBonusThisChain"] = max(
                    actor.class_state.get("LightBlockBonusThisChain", 0),
                    bonus,
                )
                self._event_append(f"Light cards get +{bonus} defense this chain")
            return 0.0
        if effect.kind == "transform_equip":
            slot = (effect.banish_name or "").lower()
            if card.id not in actor.equipment:
                actor.equipment.append(card.id)
            for i, cid in enumerate(list(actor.equipment)):
                if cid == card.id:
                    continue
                eq = self._cards[cid]
                if _equipment_slot(eq) == slot:
                    actor.equipment.pop(i)
                    actor.discard.append(cid)
                    self._fire_on_leave_triggers(player_idx, cid, perspective_idx)
                    self._event_append(f"transformed {eq.name} into {card.name}")
                    break
            return 0.0
        if effect.kind == "transform_token":
            source = token_defs.normalize_token_name(effect.banish_name or "ash")
            dest = effect.token_name or "Aether Ashwing"
            if actor.tokens.get(source, 0) <= 0:
                self._event_append(f"no {source} token to transform")
                return 0.0
            actor.tokens[source] -= 1
            if actor.tokens[source] <= 0:
                actor.tokens.pop(source, None)
            self._create_token(player_idx, dest, 1)
            self._event_append(f"transformed {source} into {dest}")
            return 0.0
        if effect.kind == "extra_attack_targets":
            actor.extra_attack_targets += max(1, effect.amount or 1)
            if (effect.banish_name or "").lower() == "crush_next_attack":
                actor.class_state["NextExtraTargetCrushOnly"] = 1
            self._event_append("next attack may target an additional hero")
            return 0.0
        if effect.kind == "counts_as_gold":
            actor.gold += 1
            self._event_append(f"{card.name} counts as Gold (hero gold={actor.gold})")
            return 0.0
        if effect.kind == "play_from_deck_top":
            cls = (effect.banish_name or "item").lower()
            extra = 1
            rm = re.search(r"costs an additional ((?:\{r\})+|\d+)", (effect.raw or card.text).lower())
            if rm:
                txt = rm.group(1)
                extra = txt.count("{r}") if "{r}" in txt else int(re.search(r"\d+", txt).group(0))
            actor.deck_top_play_class = cls
            actor.deck_top_play_extra_cost = extra
            self._event_append(
                f"may play top-of-deck {cls} item (cost 0-1) once per turn as instant (+{extra}r)"
            )
            return 0.0
        if effect.kind == "crowd_cheer":
            actor.cheered_this_turn = True
            self._event_append("crowd cheers you")
            return 0.0
        if effect.kind == "crowd_boo":
            actor.booed_this_turn = True
            self._event_append("crowd boos you")
            return 0.0
        if effect.kind == "play_as_instant":
            actor.play_as_instant = True
            cls_filter = (effect.banish_name or "").strip().lower()
            actor.instant_class_filter = cls_filter
            self._append_may_play_grant(
                player_idx,
                effects.Effect(
                    "grant_may_play",
                    target="hand",
                    banish_name="non-attack",
                    token_name=cls_filter,
                    raw=effect.raw or "play as instant",
                ),
            )
            return 0.0
        if effect.kind == "grant_may_play":
            self._append_may_play_grant(player_idx, effect)
            return 0.0
        if effect.kind == "return_gy_to_hand":
            pattern = (effect.banish_name or "").lower()
            for i, cid in enumerate(actor.discard):
                c = self._cards[cid]
                if pattern and pattern not in c.name.lower():
                    continue
                cid = actor.discard.pop(i)
                actor.hand.append(cid)
                self._event_append(f"returned {c.name} from graveyard to hand")
                return 0.0
            self._event_append("no matching card in graveyard for return")
            return 0.0
        if effect.kind == "grant_draconic":
            actor.class_state["NextChainAttackDraconic"] = 1
            self._event_append("next attack this combat chain is Draconic")
            return 0.0
        if effect.kind == "halve_base_power":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            self._players[target_idx].class_state["HalveFirstAttackBaseNextTurn"] = 1
            self._event_append("opponent's first attack action next turn has halved base power")
            return 0.0
        if effect.kind == "opponent_cost_increase":
            amount = max(1, effect.amount or 1)
            if effect.condition == "defense_reaction":
                opp = self._players[1 - player_idx]
                opp.extra_defense_reaction_cost += amount
                self._event_append(
                    f"opponents' defense reactions cost +{amount} this turn"
                )
            elif effect.condition == "first_attack_next_turn":
                target_idx = 1 - player_idx if effect.target != "self" else player_idx
                self._players[target_idx].class_state["NextFirstAttackExtraCost"] = amount
                self._event_append(
                    f"P{target_idx}'s first attack next turn costs +{amount}"
                )
            elif effect.target == "each_hero":
                for idx in (0, 1):
                    self._players[idx].extra_play_cost += amount
                self._event_append(f"all heroes' cards cost +{amount} this turn")
            else:
                opp = self._players[1 - player_idx]
                opp.extra_play_cost += amount
                self._event_append(f"opponents' cards cost +{amount} this turn")
            return 0.0
        if effect.kind == "put_item_in_arena":
            max_cost = max(1, effect.amount or 1)
            if effect.target == "banished":
                ok = self._put_item_from_banished(player_idx, max_cost)
            else:
                ok = self._put_item_from_hand(player_idx, max_cost)
            if not ok:
                self._event_append("no eligible item to put into arena")
            return 0.0
        if effect.kind == "put_arrow_arsenal":
            if not self._put_arrow_in_arsenal(player_idx):
                self._event_append("no arrow to put in arsenal")
            return 0.0
        if effect.kind == "galvanize":
            destroyed = False
            for i, cid in enumerate(actor.equipment):
                tl = (self._cards[cid].type_line or "").lower()
                if " item" in tl or tl.endswith("item"):
                    cid = actor.equipment.pop(i)
                    actor.discard.append(cid)
                    self._fire_on_leave_triggers(player_idx, cid, perspective_idx)
                    destroyed = True
                    self._event_append(f"galvanize: destroyed {self._cards[cid].name}")
                    break
            if destroyed and combat is not None and combat.blocks:
                idx = len(combat.blocks) - 1
                d_idx, b_cid, val = combat.blocks[idx]
                bonus = max(1, effect.amount or 2)
                combat.blocks[idx] = (d_idx, b_cid, val + bonus)
                self._event_append(f"galvanize: +{bonus} defense on this block")
            return 0.0
        if effect.kind == "modular_equip":
            self._event_append("modular: equipment reassigned (slot unchanged in sim)")
            return 0.0
        if effect.kind == "next_defense_bonus":
            bonus = max(1, effect.amount or 1)
            if (
                combat is not None
                and combat.blocks
                and card.id
                and combat.blocks[-1][1] == card.id
            ):
                last = combat.blocks[-1]
                combat.blocks[-1] = (last[0], last[1], last[2] + bonus)
                self._event_append(f"+{bonus} defense on this block")
                return 0.0
            actor.class_state["NextDefenseBonus"] = (
                actor.class_state.get("NextDefenseBonus", 0) + bonus
            )
            self._event_append(f"next defend +{bonus} defense")
            return 0.0
        if effect.kind == "gain_life":
            if effect.target == "each_hero":
                for idx in (0, 1):
                    self._players[idx].life += max(1, effect.amount or 1)
                    self._event_append(f"P{idx} gained {effect.amount or 1} life")
                return 0.0
            target_idx = player_idx
            if effect.target == "opponent":
                target_idx = 1 - player_idx
            self._players[target_idx].life += max(1, effect.amount or 1)
            self._event_append(f"P{target_idx} gained {effect.amount or 1} life")
            return 0.0
        if effect.kind == "lose_life":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            amount = max(1, effect.amount or 1)
            self._players[target_idx].life -= amount
            self._event_append(f"P{target_idx} lost {amount} life")
            r = float(amount) * 0.01
            return -r if perspective_idx == player_idx else r
        if effect.kind == "gain_action_point":
            rider = (effect.banish_name or "").lower()
            if rider == "roll_d6_half":
                self._pending_die_roll = {
                    "controller": player_idx,
                    "kind": "gain_ap_half",
                }
                if self._pause_for_gambler(player_idx):
                    return 0.0
                self._continue_pending_die_roll()
            elif rider == "hyper_drivers_face_down":
                turned = 0
                for cid in list(actor.banished):
                    if "hyper driver" in self._cards[cid].name.lower():
                        turned += 1
                actor.action_points += turned
                actor.class_state["LastHyperDriversTurned"] = turned
                self._event_append(
                    f"turned {turned} Hyper Driver(s) face-down: gained {turned} action point(s)"
                )
            else:
                actor.action_points += max(1, effect.amount or 1)
                self._event_append(f"gain {effect.amount or 1} action point(s)")
            return 0.0
        if effect.kind == "extra_weapon_attack":
            if effect.condition == "next_attack_on_hit":
                actor.class_state["NextAttackOnHitExtraWeapon"] = 1
                self._event_append("next attack may grant extra weapon attack on hit")
            else:
                actor.class_state["ExtraWeaponAttacks"] = (
                    actor.class_state.get("ExtraWeaponAttacks", 0) + 1
                )
                self._event_append("may attack with weapon an additional time this turn")
            return 0.0
        if effect.kind == "cost_per_token":
            return 0.0
        if effect.kind == "next_ability_cost_reduction":
            actor.class_state["NextAbilityCostReduction"] = max(1, effect.amount or 1)
            self._event_append("next ability costs 1 less")
            return 0.0
        if effect.kind == "lose_all_abilities":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            self._players[target_idx].silenced = True
            self._event_append(f"P{target_idx} loses all abilities until end of next turn")
            return 0.0
        if effect.kind == "heave":
            n = max(1, effect.amount or 1)
            moved = 0
            for _ in range(min(n, len(actor.hand))):
                cid = actor.hand.pop()
                actor.deck.insert(0, cid)
                moved += 1
                self._event_append(f"heaved {self._cards[cid].name} to deck bottom")
            if moved == 0:
                self._event_append("heave: no cards in hand")
            return 0.0
        if effect.kind == "scrap":
            if not actor.hand:
                self._event_append("scrap: no cards in hand")
                return 0.0
            cid = actor.hand.pop()
            actor.deck.insert(0, cid)
            actor.class_state["ScrappedThisPlay"] = 1
            self._event_append(f"scrapped {self._cards[cid].name}")
            return 0.0
        if effect.kind == "additional_pay":
            cost = max(1, effect.amount or 1)
            if actor.resources < cost:
                self._event_append(f"cannot pay {cost} additional cost")
                return 0.0
            actor.resources -= cost
            if card.id:
                actor.class_state[f"AdditionalCostPaid:{card.id}"] = 1
            if (effect.banish_name or "").lower() == "extra_target":
                actor.extra_attack_targets += 1
                self._event_append(f"paid {cost} additional cost: extra attack target")
            else:
                self._event_append(f"paid {cost} additional cost")
            return 0.0
        if effect.kind == "hit_bonus_damage":
            amount = max(1, effect.amount or 1)
            defender_idx = 1 - player_idx
            amount = self._mitigate_damage(defender_idx, amount)
            self._players[defender_idx].life -= amount
            if amount > 0:
                actor.class_state["DamageDealt"] += amount
                self._players[defender_idx].class_state["DamageTaken"] += amount
                self._event_append(f"hit bonus deals {amount} damage")
                r = float(amount) * 0.01
                return r if perspective_idx == player_idx else -r
            return 0.0
        if effect.kind == "grant_hit_bonus":
            actor.class_state["BonusHitDamage"] = (
                actor.class_state.get("BonusHitDamage", 0) + max(1, effect.amount or 1)
            )
            self._event_append(
                f"attacks hit for +{effect.amount or 1} damage this turn"
            )
            return 0.0
        if effect.kind == "hit_rider":
            actor.class_state["PendingHitRider"] = effect.banish_name or ""
            self._event_append("granted on-hit rider")
            return 0.0
        if effect.kind == "freeze":
            target_idx = 1 - player_idx if effect.target == "opponent" else player_idx
            target = self._players[target_idx]
            scope = (effect.banish_name or "").lower()
            if scope == "hero_and_equipment":
                target.class_state["FrozenHero"] = 1
                target.class_state["FrozenEquipment"] = len(target.equipment)
            elif scope == "arsenal" and target.arsenal:
                target.class_state[f"FrozenArsenal:{target.arsenal[0]}"] = 1
            self._event_append(f"freeze ({scope}) on P{target_idx}")
            return 0.0
        if effect.kind == "fusion":
            elements = tuple(
                e.strip() for e in (effect.banish_name or "").split(",") if e.strip()
            )
            if not elements:
                elements = _fusion_elements(card.text)
            if not self._consume_fusion_cards(player_idx, elements):
                self._event_append("fusion failed: missing element cards")
                return 0.0
            if self._play_resume_ctx:
                self._play_resume_ctx["fused"] = True
            if combat is not None:
                combat.fused = True
            cs = actor.class_state
            for element in elements:
                fkey = {
                    "lightning": "NumFusedLightning",
                    "ice": "NumFusedIce",
                    "earth": "NumFusedEarth",
                }.get(element)
                if fkey:
                    cs[fkey] += 1
            self._event_append(f"fused ({', '.join(elements)})")
            return 0.0
        if effect.kind == "create_token_triple":
            for token_name in ("agility", "might", "vigor"):
                self._create_token(player_idx, token_name)
            return 0.0
        if effect.kind == "return_self_hand":
            if card.id in actor.equipment:
                actor.equipment.remove(card.id)
                self._fire_on_leave_triggers(player_idx, card.id, perspective_idx)
            if card.id not in actor.hand:
                actor.hand.append(card.id)
            self._event_append(f"returned {card.name} to hand")
            return 0.0
        if effect.kind == "return_arsenal_hand":
            if actor.arsenal:
                cid = actor.arsenal.pop()
                actor.face_up_arsenal.discard(cid)
                actor.hand.append(cid)
                self._event_append(f"returned {self._cards[cid].name} from arsenal to hand")
            else:
                self._event_append("no card in arsenal to return")
            return 0.0
        if effect.kind == "turn_arsenal_face_up":
            if actor.arsenal:
                cid = actor.arsenal[0]
                actor.face_up_arsenal.add(cid)
                self._event_append(f"turned {self._cards[cid].name} in arsenal face-up")
            else:
                self._event_append("no card in arsenal to turn face-up")
            return 0.0
        if effect.kind == "turn_equipment_face_up":
            turned = False
            for cid in list(actor.equipment):
                if cid not in actor.face_down_permanents:
                    continue
                actor.face_down_permanents.discard(cid)
                self._event_append(f"turned {self._cards[cid].name} face-up")
                turned = True
                break
            if not turned:
                self._event_append("no face-down equipment to turn face-up")
            return 0.0
        if effect.kind == "pitch_deck_top":
            if actor.deck:
                cid = actor.deck.pop()
                card_obj = self._cards[cid]
                actor.pitch_zone.append(cid)
                actor.resources += card_obj.pitch
                self._event_append(
                    f"pitched top of deck ({card_obj.name}, +{card_obj.pitch} resources)"
                )
            else:
                self._event_append("deck empty: nothing to pitch")
            return 0.0
        if effect.kind == "weapon_swing_cost_reduction":
            actor.class_state["NextWeaponSwingCostReduction"] = max(
                1, effect.amount or 1
            )
            self._event_append(
                f"next weapon attack costs {effect.amount or 1} less to activate"
            )
            return 0.0
        if effect.kind == "taunt":
            actor.class_state["TauntActive"] = 1
            if card.id:
                actor.class_state["TauntSource"] = hash(card.id) & 0x7FFFFFFF
            self._event_append("must be chosen as attack target if able")
            return 0.0
        if effect.kind == "block_opponent_hit_effects":
            actor.class_state["BlockOpponentHitEffectsTurn"] = 1
            self._event_append("opponents' attack hit effects won't trigger this turn")
            return 0.0
        if effect.kind == "block_gold_gain":
            for idx in (0, 1):
                self._players[idx].class_state["BlockGoldGainTurn"] = 1
            self._event_append("heroes can't gain {g} this turn")
            return 0.0
        if effect.kind == "lose_phantasm":
            actor.class_state["LosePhantasmNextIllusionistAttack"] = 1
            self._event_append("next illusionist attack loses phantasm")
            return 0.0
        if effect.kind == "prevention_reduction":
            actor.class_state["PreventionReductionTurn"] = max(1, effect.amount or 1)
            self._event_append("next prevention effect prevents 1 less damage")
            return 0.0
        if effect.kind == "chain_defend":
            self._apply_chain_defend(player_idx, card, effect, combat)
            return 0.0
        if effect.kind == "name_card":
            actor.named_card = actor.named_card or "named"
            self._event_append("named a card")
            return 0.0
        if effect.kind == "banish_hand_play":
            link_cap = self._draconic_chain_links()
            pick: Optional[str] = None
            for cid in actor.hand:
                c = self._cards[cid]
                if "attack_action" not in c.card_types:
                    continue
                if c.cost >= link_cap:
                    continue
                pick = cid
                break
            if pick is None:
                self._event_append("no eligible attack in hand to banish")
                return 0.0
            actor.hand.remove(pick)
            actor.banished.append(pick)
            actor.class_state["CardsBanishedThisTurn"] += 1
            if effect.amount and effect.amount > 0:
                actor.class_state[f"BanishedPower:{pick}"] = effect.amount
            if effect.go_again:
                actor.class_state[f"BanishedGoAgain:{pick}"] = 1
            if effect.playable_banished:
                actor.playable_banished.add(pick)
            self._event_append(
                f"banished {self._cards[pick].name} from hand"
                + (f" (+{effect.amount} power)" if effect.amount else "")
            )
            return 0.0
        if effect.kind == "banish_self_play":
            if effect.condition and not self._effect_condition_met(
                player_idx, effect.condition, card, combat
            ):
                return 0.0
            cid = card.id
            if cid in actor.discard:
                actor.discard.remove(cid)
                actor.banished.append(cid)
            actor.playable_banished.add(cid)
            self._event_append(f"banished {card.name}; may play it this turn")
            return 0.0
        if effect.kind == "block_arcane_prevention":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            self._players[target_idx].class_state["BlockArcaneFromSource"] = player_idx
            self._event_append("hero can't prevent your arcane damage this turn")
            return 0.0
        if effect.kind == "reveal_named_hand":
            card_pattern = (effect.banish_name or "Crouching Tiger").split(":", 1)[0].lower()
            revealed = sum(
                1
                for cid in actor.hand
                if card_pattern in self._cards[cid].name.lower()
            )
            if revealed <= 0:
                self._event_append(f"no {card_pattern} cards revealed")
                return 0.0
            self._event_append(f"revealed {revealed} {card_pattern} card(s)")
            if combat is not None:
                if revealed >= 1:
                    self._grant_go_again(player_idx, combat, this_card=True)
                if revealed >= 2:
                    self._apply_combat_power_bonus(
                        combat,
                        player_idx,
                        1,
                        reason=f"+1 power ({revealed} revealed)",
                    )
                if revealed >= 3:
                    self._draw_card(player_idx, from_action=True)
            return 0.0
        if effect.kind == "transform_hero":
            hero_name = effect.banish_name or ""
            for cid in list(actor.banished):
                actor.face_down_banished.add(cid)
            matched = False
            for hero in self._heroes.values():
                if _card_name_key(hero.name) == _card_name_key(hero_name):
                    actor.hero = hero
                    matched = True
                    self._event_append(f"transformed into {hero.name}")
                    break
            if not matched:
                self._event_append(f"could not transform into {hero_name}")
            return 0.0
        if effect.kind == "grade_increase":
            actor.class_state["RevealGradeBonus"] = max(1, effect.amount or 1)
            self._event_append("next revealed card has grade increased by 1")
            return 0.0
        if effect.kind == "return_arena_tapped":
            cid = card.id
            if cid in actor.banished:
                actor.banished.remove(cid)
            elif cid in actor.discard:
                actor.discard.remove(cid)
            if cid and cid not in actor.equipment:
                actor.equipment.append(cid)
            if cid:
                actor.tapped_permanents.add(cid)
                token = (effect.token_name or "steam").lower()
                self._add_permanent_counter(player_idx, cid, token, 1)
                self._event_append(
                    f"returned {card.name} to arena tapped with {token} counter"
                )
            return 0.0
        if effect.kind == "play_restriction":
            self._play_restriction_kind = effect.banish_name or "weapon_attack_only"
            self._play_restriction_clear_at_turn = self._turn + 2
            self._event_append(
                "only weapon and attack actions may be played or activated until "
                "your next turn"
            )
            return 0.0
        if effect.kind == "pitch_restriction":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            target = self._players[target_idx]
            rider = (effect.banish_name or "").lower()
            if rider == "no_cost_zero":
                target.class_state["BlockZeroCostUntilTurn"] = self._turn + 1
                self._event_append(
                    f"P{target_idx} can't pitch or play cards with base cost 0 until "
                    "end of their next turn"
                )
            return 0.0
        if effect.kind == "block_pitch_color":
            target_idx = 1 - player_idx if effect.target != "self" else player_idx
            target = self._players[target_idx]
            colors = [(1, "red"), (2, "yellow"), (3, "blue")]
            if player_idx == 0 and not self._self_play:
                pick = self._rng.randrange(3)
            elif player_idx == 0:
                pick = 0
            else:
                pick = self._rng.randrange(3)
            pitch_val, color_name = colors[pick]
            target.blocked_pitch_values.add(pitch_val)
            target.class_state["BlockPitchColorUntilTurn"] = self._turn + 1
            self._event_append(
                f"P{target_idx} can't pitch {color_name} cards until start of your next turn"
            )
            return 0.0
        if effect.kind == "banish_gy_variable":
            pattern = (effect.banish_name or "item").lower()
            count = 0
            for i in range(len(actor.discard) - 1, -1, -1):
                cid = actor.discard[i]
                card_obj = self._cards[cid]
                hay = f"{card_obj.name} {(card_obj.type_line or '')} {' '.join(card_obj.card_types)}".lower()
                if pattern == "item" and "item" not in hay and "item" not in card_obj.card_types:
                    continue
                actor.discard.pop(i)
                actor.banished.append(cid)
                count += 1
            actor.class_state["LastVariableBanishCount"] = count
            actor.class_state["CardsBanishedThisTurn"] += count
            self._event_append(f"banished {count} item(s) from graveyard as additional cost")
            return 0.0
        if effect.kind == "random_banished_pick":
            type_filter = (effect.banish_name or "").lower()
            need = max(1, effect.amount or 3)
            candidates: list[str] = []
            seen: set[str] = set()
            for cid in actor.banished:
                card_obj = self._cards[cid]
                if type_filter == "action" and "action" not in card_obj.card_types:
                    continue
                key = card_obj.name.lower()
                if key in seen:
                    continue
                seen.add(key)
                candidates.append(cid)
            pool = candidates[:need]
            if len(pool) < need:
                self._event_append(
                    f"need {need} distinct banished action cards, found {len(pool)}"
                )
                return 0.0
            pick = self._rng.choice(pool)
            actor.playable_banished.add(pick)
            self._event_append(
                f"randomly chose {self._cards[pick].name} from banished (may play this turn)"
            )
            return 0.0
        if effect.kind == "turn_banished_face":
            rider = (effect.banish_name or "").lower()
            if rider == "face_up":
                if actor.banished:
                    cid = actor.banished[-1]
                    actor.face_down_banished.discard(cid)
                    self._event_append(
                        f"turned {self._cards[cid].name} face-up in banished zone"
                    )
                return 0.0
            if rider == "face_down:opponent_banished":
                target_idx = 1 - player_idx if effect.target != "self" else player_idx
                target = self._players[target_idx]
                if target.banished:
                    cid = target.banished[-1]
                    target.face_down_banished.add(cid)
                    self._event_append(
                        f"turned {self._cards[cid].name} face-down in P{target_idx} banished zone"
                    )
                return 0.0
            if rider in ("face_down:opponent_gy_yellow_gold", "face_down:any_gy_yellow_gold"):
                zones: list[tuple[int, list[str], str]] = []
                if rider == "face_down:opponent_gy_yellow_gold":
                    opp = 1 - player_idx
                    zones.append((opp, self._players[opp].discard, "discard"))
                else:
                    for idx in (0, 1):
                        zones.append((idx, self._players[idx].discard, "discard"))
                for idx, zone, _ in zones:
                    if not zone:
                        continue
                    cid = zone[-1]
                    card = self._cards[cid]
                    self._players[idx].face_down_discard.add(cid)
                    self._event_append(
                        f"turned {card.name} face-down in P{idx} graveyard"
                    )
                    if card.pitch == 2:
                        self._create_token(player_idx, "gold", 1)
                        self._event_append("created Gold token (yellow card turned face-down)")
                    return 0.0
                return 0.0
            if rider == "face_down:any_banished":
                for idx in (0, 1):
                    target = self._players[idx]
                    if target.banished:
                        cid = target.banished[-1]
                        target.face_down_banished.add(cid)
                        self._event_append(
                            f"turned {self._cards[cid].name} face-down in P{idx} banished zone"
                        )
                        return 0.0
                return 0.0
            if rider.startswith("face_down"):
                count = len(actor.soul) if ":variable" in rider else max(1, effect.amount or 1)
                turned = 0
                for cid in list(actor.banished):
                    if turned >= count:
                        break
                    actor.face_down_banished.add(cid)
                    turned += 1
                self._event_append(f"turned {turned} banished card(s) face-down")
            return 0.0
        if effect.kind == "damage_redirect":
            rider = (effect.banish_name or "").lower()
            if rider == "yoji_shield":
                actor.redirect_shield = {
                    "kind": "yoji",
                    "prevent": max(1, effect.amount or 1),
                }
                self._event_append(
                    "next damage to another hero will hit Yoji instead (prevent 1)"
                )
            elif rider == "weapon_reflect":
                actor.redirect_shield = {"kind": "weapon_reflect"}
                self._event_append(
                    "next weapon damage at X or less will reflect to its controller"
                )
            return 0.0
        return 0.0

    def _fire_on_leave_triggers(self, player_idx: int, card_id: str, perspective_idx: int = 0) -> None:
        """Fire on-leave triggers when a permanent leaves the arena."""
        card = self._cards[card_id]
        actor = self._players[player_idx]
        for trig in effects.parse_triggers(card.text):
            if trig.when != "on_leave":
                continue
            eff = trig.effect
            if eff.condition == "once_per_turn":
                if actor.class_state.get(f"OncePerTurn:{card.id}"):
                    continue
            if eff.optional:
                if self._optional_available(player_idx, eff):
                    self._pending_optionals.append(
                        {
                            "player": player_idx,
                            "card_id": card.id,
                            "effect": eff,
                            "perspective": perspective_idx,
                        }
                    )
                continue
            self._apply_effect(player_idx, card, eff, None, perspective_idx)
            if eff.condition == "once_per_turn":
                self._mark_once_per_turn_used(player_idx, card)

    def _check_no_frost_destroy(self, player_idx: int, card_id: str) -> None:
        card = self._cards.get(card_id)
        if card is None or "when it has no frost counters, destroy it" not in (card.text or "").lower():
            return
        if self._permanent_counters(player_idx, card_id).get("frost", 0) > 0:
            return
        actor = self._players[player_idx]
        if card_id in actor.equipment:
            actor.equipment.remove(card_id)
            actor.discard.append(card_id)
            self._fire_on_destroy_triggers(player_idx, card_id, player_idx)
            self._fire_on_leave_triggers(player_idx, card_id, player_idx)
            self._event_append(f"destroyed {card.name} (no frost counters)")

    def _fire_on_destroy_triggers(
        self, player_idx: int, card_id: str, perspective_idx: int = 0
    ) -> None:
        card = self._cards[card_id]
        for trig in effects.parse_triggers(card.text):
            if trig.when != "on_destroy":
                continue
            eff = trig.effect
            if eff.optional:
                if self._optional_available(player_idx, eff):
                    self._pending_optionals.append(
                        {
                            "player": player_idx,
                            "card_id": card.id,
                            "effect": eff,
                            "perspective": perspective_idx,
                        }
                    )
                continue
            self._apply_effect(player_idx, card, eff, None, perspective_idx)

    def _fire_controlled_destroy_triggers(
        self,
        owner_idx: int,
        destroyed: Card,
        perspective_idx: int = 0,
    ) -> None:
        tl = (destroyed.type_line or "").lower()
        if " aura" not in tl and not tl.endswith("aura") and "attack" not in tl:
            return
        owner = self._players[owner_idx]
        for cid in owner.equipment:
            if cid == destroyed.id:
                continue
            card = self._cards[cid]
            for trig in effects.parse_triggers(card.text):
                if trig.when != "on_controlled_destroy":
                    continue
                if (
                    trig.effect.kind == "put_soul"
                    and (trig.effect.banish_name or "").lower() == "destroyed_light"
                ):
                    tl = (destroyed.type_line or "").lower()
                    if (destroyed.talent or "").lower() == "light" and "token" not in tl:
                        if destroyed.id in owner.discard:
                            owner.discard.remove(destroyed.id)
                        owner.soul.append(destroyed.id)
                        self._event_append(f"{destroyed.name} put into soul")
                    continue
                self._apply_effect(owner_idx, card, trig.effect, None, perspective_idx)

    def _run_triggers(
        self,
        player_idx: int,
        card: Card,
        when: str,
        combat: Optional[CombatState],
        perspective_idx: int,
        fused: bool,
    ) -> float:
        reward = 0.0
        actor = self._players[player_idx]
        for trig in effects.parse_triggers(card.text):
            if trig.when != when:
                continue
            # Don't fire a fused-gated effect when the card wasn't fused.
            if when != "when_fused" and not fused and "fused" in trig.raw.lower():
                continue
            eff = trig.effect
            if eff.condition == "once_per_turn" and actor.class_state.get(f"OncePerTurn:{card.id}"):
                continue
            # Optional ("you may") effects become a player decision instead of
            # auto-resolving -- queue them if they could do something now.
            if eff.implemented and eff.optional:
                if self._optional_available(player_idx, eff):
                    self._pending_optionals.append(
                        {"player": player_idx, "card_id": card.id, "effect": eff, "perspective": perspective_idx}
                    )
                continue
            reward += self._apply_effect(player_idx, card, eff, combat, perspective_idx)
            if self._phase == "choice":
                if when == "on_hit" and self._pending_combat:
                    self._choice_ctx["resume"] = "after_hit_combat"
                elif when == "on_attack" and combat is not None:
                    self._choice_ctx["resume"] = "after_attack"
                elif when == "on_play":
                    self._choice_ctx["resume"] = "after_play_direct"
                return reward
            if eff.condition == "once_per_turn":
                self._mark_once_per_turn_used(player_idx, card)
        return reward

    def _optional_available(self, player_idx: int, effect: "effects.Effect") -> bool:
        """Whether an optional effect could actually do something if taken."""
        if effect.kind == "banish_combo":
            target = (effect.banish_name or "").lower()
            return any(
                self._card_matches_banish_combo(self._cards[c], target)
                for c in self._players[player_idx].discard
            )
        if effect.kind in ("reload", "stash_hand"):
            actor = self._players[player_idx]
            return not actor.arsenal and bool(actor.hand)
        if effect.kind == "boost":
            return bool(self._players[player_idx].deck)
        if effect.kind == "put_item_in_arena":
            max_cost = max(1, effect.amount or 1)
            actor = self._players[player_idx]
            if effect.target == "banished":
                return any(
                    self._is_arena_permanent(self._cards[c])
                    and self._cards[c].cost <= max_cost
                    for c in actor.banished
                )
            return any(
                self._is_arena_permanent(self._cards[cid])
                and self._cards[cid].cost <= max_cost
                for cid in actor.hand
            )
        if effect.kind == "put_arrow_arsenal":
            actor = self._players[player_idx]
            return not actor.arsenal and any(
                "arrow" in (self._cards[c].type_line or "").lower()
                or "arrow" in self._cards[c].name.lower()
                for c in actor.hand
            )
        if effect.kind == "heave":
            return len(self._players[player_idx].hand) >= max(1, effect.amount or 1)
        if effect.kind == "scrap":
            return bool(self._players[player_idx].hand)
        if effect.kind == "additional_pay":
            return self._players[player_idx].resources >= max(1, effect.amount or 1)
        if effect.kind == "dagger_damage":
            daggers = self._dagger_ids_controlled(player_idx)
            if "not_on_chain" in (effect.banish_name or "").lower():
                combat = self._pending_combat
                if combat is not None:
                    on_chain = self._daggers_on_chain(combat)
                    daggers = [d for d in daggers if d not in on_chain]
            return bool(daggers)
        if effect.kind == "pitch_pay":
            cost = max(1, effect.amount or 1)
            return self._can_pay_pitch_cost(
                player_idx, cost, variable=self._pitch_pay_is_variable(effect)
            )
        if effect.kind == "retrieve_gy":
            actor = self._players[player_idx]
            pattern = (effect.banish_name or "").lower()
            has_match = any(
                pattern in f"{self._cards[cid].name} {(self._cards[cid].type_line or '')}".lower()
                for cid in actor.discard
            )
            return has_match and any(self._cards[cid].pitch > 0 for cid in actor.hand)
        if effect.kind == "search" and effect.condition == "revealed_attack_reaction":
            opp = self._players[1 - player_idx]
            has_attack_reaction = any(
                "attack_reaction" in self._cards[cid].card_types
                for cid in (opp.revealed_hand or opp.hand)
            )
            actor = self._players[player_idx]
            has_defense = any(
                "defense_reaction" in self._cards[cid].card_types for cid in actor.deck
            )
            return has_attack_reaction and has_defense
        if effect.kind == "fusion":
            elements = tuple(
                e.strip() for e in (effect.banish_name or "").split(",") if e.strip()
            )
            return bool(elements) and self._can_fuse(player_idx, elements)
        if effect.kind == "enable_gy_play":
            actor = self._players[player_idx]
            pat = (effect.banish_name or "this").strip().lower()
            if pat in ("", "this"):
                return True
            return any(
                self._gy_play_pattern_match(self._cards[cid], pat) for cid in actor.discard
            )
        if effect.kind == "put_soul":
            actor = self._players[player_idx]
            color_filter = (effect.banish_name or "").lower()
            if color_filter in ("red", "yellow", "blue"):
                pitch_map = {"red": 1, "yellow": 2, "blue": 3}
                target_pitch = pitch_map[color_filter]
                return any(self._cards[cid].pitch == target_pitch for cid in actor.hand)
            return bool(actor.hand)
        if effect.kind == "remove_counter":
            token = (effect.token_name or "").lower()
            return any(
                self._permanent_counters(player_idx, cid).get(token, 0) > 0
                for cid in self._players[player_idx].equipment
            )
        if effect.kind == "banish_gy_variable":
            actor = self._players[player_idx]
            pattern = (effect.banish_name or "item").lower()
            return any(
                pattern in f"{self._cards[cid].name} {(self._cards[cid].type_line or '')}".lower()
                or pattern in self._cards[cid].card_types
                for cid in actor.discard
            )
        if effect.kind == "put_bottom" and (effect.banish_name or "").startswith("yellow_any_gy"):
            return any(
                self._cards[cid].pitch == 2
                for p in self._players
                for cid in p.discard
            )
        if effect.kind == "turn_banished_face":
            rider = (effect.banish_name or "").lower()
            if rider == "face_down:opponent_banished":
                return bool(self._players[1 - player_idx].banished)
            if rider == "face_down:opponent_gy_yellow_gold":
                return bool(self._players[1 - player_idx].discard)
            if rider == "face_down:any_gy_yellow_gold":
                return any(p.discard for p in self._players)
            if rider == "face_down:any_banished":
                return any(p.banished for p in self._players)
            return bool(self._players[player_idx].banished)
        return True

    def _do_optional(self, accept: bool) -> float:
        """Resolve the next pending optional decision (use it or decline)."""
        if not self._pending_optionals:
            self._resume_after_optional()
            return 0.0
        opt = self._pending_optionals.pop(0)
        reward = 0.0
        card = self._cards[opt["card_id"]]
        if accept:
            if opt["effect"].kind == "pitch_pay":
                reward = self._begin_pitch_pay(
                    opt["player"],
                    card,
                    opt["effect"],
                    opt["perspective"],
                    optional_resume=self._optional_resume,
                )
            else:
                reward = self._apply_effect(
                    opt["player"], card, opt["effect"], self._pending_combat, opt["perspective"]
                )
        else:
            self._event_append(f"declined {card.name} optional")
        if not self._pending_optionals and not self._pending_pitch_pay:
            self._resume_after_optional()
        return reward

    def _finish_attack_triggers(
        self,
        player_idx: int,
        card: Card,
        perspective_idx: int,
        fused: bool,
    ) -> float:
        """Run on-play / on-attack triggers after optional play costs."""
        combat = self._pending_combat
        reward = self._run_triggers(player_idx, card, "on_play", combat, perspective_idx, fused)
        if fused:
            reward += self._run_triggers(player_idx, card, "when_fused", combat, perspective_idx, fused)
        reward += self._run_triggers(player_idx, card, "on_attack", combat, perspective_idx, fused)
        if self._phase == "choice":
            return reward
        if "song" in (card.type_line or "").lower():
            reward += self._fire_equipment_triggers(player_idx, "whenever_song", perspective_idx)
        self._queue_play_keywords(player_idx, card, perspective_idx)
        if self._pending_optionals:
            self._optional_resume = "defense"
            self._phase = "optional"
            self._active_player = player_idx
        else:
            self._enter_defense()
        return reward

    def _resume_after_optional(self) -> None:
        tag, self._optional_resume = self._optional_resume, None
        if tag == "post_play_costs":
            ctx = self._play_resume_ctx
            self._play_resume_ctx = {}
            card = self._cards[ctx["card_id"]]
            fused = ctx.get("fused", False)
            if self._pending_combat is not None:
                fused = fused or self._pending_combat.fused
                self._finish_attack_triggers(ctx["player"], card, ctx["perspective"], fused)
            else:
                ctx_fused = ctx.get("fused", False)
                self._resolve_direct_effects(
                    ctx["player"],
                    card,
                    ctx["damage"],
                    ctx["arcane"],
                    ctx["go_again"],
                    ctx["dominate"],
                    ctx_fused,
                    ctx.get("elements", ()),
                    ctx["perspective"],
                )
        elif tag == "defense":
            self._enter_defense()
        elif tag == "advance":
            self._finish_combat_advance()
        elif tag == "direct_finish":
            ctx = self._optional_post_ctx
            self._optional_post_ctx = {}
            player = ctx.get("player", self._active_player)
            if ctx.get("go_again"):
                self._grant_go_again(player, None, this_card=False)
            if not self._is_terminal():
                if self._players[player].action_points > 0:
                    self._phase = "action"
                    self._active_player = player
                else:
                    self._begin_arsenal_step(player)
        elif tag == "direct_arcane":
            dctx = self._optional_post_ctx.pop("direct", {})
            self._optional_post_ctx = {}
            card = self._cards[dctx["card_id"]]
            self._resolve_direct_effects(
                dctx["player"],
                card,
                dctx["damage"],
                dctx["arcane"],
                dctx["go_again"],
                dctx["dominate"],
                dctx["fused"],
                dctx.get("elements", ()),
                dctx["perspective"],
                skip_arcane_triggers=True,
            )
        elif tag == "die_roll":
            self._continue_pending_die_roll()
            if self._pending_combat is not None:
                self._enter_defense()
            else:
                self._phase = "action"
        else:
            self._phase = "action"

    def _finish_combat_advance(self) -> None:
        ctx = self._optional_ctx
        self._optional_ctx = {}
        attacker = self._players[ctx["attacker"]]
        if ctx.get("go_again"):
            attacker.action_points += 1
        if not self._is_terminal():
            if attacker.action_points > 0:
                self._phase = "action"
                self._active_player = ctx["attacker"]
            else:
                self._begin_arsenal_step(ctx["attacker"])

    def _do_play_card(
        self,
        player_idx: int,
        hand_idx: int,
        perspective_idx: int = 0,
        *,
        from_arsenal: bool = False,
    ) -> float:
        actor = self._players[player_idx]
        if from_arsenal:
            if not actor.arsenal:
                self._last_event = "Arsenal is empty"
                return -0.05
            card = self._cards[actor.arsenal[0]]
            hand_idx = -1
        else:
            if hand_idx < 0 or hand_idx >= len(actor.hand):
                self._last_event = "No such card"
                return -0.05
            card = self._cards[actor.hand[hand_idx]]

        is_attack = "attack_action" in card.card_types
        is_utility = "utility_action" in card.card_types
        if not (is_attack or is_utility):
            self._last_event = f"{card.name} is not an action you can play"
            return -0.05
        if actor.action_points <= 0:
            self._last_event = "No action points remaining"
            return -0.05
        effective_cost = self._effective_card_cost(player_idx, card)
        if actor.resources < effective_cost:
            self._last_event = f"Need {effective_cost} resources (pitch cards first)"
            return -0.05
        reason = self._play_blocked_reason(
            player_idx, hand_idx, card, from_arsenal=from_arsenal
        )
        if reason:
            self._last_event = reason
            return -0.05

        keywords = set(card.keywords)
        elements, can_fuse = self._fusion_state(player_idx, hand_idx, card)
        fused = False
        go_again = self._go_again_for_play(player_idx, card, is_utility)
        dominate = "dominate" in keywords
        attack_base = self._effective_attack_base_power(player_idx, card) if is_attack else card.power
        damage, arcane = _parse_action_damage(card.text, attack_base, is_attack)

        actor.resources -= effective_cost
        self._consume_cost_reduction(player_idx, card, effective_cost)
        actor.action_points -= 1
        actor.class_state["ScrappedThisPlay"] = 0
        if from_arsenal:
            played_cid = actor.arsenal.pop(0)
            self._mark_played_from_arsenal(player_idx, played_cid, from_arsenal=True)
        else:
            actor.hand.pop(hand_idx)

        play_zone = " from arsenal" if from_arsenal else ""

        # Physical attacks go through the combat chain (blocks + reactions).
        # Arcane damage and non-attack actions cannot be blocked normally, so
        # they resolve immediately.
        if is_attack and not arcane:
            combat = CombatState(
                attacker=player_idx,
                defender=1 - player_idx,
                attack_card_id=card.id,
                attack_power=damage,
                blocks=[],
                go_again=go_again,
                dominate=dominate,
                fused=fused,
            )
            self._apply_defender_targeting_penalty(combat)
            self._pending_combat = combat
            suffix = self._play_suffix(fused, elements, go_again)
            self._last_event = f"P{player_idx} attacks{play_zone} with {card.name} ({damage}){suffix}"
            self._record_opponent_attack(
                player_idx,
                attack_name=card.name,
                attack_power=damage,
            )
            # Inline play bonuses (e.g. "if you've played another red card, go again").
            go_again, dominate = self._apply_play_modifiers(
                player_idx, card, combat, go_again=go_again, dominate=dominate
            )
            combat.go_again = go_again
            combat.dominate = dominate
            self._apply_kayo_power6(player_idx, card, combat)
            self._mark_attack_started(player_idx)
            if self._phase == "optional":
                self._play_resume_ctx = {
                    "player": player_idx,
                    "card_id": card.id,
                    "perspective": perspective_idx,
                    "fused": False,
                    "elements": elements,
                }
                self._optional_resume = "post_play_costs"
                self._active_player = player_idx
                return 0.0
            self._record_play_counters(
                player_idx,
                card,
                is_attack,
                is_utility,
                fused,
                elements[0] if elements else None,
                from_hand=not from_arsenal,
            )
            # Consume a pending "next attack gets +power" buff (e.g. Nimblism).
            self._consume_pending_next_attack_power(player_idx, card, combat)
            if can_fuse:
                self._queue_fusion_optional(player_idx, card, perspective_idx, elements)
            self._queue_play_costs(player_idx, card, perspective_idx)
            if self._pending_optionals:
                self._play_resume_ctx = {
                    "player": player_idx,
                    "card_id": card.id,
                    "perspective": perspective_idx,
                    "fused": False,
                    "elements": elements,
                }
                self._optional_resume = "post_play_costs"
                self._phase = "optional"
                self._active_player = player_idx
                return 0.0
            trig_reward = self._finish_attack_triggers(player_idx, card, perspective_idx, fused)
            return trig_reward

        return self._resolve_direct(
            player_idx, card, damage, arcane, go_again, dominate, fused, elements, perspective_idx
        )

    def _do_play_arsenal(self, player_idx: int, perspective_idx: int = 0) -> float:
        return self._do_play_card(player_idx, 0, perspective_idx, from_arsenal=True)

    def _do_play_banished(self, player_idx: int, banished_idx: int, perspective_idx: int = 0) -> float:
        actor = self._players[player_idx]
        if banished_idx < 0 or banished_idx >= len(actor.banished):
            self._last_event = "No such banished card"
            return -0.05
        card_id = actor.banished[banished_idx]
        if not self._can_play_from_banished(player_idx, card_id):
            self._last_event = "That banished card cannot be played now"
            return -0.05
        card = self._cards[card_id]
        is_attack = "attack_action" in card.card_types
        is_utility = "utility_action" in card.card_types
        if not (is_attack or is_utility):
            self._last_event = f"{card.name} is not an action you can play"
            return -0.05
        if actor.action_points <= 0:
            self._last_event = "No action points remaining"
            return -0.05
        effective_cost = self._effective_card_cost(player_idx, card)
        if actor.resources < effective_cost:
            self._last_event = f"Need {effective_cost} resources (pitch cards first)"
            return -0.05

        actor.banished.pop(banished_idx)
        actor.playable_banished.discard(card_id)

        keywords = set(card.keywords)
        go_again = self._go_again_for_play(player_idx, card, is_utility)
        dominate = "dominate" in keywords
        fused = False
        element = None
        attack_base = self._effective_attack_base_power(player_idx, card) if is_attack else card.power
        damage, arcane = _parse_action_damage(card.text, attack_base, is_attack)

        actor.resources -= effective_cost
        self._consume_cost_reduction(player_idx, card, effective_cost)
        actor.action_points -= 1
        actor.class_state["ScrappedThisPlay"] = 0
        self._record_play_counters(
            player_idx, card, is_attack, is_utility, fused, element, from_hand=False
        )

        if is_attack and not arcane:
            combat = CombatState(
                attacker=player_idx,
                defender=1 - player_idx,
                attack_card_id=card.id,
                attack_power=damage,
                blocks=[],
                go_again=go_again,
                dominate=dominate,
                fused=fused,
            )
            self._pending_combat = combat
            self._last_event = f"P{player_idx} attacks from banish with {card.name} ({damage})"
            go_again, dominate = self._apply_play_modifiers(
                player_idx, card, combat, go_again=go_again, dominate=dominate
            )
            combat.go_again = go_again
            combat.dominate = dominate
            self._mark_attack_started(player_idx)
            self._consume_pending_next_attack_power(player_idx, card, combat)
            self._queue_play_costs(player_idx, card, perspective_idx)
            if self._pending_optionals:
                self._play_resume_ctx = {
                    "player": player_idx,
                    "card_id": card.id,
                    "perspective": perspective_idx,
                    "fused": fused,
                }
                self._optional_resume = "post_play_costs"
                self._phase = "optional"
                self._active_player = player_idx
                return 0.0
            return self._finish_attack_triggers(player_idx, card, perspective_idx, fused)

        return self._resolve_direct(
            player_idx, card, damage, arcane, go_again, dominate, fused, (), perspective_idx
        )

    def _do_play_graveyard(self, player_idx: int, gy_idx: int, perspective_idx: int = 0) -> float:
        actor = self._players[player_idx]
        if gy_idx < 0 or gy_idx >= len(actor.discard):
            self._last_event = "No such graveyard card"
            return -0.05
        card_id = actor.discard[gy_idx]
        if not self._can_play_from_graveyard(player_idx, card_id):
            self._last_event = "That graveyard card cannot be played now"
            return -0.05
        card = self._cards[card_id]
        is_attack = "attack_action" in card.card_types
        is_utility = "utility_action" in card.card_types
        if not (is_attack or is_utility):
            self._last_event = f"{card.name} is not an action you can play"
            return -0.05
        if actor.action_points <= 0:
            self._last_event = "No action points remaining"
            return -0.05
        effective_cost = self._effective_card_cost(player_idx, card)
        if actor.resources < effective_cost:
            self._last_event = f"Need {effective_cost} resources (pitch cards first)"
            return -0.05

        actor.discard.pop(gy_idx)
        actor.playable_graveyard.discard(card_id)

        keywords = set(card.keywords)
        go_again = self._go_again_for_play(player_idx, card, is_utility)
        dominate = "dominate" in keywords
        fused = False
        element = None
        attack_base = self._effective_attack_base_power(player_idx, card) if is_attack else card.power
        damage, arcane = _parse_action_damage(card.text, attack_base, is_attack)

        actor.resources -= effective_cost
        self._consume_cost_reduction(player_idx, card, effective_cost)
        actor.action_points -= 1
        actor.class_state["ScrappedThisPlay"] = 0
        self._record_play_counters(
            player_idx, card, is_attack, is_utility, fused, element, from_hand=False
        )

        if is_attack and not arcane:
            combat = CombatState(
                attacker=player_idx,
                defender=1 - player_idx,
                attack_card_id=card.id,
                attack_power=damage,
                blocks=[],
                go_again=go_again,
                dominate=dominate,
                fused=fused,
            )
            self._pending_combat = combat
            self._last_event = f"P{player_idx} attacks from graveyard with {card.name} ({damage})"
            go_again, dominate = self._apply_play_modifiers(
                player_idx, card, combat, go_again=go_again, dominate=dominate
            )
            combat.go_again = go_again
            combat.dominate = dominate
            self._mark_attack_started(player_idx)
            self._consume_pending_next_attack_power(player_idx, card, combat)
            self._queue_play_costs(player_idx, card, perspective_idx)
            if self._pending_optionals:
                self._play_resume_ctx = {
                    "player": player_idx,
                    "card_id": card.id,
                    "perspective": perspective_idx,
                    "fused": fused,
                }
                self._optional_resume = "post_play_costs"
                self._phase = "optional"
                self._active_player = player_idx
                return 0.0
            return self._finish_attack_triggers(player_idx, card, perspective_idx, fused)

        return self._resolve_direct(
            player_idx, card, damage, arcane, go_again, dominate, fused, (), perspective_idx
        )

    def _resolve_direct(
        self,
        player_idx: int,
        card: Card,
        damage: int,
        arcane: bool,
        go_again: bool,
        dominate: bool,
        fused: bool,
        elements: tuple[str, ...],
        perspective_idx: int,
    ) -> float:
        """Resolve a non-blockable play (arcane bolt or non-attack action)."""
        go_again, dominate = self._apply_play_modifiers(
            player_idx, card, None, go_again=go_again, dominate=dominate
        )
        self._record_play_counters(
            player_idx,
            card,
            "attack_action" in card.card_types,
            "utility_action" in card.card_types,
            fused,
            elements[0] if elements else None,
        )
        can_fuse = bool(elements) and self._can_fuse(player_idx, elements)
        if can_fuse:
            self._queue_fusion_optional(player_idx, card, perspective_idx, elements)
        self._queue_play_costs(player_idx, card, perspective_idx)
        if self._pending_optionals:
            self._play_resume_ctx = {
                "player": player_idx,
                "card_id": card.id,
                "damage": damage,
                "arcane": arcane,
                "go_again": go_again,
                "dominate": dominate,
                "fused": False,
                "elements": elements,
                "perspective": perspective_idx,
            }
            self._optional_resume = "post_play_costs"
            self._phase = "optional"
            self._active_player = player_idx
            return 0.0
        return self._resolve_direct_effects(
            player_idx,
            card,
            damage,
            arcane,
            go_again,
            dominate,
            fused,
            elements,
            perspective_idx,
        )

    def _resolve_direct_effects(
        self,
        player_idx: int,
        card: Card,
        damage: int,
        arcane: bool,
        go_again: bool,
        dominate: bool,
        fused: bool,
        elements: tuple[str, ...],
        perspective_idx: int,
        *,
        skip_arcane_triggers: bool = False,
    ) -> float:
        """Apply direct-play resolution after optional play costs."""
        actor = self._players[player_idx]
        defender = self._players[1 - player_idx]
        if arcane and not skip_arcane_triggers:
            self._fire_equipment_triggers(player_idx, "whenever_arcane_play", perspective_idx)
            if self._pending_optionals:
                self._optional_post_ctx = {
                    "player": player_idx,
                    "go_again": go_again,
                    "direct": {
                        "card_id": card.id,
                        "damage": damage,
                        "arcane": arcane,
                        "go_again": go_again,
                        "dominate": dominate,
                        "fused": fused,
                        "elements": elements,
                        "perspective": perspective_idx,
                    },
                }
                self._optional_resume = "direct_arcane"
                self._phase = "optional"
                self._active_player = player_idx
                return 0.0
        self._queue_play_keywords(player_idx, card, perspective_idx)
        if arcane and actor.amp > 0:
            damage += actor.amp
            self._event_append(f"amp +{actor.amp} arcane damage")
            actor.amp = 0
        if arcane and actor.class_state.get("ArcanePlusOneThisPlay", 0):
            damage += 1
            actor.class_state["ArcanePlusOneThisPlay"] = 0
            self._event_append("Metacarpus Node: +1 arcane damage")
        if arcane and actor.class_state.get("ArcanePlusOneTurn", 0):
            damage += 1
            self._event_append("action arcane +1 this turn")
        if damage > 0:
            if not arcane:
                damage = self._apply_damage_floor(player_idx, damage)
            damage = self._mitigate_damage(
                1 - player_idx, damage, arcane=arcane, source_idx=player_idx
            )
        defender.life -= damage
        enters_arena = self._is_arena_permanent(card) and damage <= 0 and not arcane
        if enters_arena:
            actor.equipment.append(card.id)
            self._fire_enters_triggers(player_idx, card)
        else:
            actor.discard.append(card.id)

        if damage > 0:
            kind = "arcane damage" if arcane else "damage"
            verb = f"deals {damage} {kind} to P{1 - player_idx}"
            actor.class_state["ArcaneDamageDealt" if arcane else "DamageDealt"] += damage
            actor.class_state["HitCounter"] += 1
            if arcane:
                actor.class_state["LastArcaneHeroDamage"] = damage
            defender.class_state["DamageTaken"] += damage
        else:
            verb = "enters the arena" if enters_arena else "resolves"
        suffix = self._play_suffix(fused, elements, go_again)
        self._last_event = f"P{player_idx} plays {card.name} ({verb}){suffix}"

        reward = 0.0
        reward += self._run_triggers(player_idx, card, "on_play", None, perspective_idx, fused)
        if self._phase == "choice":
            return reward
        if fused:
            reward += self._run_triggers(player_idx, card, "when_fused", None, perspective_idx, fused)
        if "song" in (card.type_line or "").lower():
            reward += self._fire_equipment_triggers(player_idx, "whenever_song", perspective_idx)
        if damage > 0:
            reward += self._run_triggers(player_idx, card, "on_hit", None, perspective_idx, fused)

        if self._pending_optionals:
            self._optional_post_ctx = {"player": player_idx, "go_again": go_again}
            self._optional_resume = "direct_finish"
            self._phase = "optional"
            self._active_player = player_idx
            if damage > 0:
                reward += float(damage) * 0.01 if perspective_idx == player_idx else -float(damage) * 0.01
            return reward

        if go_again:
            self._grant_go_again(player_idx, None, this_card=False)

        if not self._is_terminal():
            if actor.action_points > 0:
                self._phase = "action"
                self._active_player = player_idx
            else:
                self._begin_arsenal_step(player_idx)

        if damage > 0:
            reward += float(damage) * 0.01 if perspective_idx == player_idx else -float(damage) * 0.01
        return reward

    def _do_block(self, defender_idx: int, hand_idx: int, perspective_idx: int = 0) -> float:
        combat = self._pending_combat
        if combat is None:
            self._last_event = "No attack to defend"
            return -0.05
        blocker = self._players[defender_idx]
        card = self._cards[blocker.hand[hand_idx]]
        if card.defense <= 0:
            self._last_event = f"{card.name} cannot block"
            return -0.05
        blocker.hand.pop(hand_idx)
        self._move_card_to_gy(defender_idx, card.id)
        if "defense_reaction" in card.card_types:
            self._queue_play_costs(defender_idx, card, perspective_idx)
        defense = card.defense + blocker.class_state.get("NextDefenseBonus", 0)
        defense -= self._defend_penalty_for_block(defender_idx, card)
        action_bonus = blocker.class_state.get("ActionBlockBonusThisChain", 0)
        if action_bonus and "attack_action" in card.card_types:
            defense += action_bonus
        if blocker.class_state.get("LightBlockBonusThisChain", 0) and "light" in (
            card.talent or ""
        ).lower():
            defense += blocker.class_state["LightBlockBonusThisChain"]
        if "combo" in card.keywords:
            for cid in blocker.equipment:
                for mod in effects.parse_play_modifiers(self._cards[cid].text):
                    if mod.condition == "next_defend_combo" and mod.defense:
                        defense += mod.defense
        if blocker.class_state.get("NextDefenseBonus", 0):
            blocker.class_state["NextDefenseBonus"] = 0
            self._event_append(f"+{defense - card.defense} defense bonus on block")
        combat.blocks.append((defender_idx, card.id, defense))
        if combat.attack_card_id:
            attack_card = self._cards.get(combat.attack_card_id)
            if attack_card:
                atk_blob = " ".join(
                    (
                        attack_card.text or "",
                        attack_card.talent or "",
                        attack_card.card_class or "",
                        attack_card.name or "",
                    )
                ).lower()
                if "lightning" in atk_blob or "elemental" in atk_blob:
                    self._fire_equipment_triggers(
                        combat.attacker, "on_lightning_hand_defend", perspective_idx
                    )
                for mod in effects.parse_play_modifiers(attack_card.text):
                    if mod.condition == "defended_by_action_penalty" and mod.power < 0:
                        self._apply_combat_power_bonus(
                            combat,
                            combat.attacker,
                            mod.power,
                            reason=f"{mod.power} power (defended by action)",
                        )
        self._last_event = f"P{defender_idx} blocks with {card.name} (+{defense} defense)"
        reward = self._run_triggers(defender_idx, card, "on_defend", combat, perspective_idx, False)
        if "defense_reaction" in card.card_types:
            reward += self._run_triggers(defender_idx, card, "on_play", combat, perspective_idx, False)
        return reward

    def _do_trap_defend(self, defender_idx: int, perspective_idx: int = 0) -> float:
        combat = self._pending_combat
        if combat is None:
            self._last_event = "No attack to defend"
            return -0.05
        if self._phase != "defense":
            self._last_event = "Traps can only be triggered during the defend step"
            return -0.05
        if not self._legal_trap_defense(defender_idx):
            self._last_event = "No trap in arsenal to trigger"
            return -0.05
        defender = self._players[defender_idx]
        cid = defender.arsenal.pop()
        card = self._cards[cid]
        defender.face_up_arsenal.add(cid)
        self._move_card_to_gy(defender_idx, cid)
        defense = card.defense + defender.class_state.get("NextDefenseBonus", 0)
        defense -= self._defend_penalty_for_block(defender_idx, card)
        action_bonus = defender.class_state.get("ActionBlockBonusThisChain", 0)
        if action_bonus and fab_rules.is_action_card(card.card_types):
            defense += action_bonus
        if defender.class_state.get("LightBlockBonusThisChain", 0) and "light" in (
            card.talent or ""
        ).lower():
            defense += defender.class_state["LightBlockBonusThisChain"]
        if defender.class_state.get("NextDefenseBonus", 0):
            defender.class_state["NextDefenseBonus"] = 0
        combat.blocks.append((defender_idx, cid, defense))
        self._last_event = (
            f"P{defender_idx} triggers {card.name} from arsenal (+{defense} defense)"
        )
        return self._fire_trap_triggered(defender_idx, card, combat, perspective_idx)

    def _do_block_gear(self, defender_idx: int, equip_idx: int, perspective_idx: int = 0) -> float:
        combat = self._pending_combat
        if combat is None:
            self._last_event = "No attack to defend"
            return -0.05
        defender = self._players[defender_idx]
        if equip_idx < 0 or equip_idx >= len(defender.equipment):
            self._last_event = "No such equipment"
            return -0.05
        cid = defender.equipment[equip_idx]
        card = self._cards[cid]
        if card.defense <= 0:
            self._last_event = f"{card.name} cannot block"
            return -0.05
        if f"equip:{cid}" in defender.arena_used:
            self._last_event = f"{card.name} already blocked this turn"
            return -0.05
        defense = self._effective_equipment_defense(defender_idx, cid, card.defense)
        defense += defender.class_state.get("NextDefenseBonus", 0)
        defense -= self._defend_penalty_for_block(defender_idx, card, is_equipment=True)
        for mod in effects.parse_play_modifiers(card.text):
            if mod.condition and not self._effect_condition_met(
                defender_idx, mod.condition, card, condition_arg=mod.condition_arg
            ):
                continue
            if mod.defense:
                bonus = mod.defense
                if mod.condition == "blue_pitched_each":
                    n_blue = sum(
                        1 for cid in defender.pitch_zone if self._cards[cid].pitch == 3
                    )
                    bonus *= max(0, n_blue)
                defense += bonus
        if defender.class_state.get("NextDefenseBonus", 0):
            defender.class_state["NextDefenseBonus"] = 0
        combat.blocks.append((defender_idx, cid, defense))
        defender.arena_used.add(f"equip:{cid}")
        attack_card = self._cards.get(combat.attack_card_id) if combat.attack_card_id else None
        if attack_card:
            pierce = fab_rules.parse_piercing_value(attack_card.text)
            if pierce > 0:
                self._apply_combat_power_bonus(
                    combat,
                    combat.attacker,
                    pierce,
                    reason=f"piercing +{pierce} power",
                )
        # Battleworn / blade break gear is destroyed after blocking.
        fragile = {"battleworn", "blade_break"} & set(card.keywords)
        if fragile:
            defender.equipment.pop(equip_idx)
            defender.discard.append(cid)
            self._fire_on_leave_triggers(defender_idx, cid)
            self._last_event = (
                f"P{defender_idx} blocks with {card.name} (+{card.defense} defense), destroyed"
            )
        else:
            self._last_event = f"P{defender_idx} blocks with {card.name} (+{card.defense} defense)"
        return self._run_triggers(defender_idx, card, "on_defend", combat, perspective_idx, False)

    def _do_reaction(self, attacker_idx: int, hand_idx: int) -> float:
        combat = self._pending_combat
        if combat is None:
            self._last_event = "No attack in progress"
            return -0.05
        if self._phase != "attack_reaction":
            self._last_event = "Attack reactions can only be played during the attack-reaction step"
            return -0.05
        attacker = self._players[attacker_idx]
        card = self._cards[attacker.hand[hand_idx]]
        if "attack_reaction" not in card.card_types:
            self._last_event = f"{card.name} is not an attack reaction"
            return -0.05
        if card.cost > attacker.resources:
            self._last_event = f"Need {card.cost} resources for {card.name}"
            return -0.05
        attacker.resources -= card.cost
        attacker.hand.pop(hand_idx)
        self._apply_combat_power_bonus(
            combat,
            attacker_idx,
            card.power,
            reason=f"+{card.power} power from {card.name}",
        )
        combat.reaction_cards.append(card.id)
        combat.attack_reactions_played += 1
        if "go_again" in card.keywords:
            self._grant_go_again(attacker_idx, combat, this_card=True)
        self._last_event = f"P{attacker_idx} boosts with {card.name} (+{card.power} power)"
        return 0.0

    def _do_defense_reaction(self, defender_idx: int, hand_idx: int, perspective_idx: int = 0) -> float:
        combat = self._pending_combat
        if combat is None:
            self._last_event = "No attack in progress"
            return -0.05
        if self._phase != "defense_reaction":
            self._last_event = "Defense reactions can only be played during the defense-reaction step"
            return -0.05
        if hand_idx not in self._legal_defense_reactions(defender_idx):
            self._last_event = "That defense reaction cannot be played now"
            return -0.05
        defender = self._players[defender_idx]
        card = self._cards[defender.hand[hand_idx]]
        cost = self._effective_card_cost(defender_idx, card) + defender.extra_defense_reaction_cost
        defender.resources -= cost
        self._consume_cost_reduction(defender_idx, card, cost)
        defender.hand.pop(hand_idx)
        self._move_card_to_gy(defender_idx, card.id)
        self._queue_play_costs(defender_idx, card, perspective_idx)
        defense = card.defense + defender.class_state.get("NextDefenseBonus", 0)
        defense -= self._defend_penalty_for_block(defender_idx, card)
        action_bonus = defender.class_state.get("ActionBlockBonusThisChain", 0)
        if action_bonus and fab_rules.is_action_card(card.card_types):
            defense += action_bonus
        if defender.class_state.get("LightBlockBonusThisChain", 0) and "light" in (
            card.talent or ""
        ).lower():
            defense += defender.class_state["LightBlockBonusThisChain"]
        if defender.class_state.get("NextDefenseBonus", 0):
            defender.class_state["NextDefenseBonus"] = 0
        combat.blocks.append((defender_idx, card.id, defense))
        self._last_event = (
            f"P{defender_idx} defends with {card.name} (+{defense} defense, reaction)"
        )
        reward = self._run_triggers(defender_idx, card, "on_defend", combat, perspective_idx, False)
        reward += self._run_triggers(defender_idx, card, "on_play", combat, perspective_idx, False)
        return reward

    def _do_weapon_attack(self, player_idx: int, perspective_idx: int = 0) -> float:
        actor = self._players[player_idx]
        if not self._can_weapon_attack(player_idx):
            self._last_event = "Cannot attack with weapon right now"
            return -0.05
        name, attack, cost, weapon_card = self._weapon_stats(player_idx)
        swing_extra = self._first_attack_extra_cost(player_idx, is_attack=True)
        eff_cost = self._effective_weapon_swing_cost(player_idx, cost, consume=True)
        actor.resources -= eff_cost + swing_extra
        actor.action_points -= 1
        self._mark_attack_started(player_idx)
        if actor.weapon_used:
            actor.class_state["ExtraWeaponAttacks"] = max(
                0, actor.class_state.get("ExtraWeaponAttacks", 0) - 1
            )
            self._event_append("extra weapon attack")
        else:
            actor.weapon_used = True
        actor.class_state["WeaponAttacksThisTurn"] = (
            actor.class_state.get("WeaponAttacksThisTurn", 0) + 1
        )
        keywords = set(weapon_card.keywords) if weapon_card else set()
        combat = CombatState(
            attacker=player_idx,
            defender=1 - player_idx,
            attack_card_id=weapon_card.id if weapon_card else "",
            attack_power=attack,
            blocks=[],
            go_again=("go_again" in keywords),
            dominate=("dominate" in keywords),
            is_weapon=True,
            source_name=name,
        )
        self._pending_combat = combat
        self._last_event = f"P{player_idx} attacks with {name} ({attack})"
        self._record_opponent_attack(
            player_idx,
            attack_name=name,
            attack_power=attack,
            is_weapon=True,
        )
        # A pending "next attack +power" buff also applies to weapon swings.
        if weapon_card is not None:
            self._consume_pending_next_attack_power(
                player_idx, self._cards[weapon_card.id], combat, is_weapon=True
            )
        else:
            self._consume_pending_next_attack_power(
                player_idx,
                Card(
                    id="hero_weapon",
                    name=name,
                    pitch=0,
                    cost=cost,
                    power=attack,
                    defense=0,
                    type_line="",
                    card_types=(),
                    card_class="",
                    talent=None,
                    rarity="",
                    set_code="",
                    keywords=(),
                    text="",
                    legality={},
                ),
                combat,
                is_weapon=True,
            )
        # Weapon on-attack triggers (on-hit fire later in _resolve_and_advance).
        reward = 0.0
        if weapon_card is not None:
            reward += self._run_triggers(player_idx, weapon_card, "on_attack", combat, perspective_idx, False)
            if re.search(
                r"earth card was pitched to attack with this",
                weapon_card.text or "",
                re.I,
            ) and any(
                (self._cards[cid].talent or "").lower() == "earth"
                for cid in actor.pitch_zone
            ):
                self._apply_combat_power_bonus(
                    combat,
                    player_idx,
                    1,
                    reason="Earth Bond +1 power",
                )
        if self._pending_optionals:
            self._optional_resume = "defense"
            self._phase = "optional"
            self._active_player = player_idx
        else:
            self._enter_defense()
        return reward

    def _do_item_attack(self, player_idx: int, item_id: str, perspective_idx: int = 0) -> float:
        """Attack using an equipment item's printed power (e.g. Miller's Grindstone)."""
        actor = self._players[player_idx]
        if item_id not in actor.equipment:
            self._last_event = "Item not in arena"
            return -0.05
        item = self._cards[item_id]
        attack = self._item_attack_power(player_idx, item_id)
        if attack <= 0:
            self._last_event = f"{item.name} has no attack"
            return -0.05
        keywords = set(item.keywords)
        combat = CombatState(
            attacker=player_idx,
            defender=1 - player_idx,
            attack_card_id=item_id,
            attack_power=attack,
            blocks=[],
            go_again=("go_again" in keywords),
            dominate=("dominate" in keywords),
            is_weapon=True,
            source_name=item.name,
        )
        self._pending_combat = combat
        self._last_event = f"P{player_idx} attacks with {item.name} ({attack})"
        self._record_opponent_attack(
            player_idx,
            attack_name=item.name,
            attack_power=attack,
            is_weapon=True,
        )
        self._consume_pending_next_attack_power(
            player_idx, item, combat, is_weapon=True
        )
        self._mark_attack_started(player_idx)
        reward = self._run_triggers(player_idx, item, "on_attack", combat, perspective_idx, False)
        if self._pending_optionals:
            self._optional_resume = "defense"
            self._phase = "optional"
            self._active_player = player_idx
        else:
            self._enter_defense()
        return reward

    def _do_stash(self, player_idx: int, hand_idx: int) -> float:
        actor = self._players[player_idx]
        if actor.arsenal:
            self._last_event = "Arsenal already holds a card"
            return -0.05
        if hand_idx < 0 or hand_idx >= len(actor.hand):
            self._last_event = "No such card to stash"
            return -0.05
        card = self._cards[actor.hand.pop(hand_idx)]
        actor.arsenal.append(card.id)
        self._last_event = f"P{player_idx} stashes {card.name} in arsenal"
        if self._phase == "arsenal":
            self._finish_action_phase(player_idx)
        return 0.0

    def _do_ability(self, player_idx: int, ability_idx: int, perspective_idx: int = 0) -> float:
        entries = self._ability_list(player_idx)
        if ability_idx < 0 or ability_idx >= len(entries):
            self._last_event = "No such ability"
            return -0.05
        entry = entries[ability_idx]
        if not self._ability_usable(player_idx, entry):
            self._last_event = f"Cannot use {entry['name']} ability now"
            return -0.05
        actor = self._players[player_idx]
        ability = entry["ability"]
        cid = entry.get("card_id") or ""
        if ability.counter_cost > 0 and cid:
            if not self._remove_permanent_counter(
                player_idx, cid, ability.counter_name, ability.counter_cost
            ):
                self._last_event = "Not enough counters to activate"
                return -0.05
        if (
            ability.effect.kind == "put_counter"
            and (ability.effect.token_name or "").lower() == "steam"
            and cid
            and self._permanent_counters(player_idx, cid).get("steam", 0) > 0
        ):
            self._last_event = "Already has a steam counter"
            return -0.05
        pay_cost = max(0, ability.cost - actor.class_state.get("NextAbilityCostReduction", 0))
        if ability.effect.kind == "attack" and cid and cid in actor.equipment:
            item = self._cards[cid]
            if item.power > 0:
                pay_cost += self._first_attack_extra_cost(player_idx, is_attack=True)
        actor.resources -= pay_cost
        if actor.class_state.get("NextAbilityCostReduction", 0) > 0 and ability.cost > 0:
            actor.class_state["NextAbilityCostReduction"] = 0
        if ability.uses_action_point:
            actor.action_points -= 1
        if ability.once_per_turn:
            actor.arena_used.add(entry["token"])
        if ability.destroy_source or ability.discard_source:
            token = entry["token"]
            if token.startswith("equip:"):
                cid = token.split(":", 1)[1]
                if cid in actor.equipment:
                    actor.equipment.remove(cid)
                    actor.discard.append(cid)
                    self._fire_on_leave_triggers(player_idx, cid, perspective_idx)
            elif token.startswith("weapon:"):
                cid = token.split(":", 1)[1]
                if actor.weapon_id == cid:
                    actor.weapon_id = None
                    actor.discard.append(cid)
                    self._fire_on_leave_triggers(player_idx, cid, perspective_idx)
        self._last_event = f"P{player_idx} activates {entry['name']}"
        card_id = entry.get("card_id") or ""
        if card_id and card_id in self._cards:
            card = self._cards[card_id]
        else:
            card = Card(
                id="",
                name=entry["name"],
                pitch=0,
                cost=0,
                power=0,
                defense=0,
                type_line="",
                card_types=(),
                card_class="",
                talent=None,
                rarity="",
                set_code="",
                keywords=(),
                text="",
                legality={},
            )
        effect = ability.effect
        if effect.kind == "attack":
            item_cid = entry.get("card_id") or ""
            if item_cid and item_cid in actor.equipment:
                item = self._cards[item_cid]
                if item.power > 0:
                    return self._do_item_attack(player_idx, item_cid, perspective_idx)
            if self._phase == "action" and self._can_weapon_attack(player_idx):
                return self._do_weapon_attack(player_idx, perspective_idx)
            return 0.0
        reward = self._apply_effect(
            player_idx, card, effect, self._pending_combat, perspective_idx
        )
        if ability.grants_go_again:
            self._grant_go_again(player_idx, None, this_card=False)
        return reward

    def _do_instant_play(self, player_idx: int, hand_idx: int, perspective_idx: int = 0) -> float:
        """Play an instant card or a utility action granted play-as-instant."""
        actor = self._players[player_idx]
        if hand_idx < 0 or hand_idx >= len(actor.hand):
            self._last_event = "No such card"
            return -0.05
        if not self._instant_playable(
            player_idx,
            hand_idx,
            in_action=self._phase == "action" and self._action_phase_player == player_idx,
        ):
            self._last_event = "That instant cannot be played now"
            return -0.05
        card = self._cards[actor.hand[hand_idx]]
        in_combat = self._in_combat_chain()
        in_action = self._phase == "action" and self._action_phase_player == player_idx
        if not in_combat and not in_action:
            self._last_event = "Instants cannot be played now"
            return -0.05
        effective_cost = self._effective_card_cost(player_idx, card)
        if actor.resources < effective_cost:
            if effective_cost > 0 and self._can_pitch_to_afford(
                player_idx, effective_cost, exclude_card_ids={card.id}
            ):
                return self._begin_instant_pay(
                    player_idx, hand_idx, perspective_idx, effective_cost
                )
            self._last_event = f"Need {effective_cost} resources"
            return -0.05
        return self._finish_instant_play(player_idx, hand_idx, perspective_idx)

    def _finish_instant_play(
        self,
        player_idx: int,
        hand_idx: int,
        perspective_idx: int = 0,
    ) -> float:
        """Resolve an instant after its resource cost is paid."""
        actor = self._players[player_idx]
        card = self._cards[actor.hand[hand_idx]]
        effective_cost = self._effective_card_cost(player_idx, card)
        if actor.resources < effective_cost:
            if effective_cost > 0 and self._can_pitch_to_afford(
                player_idx, effective_cost, exclude_card_ids={card.id}
            ):
                return self._begin_instant_pay(
                    player_idx, hand_idx, perspective_idx, effective_cost
                )
            self._last_event = f"Need {effective_cost} resources"
            return -0.05
        is_grant_utility = actor.play_as_instant and "utility_action" in card.card_types
        if is_grant_utility:
            actor.play_as_instant = False
        actor.resources -= effective_cost
        self._consume_cost_reduction(player_idx, card, effective_cost)
        actor.hand.pop(hand_idx)
        # Check if an on-attack effect asked us to return the attack card (or an aura) on next instant.
        _nie = actor.class_state.pop("NextInstantEffect", None)
        if _nie == "return_self":
            _nie_cid = actor.class_state.pop("NextInstantCardId", None)
            if _nie_cid is not None:
                actor.class_state["ReturnAttackCardToHand"] = _nie_cid
        elif _nie == "return_aura":
            actor.class_state.pop("NextInstantCardId", None)
            # Mark so the attack resolution can bounce opponent aura (best-effort, no-op if none).
            actor.class_state["ReturnOpponentAura"] = True
        keywords = set(card.keywords)
        go_again = self._go_again_for_play(player_idx, card, True)
        dominate = "dominate" in keywords
        is_attack = "attack_action" in card.card_types
        damage, arcane = _parse_action_damage(
            card.text,
            card.power if is_attack else 0,
            is_attack,
        )
        self._last_event = f"P{player_idx} plays {card.name} as instant"
        return self._resolve_direct(
            player_idx, card, damage, arcane, go_again, dominate, False, (), perspective_idx
        )

    def _apply_ability_effect(
        self, player_idx: int, source_name: str, effect: "effects.Effect", perspective_idx: int
    ) -> float:
        """Resolve an activated-ability effect (no combat chain attached)."""
        card = Card(
            id="",
            name=source_name,
            pitch=0,
            cost=0,
            power=0,
            defense=0,
            type_line="",
            card_types=(),
            card_class="",
            talent=None,
            rarity="",
            set_code="",
            keywords=(),
            text="",
            legality={},
        )
        if effect.kind == "attack":
            if self._phase == "action" and self._can_weapon_attack(player_idx):
                return self._do_weapon_attack(player_idx, perspective_idx)
            return 0.0
        return self._apply_effect(player_idx, card, effect, None, perspective_idx)

    # ------------------------------------------------------------------
    # Phase transitions
    # ------------------------------------------------------------------
    def _enter_defense(self) -> None:
        combat = self._pending_combat
        attack = self._cards.get(combat.attack_card_id)
        attacker = self._players[combat.attacker]
        cs = attacker.class_state
        cs["ComboLastAttackDraconic"] = cs.get("CurrentChainAttackDraconic", 0)
        if attack is not None:
            cs["LastChainAttackName"] = attack.name
            cs["CurrentChainAttackDraconic"] = (
                1 if self._card_is_draconic(attack, combat.attacker) else 0
            )
        if self._card_is_draconic(attack, combat.attacker, consume_pending=True):
            combat.draconic_links += 1
        self._combat_chain_links += 1
        self._phase = "defense"
        self._active_player = combat.defender

    def _enter_attack_reaction(self) -> None:
        combat = self._pending_combat
        if combat is None:
            return
        self._phase = "attack_reaction"
        self._active_player = combat.attacker

    def _enter_defense_reaction(self) -> None:
        combat = self._pending_combat
        if combat is None:
            return
        self._phase = "defense_reaction"
        self._active_player = combat.defender

    def _pass_action(self, player_idx: int) -> None:
        self._begin_arsenal_step(player_idx)

    def _pass_defense(self, defender_idx: int) -> None:
        if self._pending_combat is None:
            self._phase = "action"
            return
        self._enter_attack_reaction()

    def _pass_attack_reaction(self) -> None:
        if self._pending_combat is None:
            self._phase = "action"
            return
        self._enter_defense_reaction()

    def _pass_defense_reaction(self, perspective_idx: int) -> float:
        return self._resolve_and_advance(perspective_idx)

    def _hit_effects_allowed(self, combat: CombatState, attacker_idx: int) -> bool:
        if not combat.hit_effects_blocked:
            return True
        attacker = self._players[attacker_idx]
        cost = max(1, combat.hit_effects_unblock_cost)
        if attacker.resources >= cost:
            attacker.resources -= cost
            self._event_append(f"attacker paid {cost} resources to enable hit effects")
            return True
        self._event_append("hit effects blocked")
        return False

    def _complete_combat_resolution(
        self,
        reward: float,
        perspective_idx: int,
        attacker_idx: int,
        defender_idx: int,
        damage: int,
        go_again: bool,
        fused: bool,
    ) -> float:
        combat = self._pending_combat
        if combat is None:
            return reward
        attack_card = self._cards.get(combat.attack_card_id) if combat.attack_card_id else None
        if attack_card is not None:
            reward += self._fire_chain_close_triggers(
                attacker_idx, attack_card, damage, perspective_idx, fused
            )
        for block_player, b_cid, _ in combat.blocks:
            reward += self._fire_block_chain_close_triggers(
                block_player, self._cards[b_cid], damage, perspective_idx
            )

        self._pending_combat = None
        self._reset_chain_soul_counters()
        self._clear_chain_may_play_grants(attacker_idx)
        self._clear_chain_may_play_grants(defender_idx)
        self._optional_ctx = {"attacker": attacker_idx, "defender": defender_idx, "go_again": go_again}

        if self._pending_optionals:
            self._optional_resume = "advance"
            self._phase = "optional"
            self._active_player = attacker_idx
        else:
            self._finish_combat_advance()

        if damage > 0:
            reward += float(damage) * 0.01 if perspective_idx == attacker_idx else -float(damage) * 0.01
        return reward

    def _resolve_and_advance(self, perspective_idx: int) -> float:
        combat = self._pending_combat
        if combat is None:
            return 0.0
        attacker_idx = combat.attacker
        defender_idx = combat.defender
        attacker = self._players[attacker_idx]
        defender = self._players[defender_idx]
        attack_card = self._cards.get(combat.attack_card_id) if combat.attack_card_id else None

        if attack_card is not None:
            for mod in effects.parse_play_modifiers(attack_card.text):
                if mod.condition != "defended_by_ge_pay":
                    continue
                need = int(mod.condition_arg or "1")
                if len(combat.blocks) < need:
                    continue
                if attacker.resources >= 1:
                    attacker.resources -= 1
                    self._apply_combat_power_bonus(
                        combat,
                        attacker_idx,
                        mod.power,
                        reason=f"Spark Spray: +{mod.power} power",
                    )

        total_block = sum(b[2] for b in combat.blocks)
        total_power = max(
            0,
            combat.attack_power + combat.attack_bonus + combat.opposing_power_mod,
        )
        raw_damage = max(0, total_power - total_block)
        raw_damage = self._apply_damage_floor(attacker_idx, raw_damage)
        if attacker.class_state.get("AttackDamagePlusOneTurn", 0) and raw_damage > 0:
            raw_damage += 1
            self._event_append("attack damage +1 this turn")
        damage = self._mitigate_damage(defender_idx, raw_damage)
        _defender_life_before = defender.life
        defender.life -= damage
        if self.on_combat_resolve is not None:
            try:
                self.on_combat_resolve({
                    "combat": combat,
                    "attacker_idx": attacker_idx,
                    "defender_idx": defender_idx,
                    "total_power": total_power,
                    "total_block": total_block,
                    "raw_damage": raw_damage,
                    "damage": damage,
                    "defender_life_before": _defender_life_before,
                })
            except Exception:  # noqa: BLE001 — never let oracle bugs break gameplay
                pass
        if damage > 0:
            defender.class_state["DamageTakenThisTurn"] = (
                defender.class_state.get("DamageTakenThisTurn", 0) + damage
            )

        # Weapons stay in the arena; action attacks (and reactions) go to discard.
        fused = combat.fused
        if not combat.is_weapon and combat.attack_card_id:
            skip = attacker.class_state.get("SkipGyThisCard", 0)
            return_to_hand_cid = attacker.class_state.pop("ReturnAttackCardToHand", None)
            if skip == combat.attack_card_id:
                attacker.class_state["SkipGyThisCard"] = 0
            elif return_to_hand_cid == combat.attack_card_id:
                attacker.hand.append(combat.attack_card_id)
                self._event_append(f"{attack_card.name if attack_card else 'attack'} returned to hand by instant effect")
            else:
                self._move_card_to_gy(attacker_idx, combat.attack_card_id)
            if attack_card is not None:
                self._run_triggers(attacker_idx, attack_card, "on_gy_enter", None, perspective_idx, fused)
        if (
            attack_card is not None
            and damage == 0
            and (
                "phantasm" in attack_card.keywords
                or "phantasm" in (attack_card.text or "").lower()
            )
        ):
            attacker.class_state["PhantasmDestroyedThisTurn"] = 1
            self._event_append(f"{attack_card.name} destroyed by phantasm")
        attacker.discard.extend(combat.reaction_cards)
        go_again = combat.go_again
        if attacker_idx != 0:
            self._last_event = (
                f"P{attacker_idx} hits P{defender_idx} for {damage} "
                f"(power {total_power} vs block {total_block})"
            )
        self._record_combat_resolution(
            combat,
            attacker_idx=attacker_idx,
            defender_idx=defender_idx,
            attack_card=attack_card,
            total_power=total_power,
            total_block=total_block,
            damage=damage,
        )

        reward = 0.0
        if damage > 0:
            attacker.class_state["LastHitDamage"] = damage
            attacker.class_state["DamageDealt"] += damage
            attacker.class_state["HitCounter"] += 1
            defender.class_state["DamageTaken"] += damage
            if combat.is_weapon:
                attacker.class_state["WeaponHitsThisTurn"] = (
                    attacker.class_state.get("WeaponHitsThisTurn", 0) + 1
                )
            bonus = attacker.class_state.get("BonusHitDamage", 0)
            if bonus > 0:
                extra = self._mitigate_damage(defender_idx, bonus)
                if extra > 0:
                    defender.life -= extra
                    attacker.class_state["DamageDealt"] += extra
                    defender.class_state["DamageTaken"] += extra
                    self._event_append(f"bonus hit damage: {extra}")
            if attack_card is not None and "intimidate" in attack_card.keywords:
                self._do_intimidate(defender_idx)
            if attack_card is not None and not combat.is_weapon:
                attacker.class_state["LastChainAttackPitch"] = attack_card.pitch
            if attack_card is not None:
                reward += self._fire_damage_triggers(
                    attacker_idx, attack_card, damage, perspective_idx, fused
                )
            hit_ok = self._hit_effects_allowed(combat, attacker_idx)
            # On-hit triggers fire only when the attack connects.
            if attack_card is not None and hit_ok:
                reward += self._run_triggers(attacker_idx, attack_card, "on_hit", combat, perspective_idx, fused)
                reward += self._apply_pending_hit_rider(
                    attacker_idx, attack_card, combat, perspective_idx
                )
                if self._phase == "choice":
                    self._choice_ctx["combat_finish"] = {
                        "reward": reward,
                        "perspective": perspective_idx,
                        "attacker_idx": attacker_idx,
                        "defender_idx": defender_idx,
                        "damage": damage,
                        "go_again": go_again,
                        "fused": fused,
                    }
                    return reward
            if damage > 0 and attacker.class_state.get("NextAttackOnHitExtraWeapon", 0):
                attacker.class_state["NextAttackOnHitExtraWeapon"] = 0
                attacker.class_state["ExtraWeaponAttacks"] = (
                    attacker.class_state.get("ExtraWeaponAttacks", 0) + 1
                )
                self._event_append("extra weapon attack granted on hit")
            if damage > 0 and attack_card is not None and "stealth" in attack_card.keywords:
                attacker.class_state["StealthHitThisTurn"] = 1
            if hit_ok:
                reward += self._fire_controlled_hit_triggers(attacker_idx, perspective_idx, fused)
                reward += self._fire_chain_hit_triggers(attacker_idx, perspective_idx)
                if combat.is_weapon:
                    reward += self._fire_equipment_triggers(
                        attacker_idx, "on_weapon_hit", perspective_idx
                    )
                    weapon_id = attacker.weapon_id
                    if weapon_id and "gun" in self._cards[weapon_id].name.lower():
                        reward += self._fire_equipment_triggers(
                            attacker_idx, "on_gun_hit", perspective_idx
                        )

        return self._complete_combat_resolution(
            reward,
            perspective_idx,
            attacker_idx,
            defender_idx,
            damage,
            go_again,
            fused,
        )

    def _agent_combat_instant_step(self, parsed: str, perspective_idx: int) -> float:
        """Resolve agent instant/may-play actions during a combat chain."""
        if parsed.startswith("instant "):
            return self._do_instant_play(perspective_idx, int(parsed.split(" ")[1]), perspective_idx)
        if parsed == "deckplay":
            return self._do_play_deck_top(perspective_idx, perspective_idx)
        if parsed.startswith("mayplay "):
            parts = parsed.split(" ")
            return self._do_may_play(perspective_idx, parts[1], int(parts[2]), perspective_idx)
        return -0.1

    def _opponent_attack_reaction(self) -> None:
        combat = self._pending_combat
        if combat is None or combat.attacker != 1:
            self._pass_attack_reaction()
            return
        opp = self._players[1]
        reactions = self._legal_reactions(1)
        if reactions:
            self._do_reaction(1, reactions[0])
            return
        self._pass_attack_reaction()

    def _opponent_defense_reaction(self) -> float:
        combat = self._pending_combat
        if combat is None or combat.defender != 1:
            return self._pass_defense_reaction(0)
        reactions = self._legal_defense_reactions(1)
        if reactions:
            self._do_defense_reaction(1, reactions[0], 0)
            return 0.0
        return self._pass_defense_reaction(0)

    # ------------------------------------------------------------------
    # Self-play transition (single policy controls the active player)
    # ------------------------------------------------------------------
    def _step_self_play(self, parsed: str) -> float:
        player = self._active_player

        if self._phase == "action":
            if parsed == "pass":
                self._last_event = f"P{player} passed turn"
                self._pass_action(player)
                return 0.0
            if parsed.startswith("pitch "):
                return self._do_pitch(player, int(parsed.split(" ")[1]))
            if parsed.startswith("play "):
                return self._do_play_card(player, int(parsed.split(" ")[1]), player)
            if parsed.startswith("arsenalplay"):
                return self._do_play_arsenal(player, player)
            if parsed.startswith("banishplay "):
                return self._do_play_banished(player, int(parsed.split(" ")[1]), player)
            if parsed.startswith("gyplay "):
                return self._do_play_graveyard(player, int(parsed.split(" ")[1]), player)
            if parsed == "weapon":
                return self._do_weapon_attack(player, player)
            if parsed.startswith("ability "):
                return self._do_ability(player, int(parsed.split(" ")[1]), player)
            if parsed == "deckplay":
                return self._do_play_deck_top(player, player)
            if parsed.startswith("mayplay "):
                parts = parsed.split(" ")
                return self._do_may_play(player, parts[1], int(parts[2]), player)
            if parsed.startswith("instant "):
                return self._do_instant_play(player, int(parsed.split(" ")[1]), player)
            return 0.0

        if self._phase == "arsenal":
            if parsed == "pass":
                self._last_event = f"P{player} skipped arsenal stash"
                self._pass_arsenal(player)
                return 0.0
            if parsed.startswith("stash "):
                return self._do_stash(player, int(parsed.split(" ")[1]))
            return 0.0

        if self._phase == "defense":
            if parsed == "pass":
                self._pass_defense(player)
                return 0.0
            if parsed.startswith("block "):
                return self._do_block(player, int(parsed.split(" ")[1]))
            if parsed.startswith("blockgear "):
                return self._do_block_gear(player, int(parsed.split(" ")[1]))
            if parsed == "trapdefend":
                return self._do_trap_defend(player, player)
            if parsed.startswith("instant "):
                return self._do_instant_play(player, int(parsed.split(" ")[1]), player)
            if parsed == "deckplay":
                return self._do_play_deck_top(player, player)
            if parsed.startswith("mayplay "):
                parts = parsed.split(" ")
                return self._do_may_play(player, parts[1], int(parts[2]), player)
            return 0.0

        if self._phase == "attack_reaction":
            if parsed == "pass":
                self._pass_attack_reaction()
                return 0.0
            if parsed.startswith("reaction "):
                return self._do_reaction(player, int(parsed.split(" ")[1]))
            if parsed.startswith("instant "):
                return self._do_instant_play(player, int(parsed.split(" ")[1]), player)
            if parsed == "deckplay":
                return self._do_play_deck_top(player, player)
            if parsed.startswith("mayplay "):
                parts = parsed.split(" ")
                return self._do_may_play(player, parts[1], int(parts[2]), player)
            return 0.0

        if self._phase == "defense_reaction":
            if parsed == "pass":
                return self._pass_defense_reaction(player)
            if parsed.startswith("defreact "):
                return self._do_defense_reaction(player, int(parsed.split(" ")[1]), player)
            if parsed.startswith("instant "):
                return self._do_instant_play(player, int(parsed.split(" ")[1]), player)
            if parsed == "deckplay":
                return self._do_play_deck_top(player, player)
            if parsed.startswith("mayplay "):
                parts = parsed.split(" ")
                return self._do_may_play(player, parts[1], int(parts[2]), player)
            return 0.0

        if self._phase == "optional":
            return self._do_optional(parsed == "use_optional")

        if self._phase == "choice":
            if parsed == "pass":
                return self._resolve_card_choice(None)
            if parsed.startswith("choose "):
                return self._resolve_card_choice(int(parsed.split()[1]))
            return 0.0

        if self._phase == "opt":
            if parsed == "opt_bottom":
                self._do_opt_choice(player, to_bottom=True)
            elif parsed == "opt_top":
                self._do_opt_choice(player, to_bottom=False)
            return 0.0

        if self._phase == "instant_pay":
            if parsed == "pass":
                self._cancel_instant_pay()
                return 0.0
            if parsed.startswith("pitch "):
                return self._do_pitch(player, int(parsed.split(" ")[1]))
            return 0.0

        if self._phase == "pitch_pay":
            if parsed == "pass":
                return self._pass_pitch_pay()
            if parsed.startswith("pitch "):
                return self._do_pitch(player, int(parsed.split(" ")[1]))
            return 0.0

        return 0.0

    # ------------------------------------------------------------------
    # Opponent automation (non-self-play): drive player 1 until it is the
    # agent's turn to decide, or the game ends.
    # ------------------------------------------------------------------
    def _auto_advance(self) -> float:
        accum = 0.0
        guard = 0
        while not self._is_terminal() and guard < 2000:
            guard += 1
            phase = self._phase
            if self._active_player == 0:
                if phase == "action":
                    return accum
                if phase == "arsenal":
                    return accum
                if phase == "optional":
                    return accum
                if phase == "choice":
                    return accum
                if phase == "opt":
                    return accum
                if phase == "instant_pay":
                    return accum
                if phase == "pitch_pay":
                    return accum
                if phase == "defense":
                    if self._legal_blocks(0) or self._legal_gear_blocks(0):
                        return accum
                    if self._combat_instant_actions_for(0):
                        return accum
                    self._pass_defense(0)
                    continue
                if phase == "attack_reaction":
                    if self._legal_reactions(0):
                        return accum
                    if self._combat_instant_actions_for(0):
                        return accum
                    self._pass_attack_reaction()
                    continue
                if phase == "defense_reaction":
                    if self._legal_defense_reactions(0):
                        return accum
                    if self._combat_instant_actions_for(0):
                        return accum
                    accum += self._pass_defense_reaction(0)
                    continue
                return accum

            # Opponent (player 1) to act.
            if phase == "action":
                accum += self._opponent_action()
            elif phase == "arsenal":
                accum += self._opponent_arsenal_action()
            elif phase == "optional":
                accum += self._do_optional(True)
            elif phase == "choice":
                ctx = self._choice_ctx
                if ctx and ctx.get("options"):
                    if ctx.get("kind") == "mode":
                        if ctx.get("pick_any") and self._rng.random() < 0.3:
                            accum += self._resolve_mode_choice(None)
                        else:
                            pick = self._rng.randrange(len(ctx["options"]))
                            accum += self._resolve_mode_choice(pick)
                    else:
                        pick = self._rng.randrange(len(ctx["options"]))
                        accum += self._resolve_card_choice(pick)
            elif phase == "opt":
                self._do_opt_choice(1, to_bottom=False)
            elif phase == "defense":
                self._opponent_block()
            elif phase == "attack_reaction":
                self._opponent_attack_reaction()
            elif phase == "defense_reaction":
                accum += self._opponent_defense_reaction()
            elif phase == "instant_pay":
                accum += self._opponent_instant_pay()
            elif phase == "pitch_pay":
                accum += self._opponent_pitch_pay()
            else:
                return accum
        return accum

    def _opponent_instant_pay(self) -> float:
        """Pitch until the opponent can pay for a pending instant play."""
        ctx = self._pending_instant_pay
        if not ctx or ctx.get("player") != 1:
            return 0.0
        opp = self._players[1]
        cost = ctx["cost"]
        if opp.resources >= cost:
            return self._try_complete_instant_pay()
        best_idx: Optional[int] = None
        best_rank: Optional[tuple[int, int]] = None
        for i, cid in enumerate(opp.hand):
            if cid in opp.arsenal or cid == ctx.get("card_id"):
                continue
            card = self._cards[cid]
            if card.pitch <= 0:
                continue
            is_attack = 1 if "attack_action" in card.card_types else 0
            rank = (is_attack, card.power + card.defense)
            if best_rank is None or rank < best_rank:
                best_rank = rank
                best_idx = i
        if best_idx is None:
            self._cancel_instant_pay()
            self._last_event = "Opponent cancelled instant (cannot pitch)"
            return -0.05
        return self._do_pitch(1, best_idx)

    def _opponent_pitch_pay(self) -> float:
        """Pitch until the opponent can pay a pending pitch_pay cost."""
        ctx = self._pending_pitch_pay
        if not ctx or ctx.get("player") != 1:
            return 0.0
        opp = self._players[1]
        cost = ctx["cost"]
        if ctx.get("variable"):
            paid = opp.resources - ctx.get("resources_at_start", opp.resources)
            if paid >= 1:
                return self._pass_pitch_pay()
        elif opp.resources >= cost:
            return self._pass_pitch_pay()
        best_idx: Optional[int] = None
        best_rank: Optional[tuple[int, int]] = None
        for i, cid in enumerate(opp.hand):
            if cid in opp.arsenal:
                continue
            card = self._cards[cid]
            if card.pitch <= 0:
                continue
            is_attack = 1 if "attack_action" in card.card_types else 0
            rank = (is_attack, card.power + card.defense)
            if best_rank is None or rank < best_rank:
                best_rank = rank
                best_idx = i
        if best_idx is None:
            return self._cancel_pitch_pay()
        return self._do_pitch(1, best_idx)

    def _opponent_prepare_resources(self, budget: int = 3) -> None:
        """Auto-pitch low-value cards so the scripted opponent can afford a play."""
        opp = self._players[1]
        guard = 0
        while opp.resources < budget and guard < 12:
            guard += 1
            best_idx: Optional[int] = None
            best_rank: Optional[tuple[int, int]] = None
            for i, cid in enumerate(opp.hand):
                if cid in opp.arsenal:
                    continue
                card = self._cards[cid]
                if card.pitch <= 0:
                    continue
                # Prefer pitching non-attacks and weaker cards.
                is_attack = 1 if "attack_action" in card.card_types else 0
                rank = (is_attack, card.power + card.defense)
                if best_rank is None or rank < best_rank:
                    best_rank = rank
                    best_idx = i
            if best_idx is None:
                break
            self._do_pitch(1, best_idx)

    def _opponent_action(self) -> float:
        opp = self._players[1]
        self._opponent_prepare_resources()
        try:
            idx = self._opponent_policy.select_attack_index(self)
        except Exception:
            self._opponent_type = "preset_logic"
            self._opponent_policy = self._build_opponent_policy(self._opponent_type)
            idx = self._opponent_policy.select_attack_index(self)
        # Guard against an unplayable pick (e.g. unmet requirement) so the
        # opponent never stalls the action phase.
        if (
            idx is None
            or idx < 0
            or idx >= len(opp.hand)
            or idx not in self._legal_plays(1)
        ):
            # No worthwhile card play: swing with the weapon if able, else pass.
            if self._can_weapon_attack(1):
                return self._do_weapon_attack(1, 0)
            self._last_event = "Opponent passed"
            self._pass_action(1)
            return 0.0
        return self._do_play_card(1, idx, 0)

    def _opponent_arsenal_action(self) -> float:
        legal = self._legal_stash(1)
        if not legal:
            self._pass_arsenal(1)
            return 0.0
        opp = self._players[1]
        best_idx: Optional[int] = None
        best_rank: Optional[tuple[int, int]] = None
        for i in legal:
            card = self._cards[opp.hand[i]]
            is_attack = 1 if "attack_action" in card.card_types else 0
            rank = (is_attack, -card.defense)
            if best_rank is None or rank < best_rank:
                best_rank = rank
                best_idx = i
        if best_idx is not None:
            card = self._cards[opp.hand[best_idx]]
            if card.defense >= 3 or "attack_action" not in card.card_types:
                return self._do_stash(1, best_idx)
        self._pass_arsenal(1)
        return 0.0

    def _opponent_block(self) -> None:
        combat = self._pending_combat
        if combat is None or combat.defender != 1:
            self._pass_defense(1)
            return
        defender = self._players[1]
        guard = 0
        while combat is self._pending_combat and guard < 12:
            guard += 1
            remaining = combat.attack_power + combat.attack_bonus - sum(b[2] for b in combat.blocks)
            if remaining <= 0:
                break
            if self._legal_trap_defense(1):
                self._do_trap_defend(1, 1)
                continue
            if combat.dominate and self._defender_hand_blocks(combat, 1):
                break
            try:
                bidx = self._opponent_policy.select_block_index(self)
            except Exception:
                self._opponent_type = "preset_logic"
                self._opponent_policy = self._build_opponent_policy(self._opponent_type)
                bidx = self._opponent_policy.select_block_index(self)
            if bidx is None or bidx < 0 or bidx >= len(defender.hand):
                break
            self._do_block(1, bidx)
        # Soak remaining damage with equipment before taking the hit.
        guard = 0
        while combat is self._pending_combat and guard < 8:
            guard += 1
            remaining = combat.attack_power + combat.attack_bonus - sum(b[2] for b in combat.blocks)
            if remaining <= 0:
                break
            gear = self._legal_gear_blocks(1)
            if not gear:
                break
            self._do_block_gear(1, gear[0])
        self._pass_defense(1)

    def _legal_actions(self) -> list[str]:
        if self._selection_stage:
            return [f"choose_deck {o['key']}" for o in self._deck_options_for_format()]
        if not self._initialized or len(self._players) < 2:
            return ["pass"]
        if self._is_terminal():
            return []

        actor_idx = self._active_player
        if not self._self_play:
            if actor_idx != 0:
                instant_actions = self._combat_instant_actions_for(0)
                if instant_actions:
                    return instant_actions + ["pass"]
                return ["pass"]

        if self._phase == "action":
            actions = ["pass"]
            actions.extend(f"pitch {i}" for i in self._legal_pitches(actor_idx))
            actions.extend(f"play {i}" for i in self._legal_plays(actor_idx))
            if self._legal_arsenal_plays(actor_idx):
                actions.append("arsenalplay")
            actions.extend(f"banishplay {i}" for i in self._legal_banished_plays(actor_idx))
            actions.extend(f"gyplay {i}" for i in self._legal_graveyard_plays(actor_idx))
            if self._can_weapon_attack(actor_idx):
                actions.append("weapon")
            actions.extend(f"ability {i}" for i in self._legal_abilities(actor_idx))
            actions.extend(f"instant {i}" for i in self._legal_instant_plays(actor_idx))
            if self._can_deck_top_play_now(actor_idx):
                actions.append("deckplay")
            actions.extend(self._legal_may_plays(actor_idx))
            return actions

        if self._phase == "arsenal":
            if actor_idx != self._action_phase_player:
                return ["pass"]
            actions = ["pass"]
            actions.extend(f"stash {i}" for i in self._legal_stash(actor_idx))
            return actions

        if self._phase == "defense":
            if self._pending_combat is None or self._pending_combat.defender != actor_idx:
                return self._combat_instant_actions_for(actor_idx) + ["pass"]
            actions = ["pass"]
            actions.extend(f"block {i}" for i in self._legal_blocks(actor_idx))
            actions.extend(f"blockgear {i}" for i in self._legal_gear_blocks(actor_idx))
            if self._legal_trap_defense(actor_idx):
                actions.append("trapdefend")
            actions.extend(f"instant {i}" for i in self._legal_instant_plays(actor_idx))
            if self._can_deck_top_play_now(actor_idx):
                actions.append("deckplay")
            actions.extend(self._legal_may_plays(actor_idx))
            return actions

        if self._phase == "attack_reaction":
            if self._pending_combat is None or self._pending_combat.attacker != actor_idx:
                return self._combat_instant_actions_for(actor_idx) + ["pass"]
            actions = ["pass"]
            actions.extend(f"reaction {i}" for i in self._legal_reactions(actor_idx))
            actions.extend(f"instant {i}" for i in self._legal_instant_plays(actor_idx))
            if self._can_deck_top_play_now(actor_idx):
                actions.append("deckplay")
            actions.extend(self._legal_may_plays(actor_idx))
            return actions

        if self._phase == "defense_reaction":
            if self._pending_combat is None or self._pending_combat.defender != actor_idx:
                return self._combat_instant_actions_for(actor_idx) + ["pass"]
            actions = ["pass"]
            actions.extend(f"defreact {i}" for i in self._legal_defense_reactions(actor_idx))
            actions.extend(f"instant {i}" for i in self._legal_instant_plays(actor_idx))
            if self._can_deck_top_play_now(actor_idx):
                actions.append("deckplay")
            actions.extend(self._legal_may_plays(actor_idx))
            return actions

        if self._phase == "optional":
            if not self._pending_optionals or self._pending_optionals[0]["player"] != actor_idx:
                return ["pass"]
            return ["use_optional", "pass"]

        if self._phase == "choice":
            ctx = self._choice_ctx
            if not ctx or ctx.get("chooser") != actor_idx:
                return ["pass"]
            actions = [f"choose {o['index']}" for o in ctx.get("options", [])]
            if ctx.get("optional"):
                actions.append("pass")
            return actions or ["pass"]

        if self._phase == "opt":
            if not self._opt_ctx or self._opt_ctx.get("player") != actor_idx:
                return ["pass"]
            return ["opt_top", "opt_bottom"]

        if self._phase == "instant_pay":
            ctx = self._pending_instant_pay
            if not ctx or ctx.get("player") != actor_idx:
                return ["pass"]
            exclude = {ctx["card_id"]} if ctx.get("card_id") else None
            actions = ["pass"]
            actions.extend(
                f"pitch {i}" for i in self._legal_pitches(actor_idx, exclude_card_ids=exclude)
            )
            return actions

        if self._phase == "pitch_pay":
            ctx = self._pending_pitch_pay
            if not ctx or ctx.get("player") != actor_idx:
                return ["pass"]
            actions = ["pass"]
            actions.extend(f"pitch {i}" for i in self._legal_pitches(actor_idx))
            return actions

        return ["pass"]

    def _arena_view(self, player_idx: int, reveal: bool) -> dict[str, Any]:
        """Equipment / weapon / hero / arsenal zones for the observation."""
        p = self._players[player_idx]
        equipment = []
        for cid in p.equipment:
            c = self._cards[cid]
            equipment.append(
                {
                    "id": c.id,
                    "name": c.name,
                    "slot": _equipment_slot(c),
                    "defense": c.defense,
                    "keywords": list(c.keywords),
                    "text": c.text,
                    "used": f"equip:{cid}" in p.arena_used,
                }
            )
        hero_ability = next(
            (a for a in effects.parse_activated_abilities(p.hero.ability_text) if a.implemented),
            None,
        )
        wname, wattack, wcost, wcard = self._weapon_stats(player_idx)
        arena = {
            "equipment": equipment,
            "weapon": {
                "name": wname,
                "attack": wattack,
                "cost": wcost,
                "used": p.weapon_used,
                "text": wcard.text if wcard else "",
            },
            "hero_ability_text": p.hero.ability_text,
            "hero_ability_usable": bool(hero_ability),
            "arsenal_size": len(p.arsenal),
        }
        if reveal:
            arena["abilities"] = [
                {
                    "index": i,
                    "source": e["name"],
                    "summary": e["ability"].effect.raw or e["ability"].raw,
                    "cost": e["ability"].cost,
                    "usable": self._ability_usable(player_idx, e),
                }
                for i, e in enumerate(self._ability_list(player_idx))
            ]
            arena["arsenal"] = [self._cards[cid].name for cid in p.arsenal]
        return arena

    def _optional_decision_view(self) -> Optional[dict[str, Any]]:
        """Describe the pending optional decision for the agent, if any."""
        if self._phase != "optional" or not self._pending_optionals:
            return None
        opt = self._pending_optionals[0]
        if opt["player"] != 0:
            return None
        eff = opt["effect"]
        card = self._cards[opt["card_id"]]
        if eff.kind == "banish_combo":
            if re.search(r"deal \d+ arcane damage", (eff.raw or "").lower()):
                desc = f"banish {eff.banish_name} from your graveyard to deal arcane damage"
            else:
                rider = f"+{eff.amount} power" + (" and go again" if eff.go_again else "")
                desc = f"banish {eff.banish_name} from your graveyard for {rider}"
        elif eff.kind == "destroy_item" and (eff.banish_name or "").lower() == "reroll_d6":
            desc = "destroy Gambler's Gloves to reroll the die"
        elif eff.kind in ("damage", "arcane_damage"):
            desc = f"deal {eff.amount} {'arcane ' if eff.kind == 'arcane_damage' else ''}damage"
        elif eff.kind == "power":
            desc = f"give +{eff.amount} power"
        elif eff.kind == "draw":
            desc = f"draw {eff.amount}"
        elif eff.kind == "go_again":
            desc = "gain go again"
        elif eff.kind == "boost":
            desc = "banish top of deck for boost (Mechanologist: go again)"
        elif eff.kind in ("reload", "stash_hand"):
            desc = "reload: stash a card from hand into arsenal"
        else:
            desc = eff.raw
        return {"card": card.name, "description": desc}

    def _choice_decision_view(self) -> Optional[dict[str, Any]]:
        if self._phase != "choice" or not self._choice_ctx:
            return None
        ctx = self._choice_ctx
        if ctx.get("chooser") != 0:
            return None
        return {
            "prompt": ctx.get("prompt", "Choose a card"),
            "optional": bool(ctx.get("optional")),
            "options": [
                {"index": o["index"], "name": o["name"]} for o in ctx.get("options", [])
            ],
        }

    def _is_terminal(self) -> bool:
        if not self._players:
            return False
        return self._players[0].life <= 0 or self._players[1].life <= 0

    def _normalize_action(self, action: Any) -> str:
        if self._selection_stage and isinstance(action, str):
            return action.strip().lower()
        if isinstance(action, int):
            if self._phase == "optional":
                return "use_optional" if action == 0 else "pass"
            if self._phase == "choice":
                ctx = self._choice_ctx
                if ctx and action < len(ctx.get("options", [])):
                    return f"choose {action}"
                return "pass"
            if self._phase == "opt":
                return "opt_top" if action == 0 else "opt_bottom"
            if self._phase == "action":
                return f"play {action}"
            if self._phase == "defense":
                return f"block {action}"
            if self._phase == "attack_reaction":
                return f"reaction {action}"
            if self._phase == "defense_reaction":
                return f"defreact {action}"
        text = str(action).strip().lower()
        if text in {"pass", "end", "end turn"}:
            return "pass"
        if text in {"weapon", "attack weapon", "weapon attack"}:
            return "weapon"
        if text in {"trapdefend", "trap", "trigger trap"}:
            return "trapdefend"
        for verb in ("banishplay", "gyplay", "arsenalplay", "play", "block", "pitch", "reaction", "defreact", "ability", "stash", "blockgear", "trapdefend", "instant"):
            if text.startswith(verb):
                parts = text.split()
                if verb == "arsenalplay":
                    return "arsenalplay"
                if len(parts) == 2 and parts[1].isdigit():
                    return f"{verb} {parts[1]}"
        return text

    def _record_combat_resolution(
        self,
        combat: CombatState,
        *,
        attacker_idx: int,
        defender_idx: int,
        attack_card: Optional[Card],
        total_power: int,
        total_block: int,
        damage: int,
    ) -> None:
        if combat.is_weapon or not combat.attack_card_id:
            attack_name = combat.source_name or "Weapon"
        elif attack_card is not None:
            attack_name = attack_card.name
        else:
            attack_name = "Attack"
        summary = {
            "attacker": attacker_idx,
            "defender": defender_idx,
            "attack_card": attack_name,
            "attack_power": total_power,
            "total_block": total_block,
            "damage": damage,
            "blocks": [
                self._combat_block_view(block_player, cid, def_val)
                for block_player, cid, def_val in combat.blocks
            ],
        }
        if attacker_idx == 0:
            self._last_combat_summary = summary
            block_text = self._format_combat_blocks_text(summary["blocks"], defender_idx)
            outcome = f"{damage} damage" if damage > 0 else "no damage"
            self._last_event = (
                f"You attacked with {attack_name} ({total_power} power vs {total_block} block) "
                f"→ {outcome}"
                + (f" | Opponent blocked: {block_text}" if block_text else " | Opponent did not block")
            )

    @staticmethod
    def _format_combat_blocks_text(blocks: list[dict[str, Any]], defender_idx: int) -> str:
        defender_blocks = [b for b in blocks if int(b.get("player", -1)) == defender_idx]
        if not defender_blocks:
            return ""
        parts: list[str] = []
        for block in defender_blocks:
            name = block.get("name", "?")
            defense = int(block.get("defense") or 0)
            if block.get("kind") == "equipment":
                slot = block.get("slot") or "gear"
                parts.append(f"{name} [{slot}] (def {defense})")
            else:
                parts.append(f"{name} (def {defense})")
        return ", ".join(parts)

    def _combat_block_view(self, block_player: int, cid: str, defense: int) -> dict[str, Any]:
        card = self._cards[cid]
        player = self._players[block_player]
        if cid in player.equipment:
            kind = "equipment"
            slot = _equipment_slot(card) or ""
        else:
            kind = "hand"
            slot = ""
        return {
            "player": block_player,
            "name": card.name,
            "defense": defense,
            "kind": kind,
            "slot": slot,
        }

    def _observation(self) -> dict[str, Any]:
        if self._selection_stage:
            return {
                "turn": self._turn,
                "format": self._format,
                "stage": "deck_selection",
                "phase": self._phase,
                "active_player": self._active_player,
                "opponent_type": self._opponent_type,
                "deck_options": self._deck_options_for_format(),
                "selected_deck": self._selected_deck_option,
                "matchup": self._selected_opponent_deck_option,
                "legal_actions": self._legal_actions(),
                "last_event": self._last_event,
            }

        agent = self._players[0]
        opp = self._players[1]

        hand_view = []
        for i, cid in enumerate(agent.hand):
            c = self._cards[cid]
            is_attack = "attack_action" in c.card_types
            damage, arcane = _parse_action_damage(c.text, c.power, is_attack)
            elements, fusable = self._fusion_state(0, i, c)
            hand_view.append(
                {
                    "index": i,
                    "id": c.id,
                    "name": c.name,
                    "pitch": c.pitch,
                    "cost": c.cost,
                    "power": c.power,
                    "defense": c.defense,
                    "card_types": list(c.card_types),
                    "keywords": list(c.keywords),
                    "text": c.text,
                    "damage": damage,
                    "arcane": arcane,
                    "fusion_element": elements[0] if elements else None,
                    "fusion_elements": list(elements),
                    "fusable": fusable,
                }
            )

        pending = None
        if self._pending_combat is not None:
            pc = self._pending_combat
            if pc.is_weapon or not pc.attack_card_id:
                attack_name = pc.source_name or "Weapon"
            else:
                attack_name = self._cards[pc.attack_card_id].name
            pending = {
                "attacker": pc.attacker,
                "defender": pc.defender,
                "attack_card": attack_name,
                "attack_power": pc.attack_power + pc.attack_bonus,
                "attack_bonus": pc.attack_bonus,
                "total_block": sum(b[2] for b in pc.blocks),
                "go_again": pc.go_again,
                "dominate": pc.dominate,
                "chain_link": self._combat_chain_links,
                "blocks": [
                    self._combat_block_view(block_player, cid, def_val)
                    for block_player, cid, def_val in pc.blocks
                ],
            }

        return {
            "turn": self._turn,
            "format": self._format,
            "stage": "play",
            "phase": self._phase,
            "flow_stage": self._flow_stage,
            "flow_segment": self._flow_segment_label(),
            "action_phase_player": self._action_phase_player,
            "combat_chain_links": self._combat_chain_links,
            "active_player": self._active_player,
            "opponent_type": self._opponent_type,
            "selected_deck": self._selected_deck_option,
            "matchup": self._selected_opponent_deck_option,
            "agent": {
                "hero": agent.hero.name,
                "life": agent.life,
                "resources": agent.resources,
                "action_points": agent.action_points,
                "deck": len(agent.deck),
                "discard": len(agent.discard),
                "banished": [
                    {"index": i, "name": self._cards[cid].name, "playable": self._can_play_from_banished(0, cid)}
                    for i, cid in enumerate(agent.banished)
                ],
                "tokens": dict(agent.tokens),
                "gold": agent.gold,
                "hand": hand_view,
                "class_state": dict(agent.class_state),
                "arena": self._arena_view(0, reveal=True),
            },
            "opponent": {
                "hero": opp.hero.name,
                "life": opp.life,
                "resources": opp.resources,
                "action_points": opp.action_points,
                "deck": len(opp.deck),
                "discard": len(opp.discard),
                "banished": len(opp.banished),
                "tokens": dict(opp.tokens),
                "gold": opp.gold,
                "hand_size": len(opp.hand),
                "class_state": dict(opp.class_state),
                "arena": self._arena_view(1, reveal=False),
            },
            "pending_combat": pending,
            "last_combat": self._last_combat_summary,
            "last_opponent_turn": self._last_opponent_turn,
            "optional_decision": self._optional_decision_view(),
            "choice_decision": self._choice_decision_view(),
            "legal_actions": self._legal_actions(),
            "last_event": self._last_event,
            "notices": list(self._notices),
        }

    def _estimate_win_probabilities(self, obs: Optional[dict[str, Any]] = None) -> tuple[float, float]:
        """Heuristic win probability estimate from current FaB state.

        Returns ``(agent_win_prob, opponent_win_prob)``.
        """
        if obs is None:
            obs = self._observation()

        if obs.get("stage") == "deck_selection":
            return 0.5, 0.5

        agent = obs.get("agent") if isinstance(obs.get("agent"), dict) else {}
        opp = obs.get("opponent") if isinstance(obs.get("opponent"), dict) else {}

        agent_life = float(agent.get("life", 0.0))
        opp_life = float(opp.get("life", 0.0))

        if opp_life <= 0 < agent_life:
            return 1.0, 0.0
        if agent_life <= 0 < opp_life:
            return 0.0, 1.0

        agent_hand_size = len(agent.get("hand", [])) if isinstance(agent.get("hand"), list) else 0
        opp_hand_size = int(opp.get("hand_size", 0) or 0)
        agent_resources = float(agent.get("resources", 0.0))
        opp_resources = float(opp.get("resources", 0.0))
        agent_ap = float(agent.get("action_points", 0.0))
        opp_ap = float(opp.get("action_points", 0.0))
        agent_deck = float(agent.get("deck", 0.0))
        opp_deck = float(opp.get("deck", 0.0))

        agent_score = (
            1.8 * agent_life
            + 1.0 * agent_hand_size
            + 0.6 * agent_resources
            + 0.8 * agent_ap
            + 0.05 * agent_deck
        )
        opp_score = (
            1.8 * opp_life
            + 1.0 * opp_hand_size
            + 0.6 * opp_resources
            + 0.8 * opp_ap
            + 0.05 * opp_deck
        )

        pending = obs.get("pending_combat")
        if isinstance(pending, dict):
            atk = float(pending.get("attack_power", 0.0) or 0.0)
            blk = float(pending.get("total_block", 0.0) or 0.0)
            net = max(0.0, atk - blk)
            attacker = int(pending.get("attacker", 0) or 0)
            if attacker == 0:
                agent_score += 1.5 * net
            else:
                opp_score += 1.5 * net

        active_player = int(obs.get("active_player", 0) or 0)
        if active_player == 0:
            agent_score += 0.4
        else:
            opp_score += 0.4

        diff = (agent_score - opp_score) / 8.0
        agent_p = 1.0 / (1.0 + math.exp(-diff))
        agent_p = max(0.0, min(1.0, agent_p))
        return agent_p, 1.0 - agent_p

    def _render_text(self) -> str:
        obs = self._observation()
        if obs.get("stage") == "deck_selection":
            lines = [
                "Flesh and Blood (Talishar-inspired)",
                f"Format: {obs['format']} | Stage: deck_selection",
                "Choose a deck:",
            ]
            for item in obs.get("deck_options", []):
                lines.append(f"  - {item['label']} ({item['deck_size']} cards) -> choose_deck {item['key']}")
            lines.append("Legal actions: " + ", ".join(obs.get("legal_actions", [])))
            return "\n".join(lines)

        p_agent, p_opp = self._estimate_win_probabilities(obs)
        lines = [
            "Flesh and Blood (Talishar-inspired)",
            f"Turn: {obs['turn']} | Format: {obs['format']} | Phase: {obs['phase']} | Active: P{obs['active_player']}",
            f"Agent ({obs['agent']['hero']}): life={obs['agent']['life']} hand={len(obs['agent']['hand'])} resources={obs['agent']['resources']} AP={obs['agent']['action_points']}",
            f"Opponent ({obs['opponent']['hero']}): life={obs['opponent']['life']} hand={obs['opponent']['hand_size']} resources={obs['opponent']['resources']} AP={obs['opponent']['action_points']}",
            f"Win % | Agent: {p_agent:.1%}  Opponent: {p_opp:.1%}",
            f"Last event: {obs['last_event']}",
            "Legal actions: " + ", ".join(obs["legal_actions"]),
        ]
        if obs["pending_combat"]:
            lines.append(
                "Combat: "
                f"{obs['pending_combat']['attack_card']} "
                f"atk={obs['pending_combat']['attack_power']} "
                f"block={obs['pending_combat']['total_block']}"
            )
        return "\n".join(lines)
